1	// Nexus canvas engine — framework-free. Renders the spider-web project network with Canvas 2D.
2	// World space: core at (0,0). Camera maps world → screen: s = (w - cam) * k + viewport/2.
3	import {
4	  forceCollide, forceLink, forceManyBody, forceRadial, forceSimulation,
5	  type Simulation, type SimulationLinkDatum, type SimulationNodeDatum,
6	} from 'd3-force';
7	import type { Graph, GraphNode } from '@/lib/types';
8	
9	export type NodeKind = 'core' | 'project' | 'ghost' | 'sub' | 'branch' | 'topic';
10	export type NodeStatus = 'idle' | 'running' | 'error';
11	/** Satellites orbit a project (sub-projects, branches, topics) or a sub-project (its branches/topics). */
12	export type SatKind = 'sub' | 'branch' | 'topic';
13	
14	export interface SimNode extends SimulationNodeDatum {
15	  id: string; kind: NodeKind; data?: GraphNode; r: number; ringR: number;
16	  color: string; rgb: [number, number, number]; status: NodeStatus; activity: number;
17	  phase: number; flash: number; ripples: number[]; pinned: boolean; label: string;
18	  x: number; y: number;
19	  /** satellites: the node this one orbits */
20	  owner?: SimNode;
21	  /** satellite slot among its owner's satellites of the same kind */
22	  slot?: number; slots?: number;
23	  /** owners: fan-out amount 0..1 (animated); hover hysteresis deadline (engine time) */
24	  expand: number; holdUntil: number;
25	  /** satellites: current visual scale/alpha derived from the owner's expand */
26	  vis: number;
27	}
28	export const isSat = (n: SimNode | null | undefined): boolean => !!n && (n.kind === 'sub' || n.kind === 'branch' || n.kind === 'topic');
29	interface Strand { a: SimNode; b: SimNode; kind: string; phase: number; core: boolean; len: number; cx: number; cy: number; sat?: boolean }
30	interface Pulse { s: Strand; t: number; speed: number; dir: 1 | -1; rgb: [number, number, number]; size: number }
31	interface Star { x: number; y: number; z: number; tw: number; s: number }
32	
33	export interface EngineCallbacks {
34	  onHover?: (n: SimNode | null) => void;
35	  onOpen?: (n: SimNode) => void; // click on a project node
36	  onGhost?: () => void; // click on "+ New project"
37	  onCameraIdle?: () => void;
38	}
39	
40	const POS_KEY = 'nx.nexus.pos.v1';
41	const CORE_R = 30;
42	/** semantic zoom: satellites fan out past this camera scale */
43	const ZOOM_OPEN = 1.45;
44	const VIOLET: [number, number, number] = [177, 75, 255];
45	const MAX_PULSES = 450;
46	const TAU = Math.PI * 2;
47	
48	function hexToRgb(h: string): [number, number, number] {
49	  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(h?.trim() || '');
50	  if (!m) return [255, 62, 138];
51	  let s = m[1];
52	  if (s.length === 3) s = s.split('').map((c) => c + c).join('');
53	  const n = parseInt(s, 16);
54	  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
55	}
56	const rgba = (c: [number, number, number], a: number) => `rgba(${c[0]},${c[1]},${c[2]},${a})`;
57	const PINK: [number, number, number] = [255, 62, 138];
58	const HOT: [number, number, number] = [255, 111, 174];
59	const RED: [number, number, number] = [255, 77, 109];
60	const WARM: [number, number, number] = [255, 138, 92];
61	
62	// deterministic rng
63	function mulberry(seed: number) {
64	  return () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
65	}
66	function hashStr(s: string) { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
67	
68	function loadPositions(): Record<string, { x: number; y: number }> {
69	  try { return JSON.parse(localStorage.getItem(POS_KEY) || '{}') || {}; } catch { return {}; }
70	}
71	function savePositions(p: Record<string, { x: number; y: number }>) {
72	  try { localStorage.setItem(POS_KEY, JSON.stringify(p)); } catch { /* ignore */ }
73	}
74	
75	export class NexusEngine {
76	  private canvas: HTMLCanvasElement;
77	  private ctx: CanvasRenderingContext2D;
78	  private cb: EngineCallbacks;
79	  private dpr = 1; private W = 0; private H = 0;
80	  private raf = 0; private last = 0; private time = 0;
81	  private running = false;
82	  private reduced: boolean;
83	  private dirty = true;
84	
85	  nodes: SimNode[] = [];
86	  /** satellites (not part of the force simulation; positioned around their owner every frame) */
87	  sats: SimNode[] = [];
88	  private satStrands: Strand[] = [];
89	  private satsOf = new Map<string, SimNode[]>();
90	  private branchIdx = new Map<string, SimNode>(); // `${projectId}|${branch}` → node
91	  private showSats = false;
92	  /** camera scale of the last fit(): semantic zoom opens satellites only when zoomed in beyond it */
93	  private fitK = 1;
94	  private byId = new Map<string, SimNode>();
95	  private strands: Strand[] = [];
96	  private nodeStrands = new Map<string, Strand[]>();
97	  private pulses: Pulse[] = [];
98	  private stars: Star[] = [];
99	  private sim: Simulation<SimNode, SimulationLinkDatum<SimNode>>;
100	  private positions = loadPositions();
101	
102	  // camera
103	  cam = { x: 0, y: 0, k: 1 };
104	  private target = { x: 0, y: 0, k: 1 };
105	  private tween: { from: { x: number; y: number; k: number }; to: { x: number; y: number; k: number }; t0: number; dur: number; done?: () => void } | null = null;
106	  private outerR = 300;
107	  private webPath: Path2D | null = null;
108	  private bgCache: HTMLCanvasElement | null = null;
109	  private spokePath: Path2D | null = null;
110	
111	  // interaction
112	  hovered: SimNode | null = null;
113	  private focusId: string | null = null; // externally highlighted (list hover)
114	  /** Nexus Chat: #mentioned projects (strand from the core lit in the project's color) */
115	  private highlight = new Set<string>();
116	  /** Nexus Chat: a multi-project run is active (core spins up) */
117	  private nexusActive = false;
118	  private insetB = 0;
119	  private pointers = new Map<number, { x: number; y: number }>();
120	  private drag: { mode: 'pan' | 'node' | 'pinch'; node?: SimNode; sx: number; sy: number; moved: boolean; camX: number; camY: number; dist?: number; k0?: number } | null = null;
121	  private hoverEl: HTMLElement | null = null;
122	  private icons = new Map<string, HTMLImageElement>();
123	  private sprites = new Map<string, HTMLCanvasElement>();
124	  private ro: ResizeObserver;
125	  private disposed = false;
126	
127	  constructor(canvas: HTMLCanvasElement, cb: EngineCallbacks = {}) {
128	    this.canvas = canvas;
129	    this.ctx = canvas.getContext('2d', { alpha: false })!;
130	    this.cb = cb;
131	    this.reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
132	    this.sim = forceSimulation<SimNode>([]).stop();
133	    this.ro = new ResizeObserver(() => this.resize());
134	    this.ro.observe(canvas);
135	    this.resize();
136	    this.makeStars();
137	    this.bind();
138	    document.addEventListener('visibilitychange', this.onVis);
139	    this.start();
140	  }
141	
142	  // ---------- public API ----------
143	  setIcons(map: Map<string, HTMLImageElement>) { this.icons = map; this.dirty = true; }
144	  setHoverElement(el: HTMLElement | null) { this.hoverEl = el; }
145	  setFocus(id: string | null) { this.focusId = id; this.dirty = true; }
146	  /** Highlight projects (by id) — e.g. the #mentions while typing in Nexus Chat. */
147	  setHighlight(ids: string[]) {
148	    const next = new Set(ids);
149	    if (next.size === this.highlight.size && [...next].every((x) => this.highlight.has(x))) return;
150	    for (const id of next) if (!this.highlight.has(id)) { const n = this.nodeOf(id); if (n) n.flash = Math.max(n.flash, 0.6); }
151	    this.highlight = next; this.dirty = true;
152	  }
153	  setNexusActive(on: boolean) { if (this.nexusActive !== on) { this.nexusActive = on; this.dirty = true; } }
154	
155	  /** A Nexus run touched a project: light flows from the core out to it (and on to the sub-project / branch). */
156	  nexusPulse(projectId: string, intensity = 0.8, branch?: string | null) {
157	    const n = this.nodeOf(projectId);
158	    const core = this.byId.get('core');
159	    if (!n || !core) return;
160	    const ring = n.owner && !this.byId.has(n.id) ? (n.owner.owner ?? n.owner) : n; // ring node that carries the core strand
161	    const targets = [n, ...(ring !== n ? [ring] : [])];
162	    for (const x of targets) { x.flash = Math.min(1.5, x.flash + 0.5 + intensity * 0.4); x.activity = Math.min(1, x.activity + intensity * 0.05); }
163	    core.flash = Math.min(1.2, core.flash + 0.3);
164	    if (this.reduced) { this.dirty = true; return; }
165	    const st = (this.nodeStrands.get(core.id) || []).find((q) => q.a === ring || q.b === ring);
166	    const count = 1 + Math.round(intensity * 3);
167	    if (st) for (let i = 0; i < count; i++) this.spawn(st, st.a === core ? 1 : -1, n.rgb, 1 + intensity, i * -0.09);
168	    // continue along the satellite silk to a sub-project / branch
169	    const b = branch ? this.branchIdx.get(`${projectId}|${branch}`) : undefined;
170	    for (const x of [n, b]) {
171	      if (!x?.owner) continue;
172	      const ss = this.satStrands.find((q) => q.b === x);
173	      if (ss) for (let i = 0; i < count; i++) this.spawn(ss, 1, x.rgb, 0.8 + intensity * 0.5, -0.35 + i * -0.08);
174	    }
175	    n.ripples.push(0);
176	    if (n.ripples.length > 4) n.ripples.shift();
177	  }
178	
179	  setGraph(g: Graph) {
180	    const prev = this.byId;
181	    const nodes: SimNode[] = [];
182	    const core = prev.get('core') || this.mkNode('core', 'core', undefined);
183	    core.fx = 0; core.fy = 0; core.x = 0; core.y = 0;
184	    nodes.push(core);
185	
186	    // ring nodes: top-level projects (and sub-projects whose parent isn't visible); the rest become satellites
187	    const all = g.nodes.filter((n) => n.id !== 'core' && n.kind !== 'core');
188	    const ids = new Set(all.map((n) => n.id));
189	    const projects = all.filter((n) => !n.kind || n.kind === 'project' || (n.kind === 'subproject' && !(n.parentId && ids.has(n.parentId))));
190	    // most recently active → inner rings
191	    const sorted = [...projects].sort((a, b) => (Date.parse(b.lastActiveAt || '') || 0) - (Date.parse(a.lastActiveAt || '') || 0));
192	    let ring = 1, inRing = 0, cap = 6;
193	    const rings: { n: GraphNode; ring: number; idx: number; cap: number }[] = [];
194	    for (const n of sorted) {
195	      rings.push({ n, ring, idx: inRing, cap });
196	      if (++inRing >= cap) { ring++; inRing = 0; cap = 6 + (ring - 1) * 5; }
197	    }
198	    const ringR = (i: number) => 170 + (i - 1) * 120;
199	    const ringCount = new Map<number, number>();
200	    for (const x of rings) ringCount.set(x.ring, (ringCount.get(x.ring) || 0) + 1);
201	    for (const { n, ring: ri, idx } of rings) {
202	      let sn = prev.get(n.id);
203	      const count = ringCount.get(ri) || 1;
204	      if (!sn) {
205	        sn = this.mkNode(n.id, 'project', n);
206	        const off = (hashStr('ring' + ri) % 1000) / 1000 * TAU;
207	        const a = off + (idx / count) * TAU;
208	        const saved = this.positions[n.id];
209	        if (saved) { sn.x = saved.x; sn.y = saved.y; sn.fx = saved.x; sn.fy = saved.y; sn.pinned = true; }
210	        else { sn.x = Math.cos(a) * ringR(ri); sn.y = Math.sin(a) * ringR(ri); }
211	      }
212	      sn.data = n; sn.label = n.name; sn.color = n.color || '#ff3e8a'; sn.rgb = hexToRgb(sn.color);
213	      sn.status = n.status || 'idle'; sn.activity = Math.max(0, Math.min(1, n.activity || 0));
214	      sn.ringR = ringR(ri);
215	      sn.r = 15 + sn.activity * 5;
216	      nodes.push(sn);
217	    }
218	    const maxRing = rings.length ? rings[rings.length - 1].ring : 0;
219	    const ghost = prev.get('__ghost') || this.mkNode('__ghost', 'ghost', undefined);
220	    ghost.ringR = ringR(maxRing + 1) - (maxRing ? 40 : 30);
221	    if (!prev.get('__ghost')) {
222	      const a = -Math.PI * 0.25;
223	      ghost.x = Math.cos(a) * ghost.ringR; ghost.y = Math.sin(a) * ghost.ringR;
224	    }
225	    nodes.push(ghost);
226	
227	    this.nodes = nodes;
228	    this.byId = new Map(nodes.map((n) => [n.id, n]));
229	    this.outerR = ringR(Math.max(1, maxRing)) + 150;
230	
231	    // ---- satellites: sub-projects, then branches / topics of projects and sub-projects ----
232	    const prevSats = new Map(this.sats.map((n) => [n.id, n]));
233	    const sats: SimNode[] = [];
234	    const satsOf = new Map<string, SimNode[]>();
235	    const kindOf = (n: GraphNode): SatKind | null => (n.kind === 'subproject' ? 'sub' : n.kind === 'branch' ? 'branch' : n.kind === 'topic' ? 'topic' : null);
236	    const order: SatKind[] = ['sub', 'branch', 'topic'];
237	    const lookup = (id: string) => this.byId.get(id) || sats.find((x) => x.id === id);
238	    for (const k of order) {
239	      for (const n of all) {
240	        if (kindOf(n) !== k || !n.parentId) continue;
241	        if (k === 'sub' && this.byId.has(n.id)) continue; // promoted to a ring node
242	        const owner = lookup(n.parentId);
243	        if (!owner || (k === 'sub' && owner.kind !== 'project')) continue;
244	        let sn = prevSats.get(n.id);
245	        if (!sn || sn.kind !== k) {
246	          sn = this.mkNode(n.id, k, n);
247	          sn.x = owner.x; sn.y = owner.y;
248	        }
249	        sn.data = n; sn.owner = owner; sn.label = n.name;
250	        sn.color = n.color || owner.color; sn.rgb = hexToRgb(sn.color);
251	        sn.status = n.status || 'idle'; sn.activity = Math.max(0, Math.min(1, n.activity || 0));
252	        sn.r = k === 'sub' ? 10 + sn.activity * 2 : k === 'branch' ? 5.5 : 2.6;
253	        sats.push(sn);
254	        const arr = satsOf.get(owner.id) || [];
255	        arr.push(sn);
256	        satsOf.set(owner.id, arr);
257	      }
258	    }
259	    for (const arr of satsOf.values()) {
260	      for (const k of order) {
261	        const same = arr.filter((x) => x.kind === k);
262	        same.forEach((x, i) => { x.slot = i; x.slots = same.length; });
263	      }
264	    }
265	    this.sats = sats;
266	    this.satsOf = satsOf;
267	    this.branchIdx = new Map();
268	    for (const sn of sats) if (sn.kind === 'branch' && sn.data?.branch && sn.owner) this.branchIdx.set(`${sn.owner.id}|${sn.data.branch}`, sn);
269	
270	    // strands: core spokes + graph links
271	    const strands: Strand[] = [];
272	    const seen = new Set<string>();
273	    const add = (a: SimNode | undefined, b: SimNode | undefined, kind: string, core: boolean) => {
274	      if (!a || !b || a === b) return;
275	      const key = a.id < b.id ? a.id + '|' + b.id : b.id + '|' + a.id;
276	      if (seen.has(key)) return; seen.add(key);
277	      strands.push({ a, b, kind, core, phase: (hashStr(key) % 1000) / 1000 * TAU, len: 0, cx: 0, cy: 0 });
278	    };
279	    for (const n of nodes) if (n.kind === 'project') add(core, n, 'core', true);
280	    add(core, ghost, 'ghost', true);
281	    for (const l of g.links) {
282	      const s = typeof l.source === 'string' ? l.source : (l.source as any)?.id;
283	      const t = typeof l.target === 'string' ? l.target : (l.target as any)?.id;
284	      add(this.byId.get(s), this.byId.get(t), l.kind, s === 'core' || t === 'core');
285	    }
286	    this.strands = strands;
287	    const prevSat = new Map(this.satStrands.map((x) => [x.b.id, x]));
288	    this.satStrands = sats.map((sn) => {
289	      const old = prevSat.get(sn.id);
290	      if (old && old.a === sn.owner && old.b === sn) return old;
291	      return { a: sn.owner!, b: sn, kind: 'sat-' + sn.kind, core: false, sat: true, phase: (hashStr(sn.id) % 1000) / 1000 * TAU, len: 0, cx: sn.x, cy: sn.y };
292	    });
293	    this.nodeStrands = new Map();
294	    for (const s of [...strands, ...this.satStrands]) {
295	      for (const n of [s.a, s.b]) { const arr = this.nodeStrands.get(n.id) || []; arr.push(s); this.nodeStrands.set(n.id, arr); }
296	    }
297	    const live = new Set([...strands, ...this.satStrands]);
298	    this.pulses = this.pulses.filter((p) => live.has(p.s));
299	    if (!prevSats.size && sats.length) this.layoutSats(0, true);
300	    this.buildWeb();
301	
302	    // forces
303	    const projLinks = strands.filter((s) => !s.core).map((s) => ({ source: s.a, target: s.b }));
304	    this.sim = forceSimulation<SimNode>(nodes)
305	      .force('charge', forceManyBody<SimNode>().strength((n) => (n.kind === 'core' ? -400 : -90)).distanceMax(400))
306	      .force('collide', forceCollide<SimNode>().radius((n) => this.collideR(n)).strength(0.9))
307	      .force('radial', forceRadial<SimNode>((n) => n.ringR, 0, 0).strength((n) => (n.kind === 'core' ? 0 : 0.6)))
308	      .force('link', forceLink<SimNode, SimulationLinkDatum<SimNode>>(projLinks).distance(150).strength(0.03))
309	      .alphaDecay(0.035)
310	      .stop();
311	    const fresh = nodes.some((n) => !prev.has(n.id));
312	    if (fresh) { this.sim.alpha(1); for (let i = 0; i < 220; i++) this.sim.tick(); }
313	    this.sim.alpha(this.reduced ? 0 : 0.15);
314	    if (prev.size === 0) this.fit(true);
315	    this.dirty = true;
316	  }
317	
318	  /** Update one project's (or sub-project's / branch's) status (from run_status). */
319	  setStatus(projectId: string, status: NodeStatus, branch?: string | null) {
320	    const p = this.nodeOf(projectId);
321	    if (!p) return;
322	    const targets = [p];
323	    if (branch) { const b = this.branchIdx.get(`${projectId}|${branch}`); if (b) targets.push(b); }
324	    for (const n of targets) {
325	      if (n.status !== status && status === 'running') n.flash = 1;
326	      n.status = status;
327	    }
328	    this.dirty = true;
329	  }
330	
331	  /** graph_pulse: fire light along all strands of a node — starting at the branch / sub-project satellite if any. */
332	  pulse(projectId: string, intensity = 0.5, branch?: string | null) {
333	    const n = this.nodeOf(projectId);
334	    if (!n) return;
335	    const chain: SimNode[] = [];
336	    const b = branch ? this.branchIdx.get(`${projectId}|${branch}`) : undefined;
337	    if (b) chain.push(b);
338	    chain.push(n);
339	    if (n.owner) chain.push(n.owner); // sub-project → its parent
340	    for (const x of chain) {
341	      x.flash = Math.min(1.5, x.flash + 0.6 + intensity * 0.4);
342	      x.activity = Math.min(1, x.activity + intensity * 0.05);
343	    }
344	    if (this.reduced) { this.dirty = true; return; }
345	    const count = 1 + Math.round(intensity * 4);
346	    // satellite strands: light flows from the satellite inward to its owner
347	    for (const x of chain) {
348	      if (!x.owner) continue;
349	      const st = this.satStrands.find((q) => q.b === x);
350	      if (st) for (let i = 0; i < count; i++) this.spawn(st, -1, x.rgb, 0.8 + intensity * 0.6, i * -0.08);
351	    }
352	    const hub = chain[chain.length - 1]!;
353	    hub.ripples.push(0);
354	    if (hub.ripples.length > 4) hub.ripples.shift();
355	    for (const s of this.nodeStrands.get(hub.id) || []) {
356	      if (s.sat) continue;
357	      for (let i = 0; i < count; i++) this.spawn(s, s.a === hub ? 1 : -1, hub.rgb, 1 + intensity, i * -0.08);
358	    }
359	  }
360	
361	  /** Show all satellites (sub-projects, branches, topics) regardless of zoom/hover. */
362	  setSatellites(on: boolean) {
363	    if (this.showSats === on) return;
364	    this.showSats = on;
365	    // make room for fanned-out sub-projects
366	    const c = this.sim.force('collide') as ReturnType<typeof forceCollide<SimNode>> | undefined;
367	    if (c) { c.radius((n) => this.collideR(n)); if (!this.reduced) this.sim.alpha(Math.max(this.sim.alpha(), 0.25)); }
368	    this.dirty = true;
369	  }
370	
371	  private nodeOf(id: string): SimNode | undefined {
372	    return this.byId.get(id) || this.sats.find((x) => x.id === id);
373	  }
374	  private collideR(n: SimNode): number {
375	    if (n.kind === 'core') return CORE_R + 50;
376	    const subs = (this.satsOf.get(n.id) || []).some((x) => x.kind === 'sub');
377	    return n.r + 28 + (this.showSats && subs ? 58 : 0);
378	  }
379	
380	  /** Position satellites around their owners; animate the fan-out (semantic zoom / hover / toggle). */
381	  private layoutSats(dt: number, instant = false) {
382	    if (!this.sats.length) return;
383	    const zoomOpen = this.cam.k > Math.max(ZOOM_OPEN, this.fitK * 1.35);
384	    const hov = this.hovered;
385	    const focus = this.focusId ? this.byId.get(this.focusId) : null;
386	    const f = instant || this.reduced ? 1 : 1 - Math.exp(-dt * 7);
387	    const clock = performance.now() / 1000; // wall clock (engine time is frozen with reduced motion)
388	    for (const [ownerId, list] of this.satsOf) {
389	      const owner = this.byId.get(ownerId) || list[0]?.owner;
390	      if (!owner || owner.kind === 'sub') continue; // sub-projects follow their parent below
391	      const engaged = hov === owner || hov?.owner === owner || hov?.owner?.owner === owner || focus === owner;
392	      if (engaged) owner.holdUntil = clock + 0.9;
393	      const target = this.showSats || zoomOpen || engaged || owner.holdUntil > clock ? 1 : 0;
394	      if (Math.abs(target - owner.expand) > 0.001) { owner.expand += (target - owner.expand) * f; this.dirty = true; } else owner.expand = target;
395	    }
396	    const t = this.reduced ? 0 : this.time;
397	    for (const sn of this.sats) {
398	      const o = sn.owner!;
399	      if (o.kind === 'sub') o.expand = o.owner!.expand;
400	      const e = o.kind === 'sub' ? o.expand * o.vis : o.expand;
401	      sn.vis = e;
402	      const anchor = o.kind === 'sub' ? o.owner! : null;
403	      // "outward": away from the core (or from the parent for a sub-project's own satellites)
404	      const out = anchor ? Math.atan2(o.y - anchor.y, o.x - anchor.x) : Math.hypot(o.x, o.y) > 1 ? Math.atan2(o.y, o.x) : -Math.PI / 2;
405	      const i = sn.slot ?? 0, n = Math.max(1, sn.slots ?? 1);
406	      let a: number, dist: number;
407	      if (sn.kind === 'sub') {
408	        const spread = Math.min(2.5, 0.72 * (n - 1));
409	        a = out + (n > 1 ? -spread / 2 + (i * spread) / (n - 1) : 0) + Math.sin(t * 0.4 + sn.phase) * 0.02;
410	        dist = o.r + 4 + e * (64 + (n > 3 ? 12 : 0));
411	      } else {
412	        // branches / topics orbit on an arc that skips the bottom sector, where the owner's label sits
413	        const span = TAU - 1.3;
414	        const start = Math.PI / 2 + 0.65;
415	        const sway = Math.sin(t * (sn.kind === 'branch' ? 0.35 : 0.25) + sn.phase) * (0.35 / n);
416	        a = start + (span * (i + (sn.kind === 'branch' ? 0.5 : 0.25))) / n + sway;
417	        dist = sn.kind === 'branch' ? o.r + 4 + e * (o.kind === 'sub' ? 12 : 19) : o.r + 3 + e * (o.kind === 'sub' ? 4.5 : 8);
418	      }
419	      sn.x = o.x + Math.cos(a) * dist;
420	      sn.y = o.y + Math.sin(a) * dist;
421	    }
422	  }
423	
424	  zoomBy(f: number) { this.zoomAt(this.W / 2, this.H / 2, f); }
425	
426	  fit(instant = false) {
427	    const pad = 0.9;
428	    const vh = Math.max(160, this.H - this.insetB);
429	    const k = Math.max(0.25, Math.min(1.6, (Math.min(this.W, vh) / 2 / (this.outerR - 60)) * pad));
430	    this.fitK = k;
431	    // keep the web centered in the part of the canvas not covered by a bottom panel (Nexus Chat)
432	    this.animateTo({ x: 0, y: this.insetB / (2 * k), k }, instant ? 0 : 600);
433	  }
434	
435	  /** Height (px) of a panel covering the bottom of the canvas; re-fits the camera when it changes. */
436	  setBottomInset(px: number) {
437	    if (Math.abs(px - this.insetB) < 8) return;
438	    this.insetB = Math.max(0, px);
439	    this.fit();
440	  }
