442	  resetLayout() {
443	    this.positions = {}; savePositions({});
444	    for (const n of this.nodes) if (n.kind !== 'core') { n.fx = null; n.fy = null; n.pinned = false; }
445	    this.sim.alpha(0.9);
446	    if (this.reduced) for (let i = 0; i < 200; i++) this.sim.tick();
447	    this.dirty = true;
448	  }
