450	  /** Camera fly-in to a node, then call done. */
451	  flyTo(id: string, done: () => void) {
452	    const n = this.byId.get(id);
453	    if (!n || this.reduced) { done(); return; }
454	    this.setHover(null);
455	    this.drag = null;
456	    this.animateTo({ x: n.x, y: n.y, k: Math.max(3.2, this.cam.k * 3) }, 650, done);
457	  }
