459	  /** QA/debug: screen positions of the busiest satellite owner and its visible satellites. */
460	  probe() {
461	    let best: SimNode | null = null, bn = 0;
462	    for (const [id, list] of this.satsOf) { const o = this.byId.get(id); if (o && list.length > bn) { best = o; bn = list.length; } }
463	    if (!best) return null;
464	    const vis = (k: string) => { const x = this.sats.find((q) => (q.owner === best || q.owner?.owner === best) && q.kind === k && q.vis > 0.6); return x ? { ...this.screenPos(x), id: x.id } : null; };
465	    const r = this.canvas.getBoundingClientRect();
466	    const off = (p: { x: number; y: number; id: string } | null) => (p ? { ...p, x: p.x + r.left, y: p.y + r.top } : null);
467	    return { project: off({ ...this.screenPos(best), id: best.id }), branch: off(vis('branch')), sub: off(vis('sub')), topic: off(vis('topic')) };
468	  }
