483	  // ---------- internals ----------
484	  private mkNode(id: string, kind: NodeKind, data?: GraphNode): SimNode {
485	    const color = kind === 'core' ? '#ff3e8a' : data?.color || '#ff3e8a';
486	    return {
487	      id, kind, data, r: kind === 'core' ? CORE_R : kind === 'ghost' ? 15 : 16, ringR: 0, color, rgb: hexToRgb(color),
488	      status: data?.status || 'idle', activity: data?.activity || 0, phase: (hashStr(id) % 1000) / 1000 * TAU,
489	      flash: 0, ripples: [], pinned: false, label: kind === 'ghost' ? 'New project' : data?.name || 'core', x: 0, y: 0,
490	      expand: 0, holdUntil: 0, vis: 1,
