494	  private makeStars() {
495	    const rnd = mulberry(1337);
496	    this.stars = Array.from({ length: 240 }, () => ({ x: rnd() * 4000, y: rnd() * 4000, z: 0.04 + rnd() * rnd() * 0.35, tw: rnd() * TAU, s: rnd() < 0.08 ? 1.6 : rnd() < 0.4 ? 1.1 : 0.7 }));
497	  }
498	
499	  private buildWeb() {
500	    // Orb-web: radial spokes + sagging capture rings with slight organic jitter.
501	    const rnd = mulberry(424242);
502	    const spokes = 28;
503	    const R = this.outerR;
504	    const angles = Array.from({ length: spokes }, (_, i) => (i / spokes) * TAU + (rnd() - 0.5) * 0.08);
505	    const sp = new Path2D();
506	    for (const a of angles) { sp.moveTo(Math.cos(a) * 46, Math.sin(a) * 46); sp.lineTo(Math.cos(a) * R * 1.35, Math.sin(a) * R * 1.35); }
507	    this.spokePath = sp;
508	    const web = new Path2D();
509	    const gap = 46;
510	    for (let r = 64; r < R * 1.25; r += gap * (0.88 + rnd() * 0.24)) {
511	      const pts = angles.map((a) => { const rr = r * (0.97 + rnd() * 0.06); return [Math.cos(a) * rr, Math.sin(a) * rr, rr] as const; });
512	      web.moveTo(pts[0][0], pts[0][1]);
513	      for (let i = 0; i < spokes; i++) {
514	        const p = pts[i], q = pts[(i + 1) % spokes];
515	        const am = (angles[i] + (i === spokes - 1 ? angles[0] + TAU : angles[(i + 1) % spokes])) / 2;
516	        const sag = ((p[2] + q[2]) / 2) * 0.955;
517	        web.quadraticCurveTo(Math.cos(am) * sag, Math.sin(am) * sag, q[0], q[1]);
518	      }
519	    }
520	    this.webPath = web;
521	  }
