523	  private spawn(s: Strand, dir: 1 | -1, rgb: [number, number, number], size = 1, t0 = 0) {
524	    if (this.pulses.length >= MAX_PULSES) this.pulses.shift();
525	    const len = Math.max(60, Math.hypot(s.b.x - s.a.x, s.b.y - s.a.y));
526	    this.pulses.push({ s, t: t0, dir, rgb, size, speed: (150 + Math.random() * 90) / len * (size > 1 ? 1.4 : 1) });
527	  }
