559	  private resize() {
560	    const r = this.canvas.getBoundingClientRect();
561	    this.dpr = Math.min(2, window.devicePixelRatio || 1);
562	    this.W = Math.max(1, r.width); this.H = Math.max(1, r.height);
563	    this.canvas.width = Math.round(this.W * this.dpr);
564	    this.canvas.height = Math.round(this.H * this.dpr);
565	    this.bgCache = null;
566	    this.dirty = true;
567	    if (this.reduced && this.running) this.frame(performance.now());
