570	  private onVis = () => { if (document.hidden) this.stop(); else this.start(); };
571	  private start() {
572	    if (this.running || this.disposed) return;
573	    this.running = true; this.last = performance.now();
574	    this.raf = requestAnimationFrame(this.loop);
