583	  private animateTo(to: { x: number; y: number; k: number }, dur: number, done?: () => void) {
584	    if (dur <= 0 || this.reduced) {
585	      this.cam = { ...to }; this.target = { ...to }; this.tween = null; this.dirty = true; done?.(); return;
586	    }
587	    this.tween = { from: { ...this.cam }, to, t0: performance.now(), dur, done };
588	    this.target = { ...to };
589	  }
590	
591	  private zoomAt(sx: number, sy: number, f: number) {
592	    const k0 = this.target.k;
593	    const k1 = Math.max(0.2, Math.min(5, k0 * f));
594	    // keep world point under cursor fixed (relative to target camera)
595	    const wx = (sx - this.W / 2) / k0 + this.target.x;
596	    const wy = (sy - this.H / 2) / k0 + this.target.y;
597	    this.target = { k: k1, x: wx - (sx - this.W / 2) / k1, y: wy - (sy - this.H / 2) / k1 };
598	    this.tween = null;
599	    if (this.reduced) this.cam = { ...this.target };
600	    this.dirty = true;
601	  }
602	
603	  private toWorld(sx: number, sy: number) {
604	    return { x: (sx - this.W / 2) / this.cam.k + this.cam.x, y: (sy - this.H / 2) / this.cam.k + this.cam.y };
605	  }
606	
607	  private hit(sx: number, sy: number): SimNode | null {
608	    const w = this.toWorld(sx, sy);
609	    let best: SimNode | null = null, bd = Infinity;
610	    // satellites sit on top of the web once fanned out
611	    for (const n of this.sats) {
612	      if (n.vis < 0.55) continue;
613	      const d = Math.hypot(n.x - w.x, n.y - w.y);
614	      const lim = n.r * (0.4 + 0.6 * n.vis) + (n.kind === 'topic' ? 5 : 6) / this.cam.k;
615	      if (d < lim && d < bd) { bd = d; best = n; }
616	    }
617	    if (best) return best;
618	    for (const n of this.nodes) {
619	      const d = Math.hypot(n.x - w.x, n.y - w.y);
620	      const lim = n.r + 8 / this.cam.k;
621	      if (d < lim && d < bd) { bd = d; best = n; }
622	    }
623	    return best;
624	  }
625	
626	  private setHover(n: SimNode | null) {
627	    if (n === this.hovered) return;
628	    this.hovered = n;
629	    this.canvas.style.cursor = n && n.kind !== 'core' ? 'pointer' : this.drag?.mode === 'pan' ? 'grabbing' : 'grab';
630	    this.cb.onHover?.(n && (n.kind === 'project' || isSat(n)) ? n : null);
631	    this.dirty = true;
632	  }
633	
634	  // ----- events -----
635	  private bind() {
636	    const c = this.canvas;
637	    c.addEventListener('pointerdown', this.onDown);
638	    window.addEventListener('pointermove', this.onMove);
639	    window.addEventListener('pointerup', this.onUp);
640	    window.addEventListener('pointercancel', this.onUp);
641	    c.addEventListener('wheel', this.onWheel, { passive: false });
642	    c.addEventListener('dblclick', this.onDbl);
643	    c.addEventListener('pointerleave', this.onLeave);
644	    c.style.cursor = 'grab';
645	    c.style.touchAction = 'none';
646	  }
647	  private unbind() {
648	    const c = this.canvas;
649	    c.removeEventListener('pointerdown', this.onDown);
650	    window.removeEventListener('pointermove', this.onMove);
651	    window.removeEventListener('pointerup', this.onUp);
652	    window.removeEventListener('pointercancel', this.onUp);
653	    c.removeEventListener('wheel', this.onWheel);
654	    c.removeEventListener('dblclick', this.onDbl);
655	    c.removeEventListener('pointerleave', this.onLeave);
656	  }
657	  private local(e: { clientX: number; clientY: number }) {
658	    const r = this.canvas.getBoundingClientRect();
659	    return { x: e.clientX - r.left, y: e.clientY - r.top };
660	  }
661	  private onDown = (e: PointerEvent) => {
662	    const p = this.local(e);
663	    this.pointers.set(e.pointerId, p);
664	    try { this.canvas.setPointerCapture(e.pointerId); } catch { /* noop */ }
665	    if (this.pointers.size === 2) {
666	      const [a, b] = [...this.pointers.values()];
667	      this.drag = { mode: 'pinch', sx: (a.x + b.x) / 2, sy: (a.y + b.y) / 2, moved: true, camX: this.cam.x, camY: this.cam.y, dist: Math.hypot(a.x - b.x, a.y - b.y), k0: this.target.k };
668	      return;
669	    }
670	    const n = this.hit(p.x, p.y);
671	    this.tween = null;
672	    if (n && n.kind !== 'core' && !isSat(n)) this.drag = { mode: 'node', node: n, sx: p.x, sy: p.y, moved: false, camX: 0, camY: 0 };
673	    else { this.drag = { mode: 'pan', node: isSat(n) && n ? n : undefined, sx: p.x, sy: p.y, moved: false, camX: this.target.x, camY: this.target.y }; this.canvas.style.cursor = 'grabbing'; }
674	  };
675	  private onMove = (e: PointerEvent) => {
676	    const p = this.local(e);
677	    if (this.pointers.has(e.pointerId)) this.pointers.set(e.pointerId, p);
678	    const d = this.drag;
679	    if (!d) {
680	      if (e.target === this.canvas) this.setHover(this.hit(p.x, p.y));
681	      return;
682	    }
683	    if (d.mode === 'pinch' && this.pointers.size >= 2) {
684	      const [a, b] = [...this.pointers.values()];
685	      const dist = Math.hypot(a.x - b.x, a.y - b.y);
686	      const f = dist / (d.dist || dist);
687	      const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
688	      const k1 = Math.max(0.2, Math.min(5, (d.k0 || 1) * f));
689	      this.zoomAt(mx, my, k1 / this.target.k);
690	      this.cam = { ...this.target };
691	      return;
692	    }
693	    const dx = p.x - d.sx, dy = p.y - d.sy;
694	    if (!d.moved && Math.hypot(dx, dy) > 4) d.moved = true;
695	    if (!d.moved) return;
696	    if (d.mode === 'pan') {
697	      this.target.x = d.camX - dx / this.cam.k; this.target.y = d.camY - dy / this.cam.k;
698	      this.cam.x = this.target.x; this.cam.y = this.target.y;
699	      this.dirty = true;
700	    } else if (d.mode === 'node' && d.node) {
701	      const w = this.toWorld(p.x, p.y);
702	      d.node.fx = w.x; d.node.fy = w.y; d.node.x = w.x; d.node.y = w.y;
703	      if (!this.reduced) this.sim.alphaTarget(0.12).alpha(Math.max(this.sim.alpha(), 0.12));
704	      this.setHover(d.node);
705	      this.dirty = true;
706	    }
707	  };
708	  private onUp = (e: PointerEvent) => {
709	    this.pointers.delete(e.pointerId);
710	    const d = this.drag;
711	    if (!d) return;
712	    if (d.mode === 'pinch') { if (this.pointers.size === 0) this.drag = null; return; }
713	    this.drag = null;
714	    this.canvas.style.cursor = this.hovered ? 'pointer' : 'grab';
715	    if (d.mode === 'pan' && d.node && !d.moved) { this.cb.onOpen?.(d.node); return; }
716	    if (d.mode === 'node' && d.node) {
717	      if (d.moved) {
718	        d.node.pinned = true;
719	        if (d.node.kind === 'project') { this.positions[d.node.id] = { x: Math.round(d.node.x), y: Math.round(d.node.y) }; savePositions(this.positions); }
720	        this.sim.alphaTarget(0);
721	      } else if (d.node.kind === 'ghost') this.cb.onGhost?.();
722	      else if (d.node.kind === 'project') this.cb.onOpen?.(d.node);
723	    }
724	  };
725	  private onLeave = () => { if (!this.drag) this.setHover(null); };
726	  private onWheel = (e: WheelEvent) => {
727	    e.preventDefault();
728	    const p = this.local(e);
729	    const delta = e.deltaMode === 1 ? e.deltaY * 16 : e.deltaY;
730	    this.zoomAt(p.x, p.y, Math.exp(-delta * (e.ctrlKey ? 0.01 : 0.0015)));
731	  };
732	  private onDbl = (e: MouseEvent) => {
733	    const p = this.local(e);
734	    const n = this.hit(p.x, p.y);
735	    if (n && (n.kind === 'project' || isSat(n))) return;
736	    this.fit();
737	  };
738	
739	  // ----- frame -----
740	  private frame(now: number) {
741	    const dt = Math.min(0.05, (now - this.last) / 1000);
742	    this.last = now;
743	    const animating = !this.reduced;
744	    if (animating) this.time += dt;
745	
746	    // simulation
747	    if (this.sim.alpha() > this.sim.alphaMin() || (this.sim as any).alphaTarget?.() > 0) {
748	      this.sim.tick(); this.dirty = true;
749	    }
750	
751	    // camera
752	    if (this.tween) {
753	      const u = Math.min(1, (now - this.tween.t0) / this.tween.dur);
754	      const e = u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
755	      const { from, to } = this.tween;
756	      // zoom interpolated geometrically
757	      this.cam.k = from.k * Math.pow(to.k / from.k, e);
758	      this.cam.x = from.x + (to.x - from.x) * e; this.cam.y = from.y + (to.y - from.y) * e;
759	      this.dirty = true;
760	      if (u >= 1) { const d = this.tween.done; this.tween = null; d?.(); }
761	    } else {
762	      const f = 1 - Math.exp(-dt * 12);
763	      const dx = this.target.x - this.cam.x, dy = this.target.y - this.cam.y, dk = this.target.k - this.cam.k;
764	      if (Math.abs(dx) + Math.abs(dy) > 0.01 || Math.abs(dk) > 0.0005) {
765	        this.cam.x += dx * f; this.cam.y += dy * f; this.cam.k += dk * f; this.dirty = true;
766	      }
767	    }
768	
769	    this.layoutSats(dt);
770	    if (animating) {
771	      this.updatePulses(dt);
772	      for (const n of this.nodes) {
773	        if (n.flash > 0) n.flash = Math.max(0, n.flash - dt * 0.9);
774	        n.ripples = n.ripples.map((r) => r + dt).filter((r) => r < 1.6);
775	      }
776	      for (const n of this.sats) if (n.flash > 0) n.flash = Math.max(0, n.flash - dt * 0.9);
777	      this.dirty = true;
778	    }
779	    if (!this.dirty) return;
780	    this.dirty = false;
781	    this.draw();
782	  }
783	
784	  private updatePulses(dt: number) {
785	    // ambient + status-driven spawning
786	    const density = Math.min(1, 120 / Math.max(1, this.strands.length));
787	    for (const s of this.strands) {
788	      if (s.kind === 'ghost') continue;
789	      const run = (s.a.status === 'running' ? 1 : 0) + (s.b.status === 'running' ? 1 : 0);
790	      const act = (s.a.activity + s.b.activity) / 2;
791	      const rate = ((s.core ? 0.035 : 0.02) + act * 0.08) * density + run * 1.1 * Math.max(0.35, density);
792	      if (Math.random() < rate * dt) {
793	        const src = s.b.status === 'running' ? s.b : s.a.status === 'running' ? s.a : Math.random() < 0.5 ? s.a : s.b;
794	        const rgb = src.kind === 'core' ? HOT : src.rgb;
795	        this.spawn(s, src === s.a ? 1 : -1, rgb, run ? 1.15 : 0.8);
796	      }
797	    }
798	    for (const s of this.satStrands) {
799	      if (s.b.status !== 'running' || s.b.vis < 0.3) continue;
800	      if (Math.random() < 1.4 * dt) this.spawn(s, -1, s.b.kind === 'branch' ? VIOLET : s.b.rgb, 0.75);
801	    }
802	    const out: Pulse[] = [];
