814	  private strandGeom(s: Strand) {
815	    const ax = s.a.x, ay = s.a.y, bx = s.b.x, by = s.b.y;
816	    const len = Math.hypot(bx - ax, by - ay);
817	    // catenary-ish sag (gravity +y) with a gentle sway
818	    const sway = this.reduced ? 0 : Math.sin(this.time * 0.7 + s.phase) * 0.012;
819	    const sag = len * (0.07 + sway);
820	    const nx = -(by - ay) / (len || 1), ny = (bx - ax) / (len || 1);
821	    // pick the normal that points "down"-ish, blend with pure gravity
822	    const sgn = ny >= 0 ? 1 : -1;
823	    s.cx = (ax + bx) / 2 + (nx * sgn * 0.6) * sag;
824	    s.cy = (ay + by) / 2 + (ny * sgn * 0.6 + 0.4) * sag;
825	    s.len = len;
826	  }
