1001	    for (const s of this.satStrands) {
1002	      const v = s.b.vis;
1003	      if (v < 0.04) continue;
1004	      const on = hov === s.b || hov === s.a;
1005	      const run = s.b.status === 'running';
1006	      if (v > 0.97 && !on && !run) { batch[s.b.kind]!.push(s); continue; }
