function ProjectList({ open, onClose, nodes, statusOf, onFocus, onOpen, roles, descs }: {
  open: boolean; onClose: () => void; nodes: GraphNode[]; statusOf: (n: GraphNode) => NodeStatus;
  onFocus: (id: string | null) => void; onOpen: (n: GraphNode) => void; roles: Record<string, string>; descs: Record<string, string>;
}) {
  const [q, setQ] = useState('');
  const list = useMemo(() => {
    const qq = q.trim().toLowerCase();
    return nodes
      .filter((n) => !qq || n.name.toLowerCase().includes(qq) || (n.slug || '').includes(qq) || (descs[n.id] || '').toLowerCase().includes(qq))
      .sort((a, b) => (statusOf(b) === 'running' ? 1 : 0) - (statusOf(a) === 'running' ? 1 : 0) || (Date.parse(b.lastActiveAt || '') || 0) - (Date.parse(a.lastActiveAt || '') || 0));
  }, [nodes, q, statusOf, descs]);
  return (
    <aside
      aria-label="Projects" aria-hidden={!open}
      className={cn('absolute bottom-3 left-3 top-3 z-10 flex w-[312px] flex-col rounded-2xl nx-glass transition-all duration-300',
        open ? 'translate-x-0 opacity-100' : 'pointer-events-none -translate-x-[110%] opacity-0')}
    >
      <div className="flex items-center gap-2 px-3 pt-3">
        <Orbit size={14} className="text-pink" />
        <div className="flex-1 font-display text-[10.5px] font-semibold tracking-[0.24em]">PROJECTS</div>
        <IconButton size="xs" icon={<X size={14} />} label="Close list" onClick={onClose} tabIndex={open ? 0 : -1} />
      </div>
      <div className="p-3 pb-2">
        <Input inputSize="sm" icon={<Search size={13} />} placeholder="Filter projects…" value={q} onChange={(e) => setQ(e.target.value)} tabIndex={open ? 0 : -1} />
      </div>
      <ul className="flex-1 overflow-y-auto px-1.5 pb-2">
        {list.length === 0 && <li className="px-3 py-6 text-center text-xs text-muted">{nodes.length ? 'No matches' : 'No projects yet'}</li>}
        {list.map((n) => {
          const s = statusOf(n);
          return (
            <li key={n.id}>
              <button
                tabIndex={open ? 0 : -1}
                onMouseEnter={() => onFocus(n.id)} onMouseLeave={() => onFocus(null)} onFocus={() => onFocus(n.id)} onBlur={() => onFocus(null)}
                onClick={() => onOpen(n)}
                className="group flex w-full items-center gap-2.5 rounded-lg px-2 py-2 text-left transition-colors hover:bg-pink/[0.07] focus-visible:bg-pink/[0.07]"
              >
                {n.kind === 'subproject' && <CornerDownRight size={12} className="-mr-1 shrink-0 text-muted/50" />}
                <ProjectBadge name={n.icon} color={n.color} size={n.kind === 'subproject' ? 22 : 28} />
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-1.5">
                    <span className="truncate text-sm text-ink/95 group-hover:text-ink">{n.name}</span>
                    {s !== 'idle' && <StatusDot status={s} size={6} />}
                  </div>
                  <div className="truncate text-[11px] text-muted">{descs[n.id] || n.slug}</div>
                </div>
                <div className="flex flex-col items-end gap-0.5">
                  <span className="font-mono text-[10px] text-muted">{timeAgo(n.lastActiveAt)}</span>
                  {roles[n.id] && <span className="text-[9.5px] uppercase tracking-wider text-muted/60">{roles[n.id]}</span>}
                </div>
              </button>
            </li>
          );
        })}
      </ul>
      <div className="border-t border-line/70 p-2">
        <Button size="sm" variant="ghost" block icon={<Plus size={14} />} onClick={() => useUI.getState().setNewProject(true)} tabIndex={open ? 0 : -1}>New project</Button>
      </div>
    </aside>
  );
}

