"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { usePathname } from "next/navigation";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import type { MbServer } from "@/lib/modbuilder/install";
import { CYRUS_DEFAULT_MODEL, CYRUS_STATUS_LABEL, cyrusModel, type CyrusModelId } from "@/lib/cyrus/models";
import { groupProjects, projectOf, viewMeta, versionNumber, type CyrusProject } from "@/lib/cyrus/projects";
import { CYRUS_TEMPLATES, CYRUS_TEMPLATE_CATS } from "@/lib/cyrus/templates";
import { estimate } from "@/lib/cyrus/estimate";
import type { CyrusMeta } from "@/lib/cyrus/meta";
import { Composer, type ComposerHandle, type ComposerSubmit } from "./Composer";
import { Nebula, type NebulaMode } from "./Nebula";
import { Project } from "./Project";
import { ProjectPalette, ShortcutsModal } from "./Modals";
import { CyIcon, CyrusMark } from "./icons";
import { Glyph } from "./Glyph";
import { PROGRESS } from "./Stage";
import { ago, isTypingTarget } from "./util";

const BASE = "/dashboard/cyrus";
type Toast = { id: string; text: string; buildId: string; ok: boolean };

export function CyrusApp({ initialBuilds, servers, online, firstName }: { initialBuilds: ModBuildView[]; servers: MbServer[]; online: boolean; firstName: string }) {
  const [builds, setBuilds] = useState<ModBuildView[]>(initialBuilds);
  const [netErr, setNetErr] = useState(false);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [modal, setModal] = useState<null | "palette" | "keys">(null);
  const [railQ, setRailQ] = useState("");
  const pathname = usePathname();
  const selectedId = pathname.startsWith(BASE + "/") ? decodeURIComponent(pathname.slice(BASE.length + 1).split("/")[0]) : null;
  const homeComposer = useRef<ComposerHandle>(null);
  const changeComposer = useRef<ComposerHandle>(null);

  const projects = useMemo(() => groupProjects(builds), [builds]);
  const project = projectOf(projects, selectedId);
  const viewing = project?.builds.find((b) => b.id === selectedId) ?? null;
  const inflight = builds.filter((b) => !isTerminal(b.status)).length;

  const go = useCallback((id: string | null) => {
    const url = id ? `${BASE}/${id}` : BASE;
    if (url !== window.location.pathname) window.history.pushState(null, "", url);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }, []);
  const openProject = useCallback((p: CyrusProject) => go((p.running ?? p.head ?? p.latest).id), [go]);

  const viewingRef = useRef<string | null>(null);
  viewingRef.current = selectedId;
  const upsert = useCallback((list: ModBuildView[]) => {
    setBuilds((cur) => {
      const m = new Map(cur.map((b) => [b.id, b]));
      for (const b of list) {
        const prev = m.get(b.id);
        if (prev && !isTerminal(prev.status) && isTerminal(b.status) && viewingRef.current !== b.id) {
          setToasts((t) => [...t.filter((x) => x.buildId !== b.id), { id: b.id + b.status, buildId: b.id, ok: b.status === "succeeded", text: b.status === "succeeded" ? `${b.pluginName || "Your mod"} is ready` : `${b.pluginName || "A build"} didn't build` }]);
        }
        m.set(b.id, { ...prev, ...b });
      }
      return Array.from(m.values());
    });
  }, []);

  // Poll every in-flight build (each GET also syncs it from the build service).
  useEffect(() => {
    const ids = builds.filter((b) => !isTerminal(b.status)).map((b) => b.id);
    if (!ids.length) return;
    let stop = false;
    const t = setTimeout(async () => {
      const res = await Promise.all(ids.map((id) => fetch(`/api/mod-builder/builds/${id}`, { cache: "no-store" }).then((r) => (r.ok ? r.json() : null)).catch(() => null)));
      if (stop) return;
      upsert(res.filter(Boolean).map((j) => j.build as ModBuildView));
      setNetErr(res.some((r) => !r));
    }, document.visibilityState === "hidden" ? 9000 : 2500);
    return () => { stop = true; clearTimeout(t); };
  }, [builds, upsert]);

  const refreshAll = useCallback(async () => {
    const r = await fetch("/api/mod-builder/builds", { cache: "no-store" }).catch(() => null);
    if (r?.ok) { const j = await r.json(); upsert(j.builds as ModBuildView[]); }
  }, [upsert]);
  // Builds started in another tab show up here too.
  useEffect(() => { const t = setInterval(refreshAll, 30_000); return () => clearInterval(t); }, [refreshAll]);

  // Toasts fade after a while.
  useEffect(() => {
    if (!toasts.length) return;
    const t = setTimeout(() => setToasts((x) => x.slice(1)), 7000);
    return () => clearTimeout(t);
  }, [toasts]);
  useEffect(() => { if (selectedId) setToasts((t) => t.filter((x) => x.buildId !== selectedId)); }, [selectedId]);

  const create = useCallback(async (body: Record<string, unknown>): Promise<string | null> => {
    try {
      const r = await fetch("/api/mod-builder/builds", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) return j.error || "Cyrus couldn't start this build.";
      upsert([j.build]);
      go(j.build.id);
      return null;
    } catch { return "We couldn't reach Nxeon. Check your connection and try again."; }
  }, [go, upsert]);

  const patch = useCallback(async (rootId: string, p: Record<string, unknown>): Promise<string | null> => {
    // Optimistic: update the root build's meta locally first.
    setBuilds((cur) => cur.map((b) => (b.id === rootId ? { ...b, cyrus: { ...viewMeta(b), ...cleanPatch(p) } } : b)));
    try {
      const r = await fetch(`/api/mod-builder/projects/${rootId}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(p) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { refreshAll(); return j.error || "Couldn't save."; }
      setBuilds((cur) => cur.map((b) => (b.id === rootId ? { ...b, cyrus: j.meta } : b)));
      return null;
    } catch { return "Couldn't save."; }
  }, [refreshAll]);

  const duplicate = useCallback(async (p: CyrusProject) => {
    const src = p.head ?? p.latest;
    return create({ prompt: (p.builds[0] ?? src).prompt, mcVersion: src.mcVersion, model: viewMeta(src).model ?? CYRUS_DEFAULT_MODEL });
  }, [create]);

  const newMod = useCallback((prefill?: { text: string; model?: CyrusModelId }) => {
    go(null);
    setTimeout(() => { if (prefill) homeComposer.current?.setText(prefill.text, prefill.model); else homeComposer.current?.focus(); }, 80);
  }, [go]);

  // Global shortcuts.
  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if (e.key === "Escape" && modal) { setModal(null); return; }
      if (isTypingTarget(e.target) || e.metaKey || e.ctrlKey || e.altKey || modal) return;
      const comp = selectedId ? changeComposer.current : homeComposer.current;
      const idx = project ? projects.findIndex((p) => p.rootId === project.rootId) : -1;
      switch (e.key) {
        case "n": case "N": e.preventDefault(); newMod(); break;
        case "p": case "P": e.preventDefault(); setModal("palette"); break;
        case "?": e.preventDefault(); setModal("keys"); break;
        case "/": e.preventDefault(); comp?.focus(); break;
        case "v": case "V": e.preventDefault(); comp?.toggleVoice(); break;
        case "[": if (projects.length) { e.preventDefault(); openProject(projects[(idx - 1 + projects.length) % projects.length]); } break;
        case "]": if (projects.length) { e.preventDefault(); openProject(projects[(idx + 1) % projects.length]); } break;
      }
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [modal, selectedId, project, projects, newMod, openProject]);

  const running = projects.filter((p) => p.running);
  const railList = railQ.trim() ? projects.filter((p) => p.title.toLowerCase().includes(railQ.trim().toLowerCase())) : projects;

  return (
    <div className="cy-root">
      <div className="cy-frame">
        <header className="cy-top">
          <button type="button" className="cy-brand" onClick={() => newMod()} aria-label="Cyrus home">
            <CyrusMark size={30} />
            <span className="cy-word">Cyrus</span>
          </button>
          <span className="cy-preview">Preview</span>
          <span className={`cy-online ${online ? "up" : "down"}`} title={online ? "The builder is online" : "The builder is offline"}><i />{online ? "Builder online" : "Builder offline"}</span>
          {netErr && <span className="cy-online down"><i />Reconnecting…</span>}
          <span className="ml-auto flex items-center gap-1.5">
            {running.length > 0 && <span className="cy-running" title="Builds in progress"><i className="cy-pulse" />{running.length}<span className="cy-run-w"> weaving</span></span>}
            <button type="button" className="cy-topbtn" onClick={() => setModal("palette")} title="Switch project (P)"><CyIcon name="layers" size={15} /><span>Projects</span><kbd>P</kbd></button>
            <button type="button" className="cy-topbtn icon" onClick={() => setModal("keys")} title="Keyboard shortcuts (?)" aria-label="Keyboard shortcuts"><CyIcon name="keyboard" size={16} /></button>
          </span>
        </header>

        {/* phones: a horizontal project switcher replaces the rail */}
        <div className="cy-mswitch">
          <button type="button" className={`cy-mchip new ${!selectedId ? "on" : ""}`} onClick={() => newMod()}><CyIcon name="plus" size={13} /> New</button>
          {projects.slice(0, 12).map((p) => (
            <button key={p.rootId} type="button" className={`cy-mchip ${project?.rootId === p.rootId ? "on" : ""}`} onClick={() => openProject(p)}>
              <Glyph id={p.rootId} size={20} state={p.running ? "running" : p.head ? "ok" : "bad"} progress={p.running ? PROGRESS[p.running.status] : undefined} />
              <span className="truncate">{p.title}</span>
            </button>
          ))}
        </div>

        <div className="cy-body">
          <aside className="cy-rail" aria-label="Projects">
            <button type="button" className={`cy-new ${!selectedId ? "on" : ""}`} onClick={() => newMod()}>
              <CyIcon name="plus" size={15} strokeWidth={2} /> New mod <kbd>N</kbd>
            </button>
            {projects.length > 5 && (
              <label className="cy-rail-q"><CyIcon name="search" size={13} /><input value={railQ} onChange={(e) => setRailQ(e.target.value)} placeholder="Filter projects" aria-label="Filter projects" /></label>
            )}
            {projects.length === 0 && <p className="cy-rail-empty">Your mods appear here. Several can build at once.</p>}
            <RailGroup title="Weaving now" list={railList.filter((p) => p.running)} current={project?.rootId} onPick={openProject} />
            <RailGroup title="Favourites" list={railList.filter((p) => !p.running && p.meta.favourite)} current={project?.rootId} onPick={openProject} />
            <RailGroup title={running.length || projects.some((p) => p.meta.favourite) ? "All projects" : "Projects"} list={railList.filter((p) => !p.running && !p.meta.favourite)} current={project?.rootId} onPick={openProject} />
          </aside>

          <main className="cy-main">
            {selectedId && project && viewing ? (
              <Project key={project.rootId} project={project} viewing={viewing} servers={servers} inflight={inflight} onOpen={go} onCreate={create}
                       onPatch={patch} onDuplicate={duplicate} onRefresh={refreshAll} composerRef={changeComposer} onNewMod={newMod} />
            ) : selectedId ? (
              <div className="cy-empty"><CyrusMark size={40} /><p className="cy-empty-t">That build isn&apos;t here.</p><button type="button" className="cy-btn" onClick={() => newMod()}>Back to Cyrus</button></div>
            ) : (
              <Home firstName={firstName} projects={projects} inflight={inflight} online={online} onCreate={create} onOpen={openProject} composerRef={homeComposer} />
            )}
          </main>
        </div>
      </div>

      <div className="cy-toasts" aria-live="polite">
        {toasts.map((t) => (
          <button key={t.id} type="button" className={`cy-toast ${t.ok ? "ok" : "bad"}`} onClick={() => { go(t.buildId); setToasts((x) => x.filter((y) => y.id !== t.id)); }}>
            <span className="cy-toast-orb"><CyIcon name={t.ok ? "check" : "warn"} size={13} strokeWidth={2.2} /></span>
            <span>{t.text}</span><span className="cy-toast-go">Open <CyIcon name="chevr" size={12} /></span>
          </button>
        ))}
      </div>

      {modal === "palette" && <ProjectPalette projects={projects} onClose={() => setModal(null)} onPick={(p) => { setModal(null); openProject(p); }} onNew={() => { setModal(null); newMod(); }} />}
      {modal === "keys" && <ShortcutsModal onClose={() => setModal(null)} />}
    </div>
  );
}

function cleanPatch(p: Record<string, unknown>): Partial<CyrusMeta> {
  const o: Record<string, unknown> = { ...p };
  for (const k of Object.keys(o)) if (o[k] === null) delete o[k];
  return o as Partial<CyrusMeta>;
}

function RailGroup({ title, list, current, onPick }: { title: string; list: CyrusProject[]; current?: string; onPick: (p: CyrusProject) => void }) {
  if (!list.length) return null;
  return (
    <div className="cy-rail-g">
      <div className="cy-rail-h">{title}<span>{list.length}</span></div>
      {list.map((p) => {
        const r = p.running;
        const b = r ?? p.head ?? p.latest;
        return (
          <button key={p.rootId} type="button" className={`cy-ri ${current === p.rootId ? "on" : ""} ${r ? "run" : ""}`} onClick={() => onPick(p)}>
            <Glyph id={p.rootId} size={34} state={r ? "running" : p.head ? "ok" : "bad"} progress={r ? PROGRESS[r.status] : undefined} />
            <span className="flex min-w-0 flex-1 flex-col">
              <span className="cy-ri-t">{p.title}{p.meta.favourite && <CyIcon name="star" size={10} fill className="cy-amber ml-1 inline" />}</span>
              <span className={`cy-ri-s st-${b.status}`}>
                {r ? <><i className="cy-dot st-run" />{CYRUS_STATUS_LABEL[r.status]} · v{versionNumber(p, r.id)}</>
                  : <>v{versionNumber(p, b.id)} · <span suppressHydrationWarning>{ago(p.updatedAt)}</span>{!p.head && <> · <span className="bad">{CYRUS_STATUS_LABEL.failed}</span></>}</>}
              </span>
            </span>
          </button>
        );
      })}
    </div>
  );
}

function Home({ firstName, projects, inflight, online, onCreate, onOpen, composerRef }: {
  firstName: string; projects: CyrusProject[]; inflight: number; online: boolean;
  onCreate: (b: Record<string, unknown>) => Promise<string | null>; onOpen: (p: CyrusProject) => void; composerRef: React.RefObject<ComposerHandle | null>;
}) {
  const [act, setAct] = useState<{ typing: boolean; listening: boolean; level: number }>({ typing: false, listening: false, level: 0 });
  const onActivity = useCallback((a: { typing: boolean; listening: boolean; level: number }) => {
    setAct((cur) => (cur.typing === a.typing && cur.listening === a.listening && Math.abs(cur.level - a.level) < 0.04 ? cur : a));
  }, []);
  const [cat, setCat] = useState<(typeof CYRUS_TEMPLATE_CATS)[number]>("All");
  const mode: NebulaMode = act.listening ? "listening" : act.typing ? "typing" : "idle";
  const submit = (s: ComposerSubmit) => onCreate({ prompt: s.text, mcVersion: s.mcVersion, model: s.model, attachmentIds: s.attachmentIds });
  const disabledReason = !online ? "The builder is offline right now. You can write your idea; building resumes shortly." : inflight >= 2 ? "Two builds are running. Cyrus builds two at a time in the preview." : null;
  const tpl = CYRUS_TEMPLATES.filter((t) => cat === "All" || t.cat === cat);
  const running = projects.filter((p) => p.running);

  return (
    <div className="cy-home">
      <section className={`cy-hero mode-${mode}`}>
        <div className="cy-hero-bg" aria-hidden="true">
          <div className="cy-aurora"><i /><i /><i /></div>
          <Nebula mode={mode} energy={act.listening ? act.level : act.typing ? 0.5 : 0} seed={11} />
        </div>
        <div className="cy-hero-in">
          <span className="cy-eyebrow"><CyrusMark size={16} /> AI mod studio</span>
          <h1 className="cy-h1">Speak a mod <span className="cy-grad">into existence.</span></h1>
          <p className="cy-hero-sub">Tell Cyrus what you want on your server, {firstName}. Watch it plan, write, compile, fix and safety-check a real plugin, then change it as often as you like.</p>
          <Composer ref={composerRef} kind="new" defaultModel={CYRUS_DEFAULT_MODEL} disabledReason={disabledReason} submitLabel="Build with Cyrus" onActivity={onActivity} onSubmit={submit}
                    placeholder="Describe your mod… e.g. “A /shop menu where players spend coins they earn from killing mobs.” Paste a screenshot or press the mic to talk." />
          <ul className="cy-promise">
            <li><CyIcon name="code" size={13} /> Real Java source, yours to keep</li>
            <li><CyIcon name="retry" size={13} /> Fixes its own errors</li>
            <li><CyIcon name="shield" size={13} /> Safety-checked</li>
            <li><CyIcon name="layers" size={13} /> Every change is a new version</li>
          </ul>
        </div>
      </section>

      {running.length > 0 && (
        <section className="cy-sec">
          <div className="cy-sec-h"><h2>Weaving now</h2><span className="cy-sub">Builds keep going if you leave. Up to two at once.</span></div>
          <div className="cy-cards">
            {running.map((p) => <ProjectCard key={p.rootId} p={p} onOpen={onOpen} />)}
          </div>
        </section>
      )}

      <section className="cy-sec">
        <div className="cy-sec-h">
          <h2>Start from a template</h2>
          <div className="cy-cats" role="tablist">
            {CYRUS_TEMPLATE_CATS.map((c) => <button key={c} type="button" role="tab" aria-selected={cat === c} className={`cy-cat ${cat === c ? "on" : ""}`} onClick={() => setCat(c)}>{c}</button>)}
          </div>
        </div>
        <div className="cy-tpls">
          {tpl.map((t) => {
            const e = estimate(t.prompt, t.model);
            const m = cyrusModel(t.model);
            return (
              <button key={t.id} type="button" className="cy-tpl" onClick={() => { composerRef.current?.setText(t.prompt, t.model); window.scrollTo({ top: 0, behavior: "smooth" }); }}>
                <span className="cy-tpl-top">
                  <Glyph id={`tpl-${t.id}`} size={30} />
                  <span className="cy-tpl-cat">{t.cat}</span>
                </span>
                <b className="cy-tpl-t">{t.title}</b>
                <span className="cy-tpl-d">{t.blurb}</span>
                <span className="cy-tpl-f">
                  <span className="cy-model-dot" style={{ background: m.hue }} /> {m.name}
                  <span className="cy-tpl-sep">·</span> ~{e.minutes[0]}–{e.minutes[1]} min
                  <span className="cy-tpl-use">Use <CyIcon name="chevr" size={12} /></span>
                </span>
              </button>
            );
          })}
        </div>
      </section>

      {projects.filter((p) => !p.running).length > 0 && (
        <section className="cy-sec cy-recent">
          <div className="cy-sec-h"><h2>Your mods</h2><span className="cy-sub">{projects.length} project{projects.length === 1 ? "" : "s"} · press P to jump to one</span></div>
          <div className="cy-cards">
            {projects.filter((p) => !p.running).slice(0, 9).map((p) => <ProjectCard key={p.rootId} p={p} onOpen={onOpen} />)}
          </div>
        </section>
      )}
      <p className="cy-legal">Cyrus builds Paper server plugins (Java). Not an official Minecraft product. Not approved by or associated with Mojang or Microsoft.</p>
    </div>
  );
}

function ProjectCard({ p, onOpen }: { p: CyrusProject; onOpen: (p: CyrusProject) => void }) {
  const r = p.running;
  const b = r ?? p.head ?? p.latest;
  const s = p.head?.result?.summary?.tagline;
  return (
    <button type="button" className={`cy-pc ${r ? "run" : ""}`} onClick={() => onOpen(p)}>
      <span className="cy-pc-top">
        <Glyph id={p.rootId} size={40} state={r ? "running" : p.head ? "ok" : "bad"} progress={r ? PROGRESS[r.status] : undefined} />
        <span className="flex min-w-0 flex-1 flex-col">
          <b className="cy-pc-t">{p.title}</b>
          <span className={`cy-ri-s st-${b.status}`}>{r ? <><i className="cy-dot st-run" />{CYRUS_STATUS_LABEL[r.status]}</> : <>v{versionNumber(p, b.id)} · {CYRUS_STATUS_LABEL[b.status]}</>}</span>
        </span>
        {p.meta.favourite && <CyIcon name="star" size={13} fill className="cy-amber" />}
      </span>
      <span className="cy-pc-d">{s || p.latest.changeRequest || p.latest.prompt}</span>
      {r && <span className="cy-pc-bar"><i style={{ width: `${Math.round((PROGRESS[r.status] ?? 0.1) * 100)}%` }} /></span>}
      {!r && p.head && <span className="cy-badge sm"><CyIcon name="sparkle" size={9} /> Cyrus</span>}
    </button>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import type { MbServer } from "@/lib/modbuilder/install";
import { CYRUS_DEFAULT_MODEL, CYRUS_STATUS_LABEL, cyrusModel, type CyrusModelId } from "@/lib/cyrus/models";
import { viewMeta, versionNumber, type CyrusProject } from "@/lib/cyrus/projects";
import { CYRUS_NOTES_MAX, type ProjectPatch } from "@/lib/cyrus/meta";
import { Composer, type ComposerHandle, type ComposerSubmit } from "./Composer";
import { CodePane, visibleSrc } from "./CodePane";
import { Failure, Overview } from "./Overview";
import { Stage, PROGRESS } from "./Stage";
import { Versions } from "./Versions";
import { InstallModal } from "./Modals";
import { CyIcon } from "./icons";
import { Glyph } from "./Glyph";
import { ago, bytes, dur, isTypingTarget } from "./util";

export type Tab = "overview" | "code" | "versions" | "notes";

export function Project({ project, viewing, servers, inflight, onOpen, onCreate, onPatch, onDuplicate, onRefresh, composerRef, onNewMod }: {
  project: CyrusProject;
  viewing: ModBuildView;
  servers: MbServer[];
  inflight: number;
  onOpen: (id: string) => void;
  onCreate: (body: Record<string, unknown>) => Promise<string | null>;
  onPatch: (rootId: string, patch: ProjectPatch) => Promise<string | null>;
  onDuplicate: (p: CyrusProject) => Promise<string | null>;
  onRefresh: () => void;
  composerRef: React.RefObject<ComposerHandle | null>;
  onNewMod: (prefill?: { text: string; model?: CyrusModelId }) => void;
}) {
  const b = viewing;
  const running = !isTerminal(b.status);
  const n = versionNumber(project, b.id);
  const isHead = project.head?.id === b.id;
  const [tab, setTab] = useState<Tab>("overview");
  const [modal, setModal] = useState<null | "install">(null);
  const [menu, setMenu] = useState(false);
  const [rename, setRename] = useState(false);
  const [branchFrom, setBranchFrom] = useState<string | null>(null);
  const meta = project.meta;
  const bm = viewMeta(b);

  // A build that just finished while being watched gets the reveal + the Code tab nudge.
  const wasRunning = useRef(running);
  const [justDone, setJustDone] = useState<string | null>(null);
  useEffect(() => {
    if (wasRunning.current && !running) { setJustDone(b.id); if (b.status === "succeeded") setTab("overview"); }
    wasRunning.current = running;
  }, [running, b.id, b.status]);
  useEffect(() => { setBranchFrom(null); setMenu(false); }, [b.id]);

  // 1-4 switch tabs, F favourites.
  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if (isTypingTarget(e.target) || e.metaKey || e.ctrlKey || e.altKey || document.querySelector(".cy-modal-back")) return;
      const t = ({ "1": "overview", "2": "code", "3": "versions", "4": "notes" } as Record<string, Tab>)[e.key];
      if (t) { setTab(t); e.preventDefault(); }
      if (e.key === "f" || e.key === "F") { onPatch(project.rootId, { favourite: !meta.favourite }); e.preventDefault(); }
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [project.rootId, meta.favourite, onPatch]);

  const base = branchFrom ? project.builds.find((x) => x.id === branchFrom) ?? null : b.status === "succeeded" ? b : project.head;
  const baseN = base ? versionNumber(project, base.id) : 0;
  const disabledReason = project.running ? `Cyrus is building v${versionNumber(project, project.running.id)}. Ask for the next change when it's done.`
    : !base ? "This mod hasn't built yet. Try again first, then ask for changes."
    : inflight >= 2 ? "Two builds are running. Cyrus builds two at a time in the preview." : null;

  const submitChange = async (s: ComposerSubmit) => {
    if (!base) return "Nothing to change yet.";
    return onCreate({ baseBuildId: base.id, changeRequest: s.text, model: s.model, attachmentIds: s.attachmentIds });
  };
  const retry = async () => onCreate(b.baseBuildId
    ? { baseBuildId: b.baseBuildId, changeRequest: b.changeRequest, model: bm.model }
    : { prompt: b.prompt, mcVersion: b.mcVersion, model: bm.model });
  const editRetry = () => {
    if (b.baseBuildId) { setBranchFrom(b.baseBuildId); composerRef.current?.setText(b.changeRequest || "", bm.model); }
    else onNewMod({ text: b.prompt, model: bm.model });
  };

  const ok = b.status === "succeeded";
  const files = b.result?.files ?? [];
  const parent = b.baseBuildId ? project.builds.find((x) => x.id === b.baseBuildId) ?? null : null;
  const model = cyrusModel(bm.model ?? CYRUS_DEFAULT_MODEL);

  return (
    <div className="cy-project">
      <header className="cy-ph">
        <Glyph id={project.rootId} size={52} state={running ? "running" : ok ? "ok" : "bad"} progress={PROGRESS[b.status]} />
        <div className="flex min-w-0 flex-1 flex-col gap-1.5">
          <div className="cy-ph-row">
            {rename ? (
              <form className="cy-rename" onSubmit={async (e) => { e.preventDefault(); const v = String(new FormData(e.currentTarget).get("t") || ""); await onPatch(project.rootId, { title: v || null }); setRename(false); }}>
                <input name="t" autoFocus defaultValue={project.title} maxLength={60} aria-label="Project name" onBlur={(e) => e.currentTarget.form?.requestSubmit()} onKeyDown={(e) => { if (e.key === "Escape") setRename(false); }} />
              </form>
            ) : (
              <h1 className="cy-ph-t" onDoubleClick={() => setRename(true)} title="Double-click to rename">{project.title}</h1>
            )}
            <button type="button" className={`cy-ib star ${meta.favourite ? "on" : ""}`} aria-pressed={!!meta.favourite} aria-label={meta.favourite ? "Remove from favourites" : "Add to favourites"} title="Favourite (F)"
                    onClick={() => onPatch(project.rootId, { favourite: !meta.favourite })}>
              <CyIcon name="star" size={16} fill={!!meta.favourite} />
            </button>
            {ok && <span className="cy-badge" title="Built with Cyrus"><CyIcon name="sparkle" size={10} /> Cyrus</span>}
          </div>
          <div className="cy-ph-meta">
            <span className={`cy-pill st-${b.status}`}><i />{CYRUS_STATUS_LABEL[b.status]}</span>
            <span className="cy-chip">v{n}{project.builds.length > 1 ? ` of ${project.builds.length}` : ""}</span>
            <span className="cy-chip">Minecraft · Paper {b.mcVersion}</span>
            <span className="cy-chip"><span className="cy-model-dot" style={{ background: model.hue }} />{model.name}</span>
            {ok && b.version && <span className="cy-chip dim">plugin {b.version}</span>}
            {ok && <span className="cy-meta-t">built in {dur(b.durationMs)}{b.attempts > 1 ? ` · fixed itself ${b.attempts - 1}×` : " · first try"}</span>}
            {!ok && <span className="cy-meta-t" suppressHydrationWarning>started {ago(b.createdAt)}</span>}
          </div>
        </div>
        <div className="cy-ph-act">
          {ok && (
            <>
              <a href={`/api/mod-builder/builds/${b.id}/jar`} className="cy-btn primary" download><CyIcon name="download" size={14} /> <span>Download</span></a>
              <button type="button" className="cy-btn" onClick={() => setModal("install")}><CyIcon name="server" size={14} /> <span>Install</span></button>
            </>
          )}
          {running && (
            <button type="button" className="cy-btn" onClick={async () => { await fetch(`/api/mod-builder/builds/${b.id}/cancel`, { method: "POST" }); onRefresh(); }}>
              <CyIcon name="stop" size={13} /> Cancel
            </button>
          )}
          <span className="relative">
            <button type="button" className="cy-ib lg" aria-label="More" aria-expanded={menu} onClick={() => setMenu((v) => !v)}><CyIcon name="more" size={18} strokeWidth={2.4} /></button>
            {menu && (
              <span className="cy-menu" role="menu" onMouseLeave={() => setMenu(false)}>
                <button type="button" role="menuitem" onClick={async () => { setMenu(false); await onDuplicate(project); }}><CyIcon name="copy" size={14} /> Duplicate as a new project</button>
                <button type="button" role="menuitem" onClick={() => { setMenu(false); setRename(true); }}><CyIcon name="pencil" size={14} /> Rename</button>
                {ok && <a role="menuitem" href={`/api/mod-builder/builds/${b.id}/source-zip`}><CyIcon name="download" size={14} /> Download source (.zip)</a>}
                <button type="button" role="menuitem" onClick={() => { setMenu(false); navigator.clipboard?.writeText(b.changeRequest || b.prompt); }}><CyIcon name="note" size={14} /> Copy the request</button>
                <button type="button" role="menuitem" onClick={() => { setMenu(false); onNewMod(); }} ><CyIcon name="plus" size={14} /> New mod</button>
              </span>
            )}
          </span>
        </div>
      </header>

      {!isHead && ok && project.head && (
        <div className="cy-banner">
          <CyIcon name="layers" size={14} />
          <span>You&apos;re looking at <b>v{n}</b>. The current version is <b>v{versionNumber(project, project.head.id)}</b>.</span>
          <span className="ml-auto flex flex-wrap gap-1.5">
            <button type="button" className="cy-btn sm" onClick={() => onPatch(project.rootId, { headBuildId: b.id })}><CyIcon name="restore" size={13} /> Make v{n} current</button>
            <button type="button" className="cy-btn sm ghost" onClick={() => onOpen(project.head!.id)}>Go to current</button>
          </span>
        </div>
      )}

      {running && (
        <div className="cy-live-grid">
          <Stage build={b} />
          <CodePane build={b} base={parent} height={440} />
        </div>
      )}
      {!running && b.status === "succeeded" && justDone === b.id && <Stage build={b} compact />}
      {b.status === "failed" && <Failure b={b} onRetry={retry} onEdit={editRetry} />}

      {!running && (
        <>
          <div className="cy-tabs" role="tablist">
            {(["overview", "code", "versions", "notes"] as Tab[]).map((t, i) => (
              <button key={t} type="button" role="tab" aria-selected={tab === t} className={`cy-tab ${tab === t ? "on" : ""}`} onClick={() => setTab(t)}>
                {{ overview: ok ? "Overview" : "Request", code: "Code", versions: "Versions", notes: "Notes" }[t]}
                {t === "versions" && <span className="cy-tab-n">{project.builds.length}</span>}
                {t === "code" && files.length > 0 && <span className="cy-tab-n">{visibleSrc(files).length}</span>}
                <span className="cy-tab-k" aria-hidden="true">{i + 1}</span>
              </button>
            ))}
          </div>
          <div role="tabpanel">
            {tab === "overview" && (ok ? <Overview b={b} /> : <FailedRequest b={b} />)}
            {tab === "code" && (files.length ? (
              <section className="flex flex-col gap-3">
                <CodePane build={b} height={560} revealKey={justDone === b.id ? b.id : undefined} />
                <p className="cy-sub">Source is yours to keep. The .zip includes a Gradle project so a developer can rebuild it. {ok && b.jarName && <>{b.jarName} · {bytes(b.jarSize)}</>}</p>
              </section>
            ) : <p className="cy-empty-t">No source for this version.</p>)}
            {tab === "versions" && (
              <Versions project={project} viewing={b.id} onOpen={onOpen}
                        onRestore={async (id) => { await onPatch(project.rootId, { headBuildId: id }); }}
                        onBranch={(id) => { setBranchFrom(id); composerRef.current?.focus(); }} />
            )}
            {tab === "notes" && <Notes key={project.rootId} project={project} onPatch={onPatch} />}
          </div>
        </>
      )}

      {(base || project.running) && <div className="cy-dock">
        {branchFrom && base && (
          <div className="cy-dock-note"><CyIcon name="branch" size={13} /> Branching from <b>v{baseN}</b> <button type="button" onClick={() => setBranchFrom(null)}>Use {b.status === "succeeded" ? `v${n}` : "current"} instead</button></div>
        )}
        <Composer ref={composerRef} kind="change" compact
                  placeholder={base ? `Ask Cyrus to change v${baseN}… e.g. “add a /reload command and make the messages purple”` : "Ask for a change once this mod builds"}
                  defaultModel={bm.model ?? viewMeta(project.head ?? b).model ?? CYRUS_DEFAULT_MODEL}
                  lockVersion={b.mcVersion} disabledReason={disabledReason} submitLabel={base ? `Build v${project.builds.length + 1}` : "Build"} onSubmit={submitChange} />
      </div>}

      {modal === "install" && <InstallModal build={b} servers={servers} onClose={() => setModal(null)} onDone={onRefresh} />}
    </div>
  );
}

function FailedRequest({ b }: { b: ModBuildView }) {
  return (
    <section className="cy-card">
      <h4>{b.changeRequest ? "The change you asked for" : "What you asked for"}</h4>
      <blockquote className="cy-quote">{b.changeRequest || b.prompt}</blockquote>
    </section>
  );
}

function Notes({ project, onPatch }: { project: CyrusProject; onPatch: (rootId: string, p: { notes: string }) => Promise<string | null> }) {
  const [v, setV] = useState(project.meta.notes ?? "");
  const [state, setState] = useState<"saved" | "dirty" | "saving" | "error">("saved");
  const t = useRef<number | undefined>(undefined);
  const save = async (text: string) => {
    setState("saving");
    const e = await onPatch(project.rootId, { notes: text });
    setState(e ? "error" : "saved");
  };
  return (
    <section className="cy-card cy-notes">
      <div className="flex items-center gap-2">
        <h4 className="!m-0"><CyIcon name="note" size={14} /> Project notes</h4>
        <span className={`cy-save ${state}`}>{state === "saving" ? "Saving…" : state === "dirty" ? "Unsaved" : state === "error" ? "Couldn't save" : "Saved"}</span>
      </div>
      <p className="cy-sub">Only you see these. Ideas for the next version, what players said, server setup reminders.</p>
      <textarea value={v} maxLength={CYRUS_NOTES_MAX} rows={10} placeholder="e.g. Players want the shop to sell elytra. Try a 7-day streak reward next."
                onChange={(e) => { setV(e.target.value); setState("dirty"); window.clearTimeout(t.current); const text = e.target.value; t.current = window.setTimeout(() => save(text), 800); }}
                onBlur={() => { if (state === "dirty") { window.clearTimeout(t.current); save(v); } }} />
      <span className="cy-fine">{v.length.toLocaleString("en-US")} / {CYRUS_NOTES_MAX.toLocaleString("en-US")}</span>
    </section>
  );
}
"use client";

import { useEffect, useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import { CYRUS_STAGES } from "@/lib/cyrus/models";
import { hashSeed } from "@/lib/cyrus/projects";
import { Nebula, type NebulaMode } from "./Nebula";
import { CyIcon } from "./icons";
import { dur } from "./util";

const ORDER = ["queued", "planning", "coding", "compiling", "repairing", "scanning", "succeeded"];
export const PROGRESS: Record<string, number> = { queued: 0.04, planning: 0.14, coding: 0.4, compiling: 0.62, repairing: 0.72, scanning: 0.88, succeeded: 1, failed: 1 };

const HEADLINE: Record<string, string> = {
  queued: "Waiting for a free builder",
  planning: "Mapping out your mod",
  coding: "Weaving the code",
  compiling: "Compiling it into a real plugin",
  repairing: "Found a problem, fixing it",
  scanning: "Running the safety check",
  succeeded: "Your mod is ready",
  failed: "This one didn't build",
};

export const modeOf = (s: string): NebulaMode => (s === "queued" || s === "planning" || s === "coding" || s === "compiling" || s === "repairing" || s === "scanning" || s === "succeeded" || s === "failed" ? s : "idle");

/** The living "thinking" panel: nebula that reacts to the real stage + the build's own event stream. */
export function Stage({ build, compact = false }: { build: ModBuildView; compact?: boolean }) {
  const events = build.result?.events ?? [];
  const running = !isTerminal(build.status);
  const writes = events.filter((e) => /^(Wrote|Edited) /.test(e.message));
  const lastWrite = writes[writes.length - 1]?.message.replace(/^(Wrote|Edited) /, "") ?? "";
  const startedAt = events.find((e) => e.stage !== "queued")?.at ?? null;
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => { if (!running) return; const t = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(t); }, [running]);
  const elapsed = running && startedAt ? now - new Date(startedAt).getTime() : build.durationMs ?? 0;
  const stream = events.filter((e) => e.stage !== "queued" && e.message && e.message !== "Error details").slice(-5);
  const seen = new Set(events.map((e) => e.stage));
  const idx = ORDER.indexOf(build.status);
  const repairs = build.result?.repairs ?? 0;
  const head = build.status === "queued" && build.result?.queuePosition ? `In line · position ${build.result.queuePosition}` : HEADLINE[build.status] ?? "Working";

  return (
    <section className={`cy-stage ${compact ? "compact" : ""} st-${build.status}`} aria-live="polite" aria-label="Build progress">
      <div className="cy-aurora" aria-hidden="true"><i /><i /><i /></div>
      <Nebula mode={modeOf(build.status)} burst={writes.length} burstLabel={lastWrite} seed={hashSeed(build.id) % 997} density={compact ? 0.6 : 1} />
      <div className="cy-stage-top">
        <span className="cy-stage-k">{running ? <><i className="cy-pulse" /> Cyrus is thinking</> : build.status === "succeeded" ? "Built" : "Stopped"}</span>
        <h2 className="cy-stage-h">{head}</h2>
        {!compact && running && stream.length > 0 && (
          <ol className="cy-thoughts">
            {stream.map((e, i) => (
              <li key={`${e.at}-${i}`} style={{ opacity: 0.35 + (0.65 * (i + 1)) / stream.length }}>
                <span className="t">+{Math.max(0, Math.round((new Date(e.at).getTime() - new Date(startedAt || e.at).getTime()) / 1000))}s</span>
                <span className="m">{e.message}</span>
              </li>
            ))}
          </ol>
        )}
      </div>
      <div className="cy-stage-time" suppressHydrationWarning>
        <CyIcon name="clock" size={12} /> {running ? (startedAt ? dur(elapsed) : "—") : dur(build.durationMs)}
      </div>
      <ol className="cy-track" aria-label="Stages">
        {CYRUS_STAGES.map((s) => {
          const si = ORDER.indexOf(s.key);
          let cls = "pending";
          if (build.status === "failed") cls = seen.has(s.key) ? "done" : "pending";
          if (s.key === build.status) cls = "now";
          else if (build.status !== "failed" && si < idx) cls = s.key === "repairing" && !seen.has("repairing") ? "skip" : "done";
          return (
            <li key={s.key} className={`cy-tr ${cls}`}>
              <span className="cy-tr-node">{cls === "done" ? <CyIcon name="check" size={10} strokeWidth={2.6} /> : null}</span>
              <span className="cy-tr-l">{s.label}</span>
              <span className="cy-tr-s">{cls === "skip" ? "Not needed" : s.key === "repairing" && repairs ? `Fix ${repairs} of 3` : s.sub}</span>
            </li>
          );
        })}
      </ol>
    </section>
  );
}

"use client";

import { forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState } from "react";
import { CYRUS_GAMES, CYRUS_MODELS, cyrusModel, type CyrusModelId } from "@/lib/cyrus/models";
import { estimate, fmtUsd, modelAdvice } from "@/lib/cyrus/estimate";
import { CyIcon } from "./icons";
import { useVoice } from "./voice";

export type ComposerSubmit = { text: string; model: CyrusModelId; mcVersion: string; attachmentIds: string[] };
export type ComposerHandle = { focus: () => void; setText: (t: string, model?: CyrusModelId) => void; toggleVoice: () => void };
type Att = { key: string; name: string; url: string; status: "up" | "ok" | "err"; id?: string; error?: string };

const MAX_IMG = 4;

export const Composer = forwardRef<ComposerHandle, {
  kind: "new" | "change";
  placeholder: string;
  defaultModel: CyrusModelId;
  defaultVersion?: string;
  lockVersion?: string;
  disabledReason?: string | null;
  submitLabel: string;
  onSubmit: (s: ComposerSubmit) => Promise<string | null>;
  onActivity?: (a: { typing: boolean; listening: boolean; level: number }) => void;
  compact?: boolean;
}>(function Composer({ kind, placeholder, defaultModel, defaultVersion, lockVersion, disabledReason, submitLabel, onSubmit, onActivity, compact }, ref) {
  const [text, setText] = useState("");
  const [model, setModel] = useState<CyrusModelId>(defaultModel);
  const [version, setVersion] = useState(lockVersion || defaultVersion || CYRUS_GAMES[0].defaultVersion!);
  const [atts, setAtts] = useState<Att[]>([]);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [drag, setDrag] = useState(false);
  const [pop, setPop] = useState<null | "model" | "game">(null);
  const ta = useRef<HTMLTextAreaElement>(null);
  const fileIn = useRef<HTMLInputElement>(null);
  const typingT = useRef<number | undefined>(undefined);
  const [typing, setTyping] = useState(false);

  const voice = useVoice((said) => setText((t) => (t && !/\s$/.test(t) ? t + " " : t) + said));

  useEffect(() => setModel(defaultModel), [defaultModel]);
  useEffect(() => { if (lockVersion) setVersion(lockVersion); }, [lockVersion]);

  useImperativeHandle(ref, () => ({
    focus: () => ta.current?.focus(),
    setText: (t, m) => { setText(t); if (m) setModel(m); requestAnimationFrame(() => { ta.current?.focus(); autosize(); }); },
    toggleVoice: () => voice.toggle(),
  }));

  // Feed the nebula: typing bursts and the live voice level.
  useEffect(() => {
    if (!onActivity) return;
    if (!voice.listening) { onActivity({ typing, listening: false, level: 0 }); return; }
    let raf = 0;
    const tick = () => { onActivity({ typing, listening: true, level: voice.level.current }); raf = requestAnimationFrame(tick); };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [typing, voice.listening, onActivity, voice.level]);

  const autosize = () => {
    const el = ta.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = Math.min(el.scrollHeight, compact ? 200 : 320) + "px";
  };
  useEffect(autosize, [text, compact]);

  const attsRef = useRef<Att[]>([]);
  attsRef.current = atts;
  const addFiles = useCallback((files: File[]) => {
    const imgs = files.filter((f) => /^image\/(png|jpe?g|webp|gif)$/.test(f.type));
    if (!imgs.length) { if (files.length) setErr("Only PNG, JPG, WebP or GIF images can be attached."); return; }
    const room = MAX_IMG - attsRef.current.length;
    if (room <= 0) { setErr(`Up to ${MAX_IMG} images per request.`); return; }
    if (imgs.length > room) setErr(`Up to ${MAX_IMG} images per request.`);
    const add = imgs.slice(0, room).map((f) => ({ f, a: { key: Math.random().toString(36).slice(2), name: f.name || "pasted image", url: URL.createObjectURL(f), status: "up" as const } }));
    setAtts((cur) => [...cur, ...add.map((x) => x.a)]);
    for (const x of add) upload(x.a.key, x.f);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function upload(key: string, f: File) {
    if (f.size > 5 * 1024 * 1024) { setAtts((c) => c.map((a) => (a.key === key ? { ...a, status: "err", error: "Over 5 MB" } : a))); return; }
    const fd = new FormData();
    fd.append("file", f, f.name || "pasted.png");
    try {
      const r = await fetch("/api/mod-builder/uploads", { method: "POST", body: fd });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || "Upload failed");
      setAtts((c) => c.map((a) => (a.key === key ? { ...a, status: "ok", id: j.upload.id } : a)));
    } catch (e) {
      setAtts((c) => c.map((a) => (a.key === key ? { ...a, status: "err", error: (e as Error).message } : a)));
    }
  }

  const est = useMemo(() => estimate(text, model, { change: kind === "change" }), [text, model, kind]);
  const advice = text.trim().length > 30 ? modelAdvice(est, model) : "ok";
  const minLen = kind === "change" ? 4 : 12;
  const uploading = atts.some((a) => a.status === "up");
  const canSend = !busy && !disabledReason && text.trim().length >= minLen && !uploading;

  async function submit() {
    if (!canSend) {
      if (text.trim().length < minLen && !disabledReason) setErr(kind === "change" ? "Describe the change in a few words." : "Tell Cyrus a bit more about the mod.");
      return;
    }
    if (voice.listening) voice.stop();
    setBusy(true); setErr(null);
    const e = await onSubmit({ text: text.trim(), model, mcVersion: version, attachmentIds: atts.filter((a) => a.status === "ok" && a.id).map((a) => a.id!) });
    setBusy(false);
    if (e) { setErr(e); return; }
    atts.forEach((a) => URL.revokeObjectURL(a.url));
    setText(""); setAtts([]);
  }

  const m = cyrusModel(model);
  const game = CYRUS_GAMES[0];
  const listening = voice.listening;

  return (
    <div
      className={`cy-composer ${compact ? "compact" : ""} ${listening ? "listening" : ""} ${drag ? "drag" : ""} ${busy ? "busy" : ""}`}
      onDragOver={(e) => { if (e.dataTransfer.types.includes("Files")) { e.preventDefault(); setDrag(true); } }}
      onDragLeave={(e) => { if (e.currentTarget === e.target) setDrag(false); }}
      onDrop={(e) => { e.preventDefault(); setDrag(false); addFiles(Array.from(e.dataTransfer.files)); }}
    >
      <div className="cy-composer-box">
      <div className="cy-rim" aria-hidden="true" />
      <div className="cy-composer-in">
        {atts.length > 0 && (
          <div className="cy-atts" aria-label="Attached images">
            {atts.map((a) => (
              <figure key={a.key} className={`cy-att ${a.status}`} title={a.error || a.name}>
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={a.url} alt={a.name} />
                {a.status === "up" && <span className="cy-att-veil"><i className="cy-spin" /></span>}
                {a.status === "err" && <span className="cy-att-veil err"><CyIcon name="warn" size={14} /></span>}
                <button type="button" aria-label={`Remove ${a.name}`} onClick={() => { URL.revokeObjectURL(a.url); setAtts((c) => c.filter((x) => x.key !== a.key)); }}>
                  <CyIcon name="x" size={10} strokeWidth={2.2} />
                </button>
              </figure>
            ))}
            <span className="cy-att-note">Reference images are saved with your build. Cyrus can&apos;t read images yet, so describe what matters in words too.</span>
          </div>
        )}

        <div className="relative">
          <textarea
            ref={ta}
            value={text}
            rows={compact ? 1 : 3}
            maxLength={kind === "change" ? 2000 : 4000}
            placeholder={listening ? "" : placeholder}
            aria-label={kind === "change" ? "Describe a change" : "Describe your mod"}
            onChange={(e) => {
              setText(e.target.value); setErr(null);
              setTyping(true); window.clearTimeout(typingT.current);
              typingT.current = window.setTimeout(() => setTyping(false), 900);
            }}
            onPaste={(e) => { const f = Array.from(e.clipboardData.files); if (f.length) { e.preventDefault(); addFiles(f); } }}
            onKeyDown={(e) => {
              if (e.key === "Enter" && (e.metaKey || e.ctrlKey || (kind === "change" && !e.shiftKey))) { e.preventDefault(); submit(); }
            }}
          />
          {listening && (
            <div className="cy-listen" aria-live="polite">
              <VoiceWave level={voice.level} />
              <span className="cy-listen-t">{voice.interim ? <em>{voice.interim}</em> : <>Listening<span className="cy-ellipsis" /></>}</span>
            </div>
          )}
        </div>

        <div className="cy-bar">
          <div className="cy-bar-l">
            <button type="button" className="cy-tool" onClick={() => fileIn.current?.click()} aria-label="Attach images" title="Attach images (or paste / drop them)">
              <CyIcon name="image" size={17} />
            </button>
            <input ref={fileIn} type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple className="sr-only" tabIndex={-1}
                   onChange={(e) => { addFiles(Array.from(e.target.files || [])); e.target.value = ""; }} />
            <button type="button" className={`cy-tool cy-mic ${listening ? "on" : ""} ${voice.supported ? "" : "unsupported"}`} onClick={() => voice.toggle()}
                    aria-pressed={listening} aria-label={listening ? "Stop voice typing" : "Voice typing"} title={voice.supported ? "Talk to Cyrus (V)" : "Voice typing needs Chrome, Edge or Safari"}>
              <CyIcon name={listening ? "stop" : "mic"} size={17} />
            </button>
            <span className="cy-bar-sep" aria-hidden="true" />
            {!compact && (
              <Pop open={pop === "game"} onClose={() => setPop(null)}
                   trigger={
                     <button type="button" className="cy-pick" onClick={() => setPop(pop === "game" ? null : "game")} aria-haspopup="dialog" aria-expanded={pop === "game"}>
                       <span className="cy-pick-k">{game.name}</span><span className="cy-pick-v">{lockVersion ? `Paper ${lockVersion}` : `Paper ${version}`}</span><CyIcon name="chev" size={13} />
                     </button>
                   }>
                <GamePanel version={version} lock={!!lockVersion} onPick={(v) => { setVersion(v); setPop(null); }} />
              </Pop>
            )}
            <Pop open={pop === "model"} onClose={() => setPop(null)}
                 trigger={
                   <button type="button" className="cy-pick" onClick={() => setPop(pop === "model" ? null : "model")} aria-haspopup="dialog" aria-expanded={pop === "model"}>
                     <span className="cy-model-dot" style={{ background: m.hue }} />
                     <span className="cy-pick-k">{m.name}</span>
                     <Spend n={m.spend} />
                     <CyIcon name="chev" size={13} />
                   </button>
                 }>
              <ModelPanel model={model} recommended={text.trim().length > 30 ? est.recommended : null} onPick={(id) => { setModel(id); setPop(null); }} />
            </Pop>
          </div>
          <div className="cy-bar-r">
            {!compact && text.trim().length > 0 && (
              <span className="cy-est" title="Estimate from preview builds. You aren't charged during the preview.">
                <CyIcon name="clock" size={12} /> ~{est.minutes[0]}–{est.minutes[1]} min <span className="cy-est-sep">·</span> ≈ {fmtUsd(est.usd)} AI
              </span>
            )}
            <span className="cy-kbd-hint" aria-hidden="true">{kind === "change" ? "↵" : "⌘↵"}</span>
            <button type="button" className="cy-go" disabled={!canSend} onClick={submit} title={disabledReason || undefined}>
              {busy ? <i className="cy-spin" /> : <CyIcon name={kind === "change" ? "send" : "sparkle"} size={15} strokeWidth={1.9} />}
              <span>{busy ? "Starting…" : submitLabel}</span>
            </button>
          </div>
        </div>
      </div>
      </div>
      {(err || voice.error || disabledReason || advice !== "ok") && (
        <div className="cy-composer-msg" role={err || voice.error ? "alert" : undefined}>
          {err ? <span className="bad">{err}</span>
            : voice.error ? <span className="warn">{voice.error} <button type="button" onClick={voice.clearError}>Dismiss</button></span>
            : disabledReason ? <span className="mute">{disabledReason}</span>
            : advice === "under" ? <span className="hint">This sounds like a bigger mod. <button type="button" onClick={() => setModel(est.recommended)}>Use {cyrusModel(est.recommended).name}</button> for a better first try.</span>
            : <span className="hint">A small mod. <button type="button" onClick={() => setModel("katara")}>Katara</button> is fast for simple mods like this.</span>}
        </div>
      )}
    </div>
  );
});

function Spend({ n }: { n: number }) {
  return (
    <span className="cy-spend" aria-label={`Token spend ${n} of 3`}>
      {[1, 2, 3].map((i) => <i key={i} className={i <= n ? "on" : ""} />)}
    </span>
  );
}

function ModelPanel({ model, recommended, onPick }: { model: CyrusModelId; recommended: CyrusModelId | null; onPick: (m: CyrusModelId) => void }) {
  return (
    <div className="cy-panel" role="listbox" aria-label="Model">
      <div className="cy-panel-h">Choose a model</div>
      {CYRUS_MODELS.map((m) => (
        <button key={m.id} type="button" role="option" aria-selected={m.id === model} className={`cy-opt ${m.id === model ? "on" : ""}`} onClick={() => onPick(m.id)}>
          <span className="cy-opt-orb" style={{ ["--orb" as string]: m.hue }} />
          <span className="flex min-w-0 flex-1 flex-col gap-0.5 text-left">
            <span className="flex items-center gap-2">
              <b>{m.name}</b>
              <span className="cy-opt-blurb">{m.blurb}</span>
              {recommended === m.id && <span className="cy-tag">Suggested</span>}
            </span>
            <span className="cy-opt-sub">{m.bestFor}</span>
            <span className="cy-opt-cost"><Spend n={m.spend} /> {m.spendLabel}</span>
          </span>
          {m.id === model && <CyIcon name="check" size={15} className="cy-opt-check" />}
        </button>
      ))}
      <p className="cy-panel-foot">Costs are estimates from preview builds. Nothing is charged during the preview.</p>
    </div>
  );
}

function GamePanel({ version, lock, onPick }: { version: string; lock: boolean; onPick: (v: string) => void }) {
  const mc = CYRUS_GAMES[0];
  return (
    <div className="cy-panel cy-panel-game" aria-label="Game and version">
      <div className="cy-panel-h">Game</div>
      <div className="cy-games">
        {CYRUS_GAMES.map((g) => (
          <span key={g.id} className={`cy-game ${g.available ? "on" : "soon"}`} aria-disabled={!g.available}>
            <span className="cy-game-n">{g.name}</span>
            <span className="cy-game-s">{g.available ? g.note : "Coming soon"}</span>
          </span>
        ))}
      </div>
      <div className="cy-panel-h">Server version {lock && <span className="cy-panel-hn">locked to this project</span>}</div>
      <div className="cy-vers">
        {mc.versions.map((v, i) => (
          <button key={v} type="button" disabled={lock} className={`cy-ver ${v === version ? "on" : ""}`} onClick={() => onPick(v)}>
            Paper {v}{i === 0 && <span className="cy-tag">Latest</span>}
          </button>
        ))}
      </div>
    </div>
  );
}

/** Anchored popover; a bottom sheet on phones. */
function Pop({ open, onClose, trigger, children }: { open: boolean; onClose: () => void; trigger: React.ReactNode; children: React.ReactNode }) {
  const box = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    if (!open) return;
    const down = (e: MouseEvent) => { if (box.current && !box.current.contains(e.target as Node)) onClose(); };
    const key = (e: KeyboardEvent) => { if (e.key === "Escape") { e.stopPropagation(); onClose(); } };
    document.addEventListener("mousedown", down);
    document.addEventListener("keydown", key, true);
    return () => { document.removeEventListener("mousedown", down); document.removeEventListener("keydown", key, true); };
  }, [open, onClose]);
  return (
    <span ref={box} className="cy-pop">
      {trigger}
      {open && (
        <>
          <span className="cy-pop-back" onClick={onClose} aria-hidden="true" />
          <span className="cy-pop-panel" role="dialog">{children}</span>
        </>
      )}
    </span>
  );
}

/** Aurora waveform: real mic level when available, a calm synthetic wave otherwise. */
function VoiceWave({ level }: { level: React.MutableRefObject<number> }) {
  const box = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const bars = Array.from(box.current?.children || []) as HTMLElement[];
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let raf = 0;
    const t0 = performance.now();
    const tick = (now: number) => {
      const t = (now - t0) / 1000;
      const lv = level.current;
      bars.forEach((b, i) => {
        const x = i / (bars.length - 1);
        const env = Math.sin(Math.PI * x);
        const wave = 0.5 + 0.5 * Math.sin(t * 7 + i * 0.75) * Math.sin(t * 2.3 + i * 0.31);
        const h = 0.14 + env * (0.18 + lv * 0.95) * (0.45 + wave * 0.75);
        b.style.transform = `scaleY(${Math.min(1, h).toFixed(3)})`;
      });
      if (!reduce) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [level]);
  return <span ref={box} className="cy-wave" aria-hidden="true">{Array.from({ length: 30 }, (_, i) => <i key={i} />)}</span>;
}
"use client";

// Voice to text for the Cyrus prompt. Web Speech API (Chrome, Edge, Safari)
// for the words; a separate getUserMedia analyser for the live level that
// drives the aurora waveform. Either can be missing: no recognition -> the mic
// button explains why; no analyser -> the waveform animates without real levels.
import { useCallback, useEffect, useRef, useState } from "react";

type SR = {
  continuous: boolean; interimResults: boolean; lang: string;
  start(): void; stop(): void; abort(): void;
  onresult: ((e: { resultIndex: number; results: ArrayLike<ArrayLike<{ transcript: string }> & { isFinal: boolean }> }) => void) | null;
  onerror: ((e: { error: string }) => void) | null;
  onend: (() => void) | null;
};

export function speechSupported(): boolean {
  if (typeof window === "undefined") return false;
  const w = window as unknown as { SpeechRecognition?: unknown; webkitSpeechRecognition?: unknown };
  return !!(w.SpeechRecognition || w.webkitSpeechRecognition);
}

export function useVoice(onFinal: (text: string) => void) {
  const [supported, setSupported] = useState(false);
  const [listening, setListening] = useState(false);
  const [interim, setInterim] = useState("");
  const [error, setError] = useState<string | null>(null);
  const level = useRef(0);
  const rec = useRef<SR | null>(null);
  const audio = useRef<{ ctx: AudioContext; stream: MediaStream; raf: number } | null>(null);
  const finalCb = useRef(onFinal);
  finalCb.current = onFinal;

  useEffect(() => { setSupported(speechSupported()); }, []);

  const stopAudio = () => {
    const a = audio.current;
    if (!a) return;
    cancelAnimationFrame(a.raf);
    a.stream.getTracks().forEach((t) => t.stop());
    a.ctx.close().catch(() => {});
    audio.current = null;
    level.current = 0;
  };

  const stop = useCallback(() => {
    try { rec.current?.stop(); } catch { /* already stopped */ }
    stopAudio();
    setListening(false);
    setInterim("");
  }, []);

  const start = useCallback(async () => {
    setError(null);
    const w = window as unknown as { SpeechRecognition?: new () => SR; webkitSpeechRecognition?: new () => SR };
    const Ctor = w.SpeechRecognition || w.webkitSpeechRecognition;
    if (!Ctor) { setError("Voice typing needs Chrome, Edge or Safari. You can still type or paste."); return; }
    const r = new Ctor();
    r.continuous = true;
    r.interimResults = true;
    r.lang = navigator.language || "en-US";
    r.onresult = (e) => {
      let fin = "", mid = "";
      for (let i = e.resultIndex; i < e.results.length; i++) {
        const res = e.results[i];
        if (res.isFinal) fin += res[0].transcript; else mid += res[0].transcript;
      }
      if (fin.trim()) finalCb.current(fin.trim());
      setInterim(mid);
    };
    r.onerror = (e) => {
      if (e.error === "not-allowed" || e.error === "service-not-allowed") setError("Microphone access is blocked. Allow it in your browser's address bar to talk to Cyrus.");
      else if (e.error === "no-speech") setError("Didn't catch that. Try again a little closer to the mic.");
      else if (e.error !== "aborted") setError("Voice typing stopped unexpectedly.");
    };
    r.onend = () => { stopAudio(); setListening(false); setInterim(""); };
    rec.current = r;
    try { r.start(); setListening(true); } catch { setError("Voice typing couldn't start."); return; }
    // Live level for the waveform (best effort; recognition works without it).
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      const ctx = new AudioContext();
      const an = ctx.createAnalyser();
      an.fftSize = 512;
      ctx.createMediaStreamSource(stream).connect(an);
      const buf = new Uint8Array(an.fftSize);
      const tick = () => {
        an.getByteTimeDomainData(buf);
        let sum = 0;
        for (let i = 0; i < buf.length; i++) { const v = (buf[i] - 128) / 128; sum += v * v; }
        const rms = Math.sqrt(sum / buf.length);
        level.current = level.current * 0.7 + Math.min(1, rms * 5) * 0.3;
        if (audio.current) audio.current.raf = requestAnimationFrame(tick);
      };
      audio.current = { ctx, stream, raf: requestAnimationFrame(tick) };
    } catch { /* no analyser: the waveform runs on its own */ }
  }, []);

  useEffect(() => () => { try { rec.current?.abort(); } catch { /* noop */ } stopAudio(); }, []);

  return { supported, listening, interim, error, level, start, stop, toggle: () => (listening ? stop() : start()), clearError: () => setError(null) };
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import { CyIcon } from "./icons";
import { highlight, langOf } from "./highlight";
import { useSource } from "./source";

type F = { path: string; size: number; name: string; state: "ready" | "writing" | "written" | "editing" | "base"; src: string | null };

const EV = /^(Wrote|Edited|Reading) (.+)$/;

/** Files the AI touched so far, from the real build events ("Wrote Main.java", "Edited config.yml"). */
export function touchedFiles(b: ModBuildView): { name: string; verb: "Wrote" | "Edited" | "Reading"; at: string }[] {
  const out = new Map<string, { name: string; verb: "Wrote" | "Edited" | "Reading"; at: string }>();
  for (const e of b.result?.events ?? []) {
    const m = e.message.match(EV);
    if (!m) continue;
    const verb = m[1] as "Wrote" | "Edited" | "Reading";
    const prev = out.get(m[2]);
    if (verb === "Reading" && prev) continue;
    out.set(m[2], { name: m[2], verb: prev && prev.verb !== "Reading" && verb === "Reading" ? prev.verb : verb, at: e.at });
  }
  return Array.from(out.values());
}

export const visibleSrc = (files: { path: string; size: number }[]) => files.filter((f) => f.path.startsWith("src/") || f.path === "modbuilder.json" || f.path.endsWith(".kts"));

export function CodePane({ build, base, height = 520, revealKey }: { build: ModBuildView; base?: ModBuildView | null; height?: number; revealKey?: string }) {
  const running = !isTerminal(build.status);
  const real = visibleSrc(build.result?.files ?? []);
  const touched = touchedFiles(build);

  const files: F[] = useMemo(() => {
    if (real.length) {
      const t = new Set(touched.filter((x) => x.verb !== "Reading").map((x) => x.name));
      return real.map((f) => {
        const name = f.path.split("/").pop()!;
        return { path: f.path, size: f.size, name, state: running && t.has(name) ? "written" : "ready", src: build.id };
      });
    }
    // Mid-build: the service shares file NAMES live (events); contents arrive at the end.
    const baseFiles = visibleSrc(base?.result?.files ?? []);
    const out: F[] = baseFiles.map((f) => {
      const name = f.path.split("/").pop()!;
      const hit = touched.find((x) => x.name === name && x.verb !== "Reading");
      return { path: f.path, size: f.size, name, state: hit ? "editing" : "base", src: base!.id };
    });
    const wrote = touched.filter((t) => t.verb !== "Reading");
    wrote.forEach((t, i) => {
      if (out.some((f) => f.name === t.name)) return;
      // The newest file is the one being written; earlier ones are done (contents arrive at the end).
      out.push({ path: t.name, size: 0, name: t.name, state: i === wrote.length - 1 && running ? "writing" : "written", src: null });
    });
    return out;
  }, [real, touched, running, build.id, base]);

  const pick = (list: F[]) => {
    const java = list.filter((f) => f.name.endsWith(".java"));
    const pn = build.pluginName;
    return (pn && java.find((f) => f.name === `${pn}.java` || f.name === `${pn}Plugin.java`)) || java.find((f) => /Plugin\.java$|Main\.java$/.test(f.name)) || java[0] || list[0] || null;
  };
  const [sel, setSel] = useState<string | null>(null);
  const [follow, setFollow] = useState(true);
  // While building, follow the file Cyrus touched last (until the user picks one).
  const newest = running ? files.find((f) => f.name === touched.filter((x) => x.verb !== "Reading").slice(-1)[0]?.name) : null;
  const current = (follow && newest) || files.find((f) => f.path === sel) || pick(files);

  const src = useSource(current?.src ?? null, current?.src ? current.path : null, { live: running && current?.src === build.id, sizeKey: current?.size });
  const lines = src.text !== undefined ? src.text.replace(/\n$/, "").split("\n") : null;
  const lang = langOf(current?.path);

  // Reveal animation the first time a finished build's code appears.
  const [reveal, setReveal] = useState(false);
  const revealed = useRef<string | null>(null);
  useEffect(() => {
    if (revealKey && revealed.current !== revealKey && lines) { revealed.current = revealKey; setReveal(true); const t = setTimeout(() => setReveal(false), 2200); return () => clearTimeout(t); }
  }, [revealKey, lines]);

  const groups = useMemo(() => {
    const g: Record<string, F[]> = { Code: [], "Plugin files": [], Other: [] };
    for (const f of files) {
      const k = f.path.startsWith("src/main/java/") || f.name.endsWith(".java") ? "Code" : f.path.startsWith("src/main/resources/") || /\.(ya?ml)$/.test(f.name) ? "Plugin files" : "Other";
      g[k].push(f);
    }
    return Object.entries(g).filter(([, v]) => v.length);
  }, [files]);

  const writingCount = files.filter((f) => f.state === "writing" || f.state === "editing" || f.state === "written").length;

  return (
    <div className="cy-code nx-dark-island" style={{ ["--cy-code-h" as string]: `${height}px` }}>
      <div className="cy-code-head">
        <span className="cy-code-title"><CyIcon name="code" size={14} /> Workspace</span>
        {running ? (
          <span className="cy-live"><i /> Live</span>
        ) : (
          <span className="cy-code-count">{files.length} files</span>
        )}
        {running && writingCount > 0 && <span className="cy-code-count">{writingCount} touched</span>}
        {lines && (
          <button type="button" className="cy-code-btn" onClick={() => navigator.clipboard?.writeText(src.text || "")}>
            <CyIcon name="copy" size={12} /> Copy
          </button>
        )}
      </div>
      <div className="cy-code-body">
        <nav className="cy-tree" aria-label="Files">
          {files.length === 0 && (
            <div className="cy-tree-empty">
              <span className="cy-skel w-[70%]" /><span className="cy-skel w-[55%]" /><span className="cy-skel w-[62%]" />
              <p>Files appear here the moment Cyrus writes them.</p>
            </div>
          )}
          {groups.map(([dir, fs]) => (
            <div key={dir} className="cy-tree-g">
              <div className="cy-tree-dir"><CyIcon name="folder" size={11} /> {dir}</div>
              {fs.map((f) => (
                <button key={f.path} type="button" title={f.path}
                        className={`cy-tree-f ${current?.path === f.path ? "on" : ""} st-${f.state}`}
                        onClick={() => { setSel(f.path); setFollow(false); }}>
                  <span className={`cy-fdot ${f.name.endsWith(".java") ? "j" : "y"}`} />
                  <span className="truncate">{f.name}</span>
                  {f.state === "writing" && <span className="cy-fstate">writing</span>}
                  {f.state === "editing" && <span className="cy-fstate">editing</span>}
                  {f.state === "written" && <span className="cy-fstate ok">{f.src ? "new" : "done"}</span>}
                </button>
              ))}
            </div>
          ))}
          {running && !follow && files.length > 0 && (
            <button type="button" className="cy-follow" onClick={() => setFollow(true)}><CyIcon name="eye" size={11} /> Follow Cyrus</button>
          )}
        </nav>
        <div className="cy-view">
          <div className="cy-view-path">
            <span className="truncate">{current?.path ?? "—"}</span>
            {current?.state === "editing" && <span className="cy-view-tag">showing the previous version · Cyrus is editing it</span>}
            {current?.state === "base" && running && <span className="cy-view-tag dim">previous version</span>}
          </div>
          <div className="cy-view-scroll">
            {!current ? (
              <Weaving label={running ? "Cyrus is planning the files" : "No source files"} />
            ) : current.state === "writing" || !current.src ? (
              <Weaving label={current.state === "writing" ? `Cyrus is writing ${current.name}` : `${current.name} is written`} note="Code opens here when the build finishes. File names appear live as they're written." />
            ) : src.error ? (
              <p className="cy-view-err">Couldn&apos;t load this file right now.</p>
            ) : !lines ? (
              <Weaving label="Loading" compact />
            ) : (
              <table className={`cy-lines ${reveal ? "reveal" : ""} ${current.state === "editing" ? "editing" : ""}`}>
                <tbody>
                  {lines.map((l, i) => (
                    <tr key={i} style={reveal && i < 90 ? { animationDelay: `${i * 14}ms` } : undefined}>
                      <td className="n">{i + 1}</td>
                      <td className="c">{highlight(l, lang)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

/** Placeholder while a file's content isn't readable yet: clearly a skeleton, never fake code. */
function Weaving({ label, note, compact }: { label: string; note?: string; compact?: boolean }) {
  const widths = [62, 44, 78, 30, 66, 52, 84, 38, 58, 70, 26, 48];
  return (
    <div className={`cy-weave ${compact ? "compact" : ""}`}>
      <div className="cy-weave-lines" aria-hidden="true">
        {widths.slice(0, compact ? 5 : 12).map((w, i) => <span key={i} className="cy-skel" style={{ width: `${w}%`, marginLeft: `${(i % 4) * 14}px`, animationDelay: `${i * 90}ms` }} />)}
      </div>
      <div className="cy-weave-l"><i className="cy-spin" /> {label}</div>
      {note && <p className="cy-weave-n">{note}</p>}
    </div>
  );
}
"use client";

import { useState } from "react";
import type { ModBuildView } from "@/lib/modbuilder/types";
import { hashSeed, viewMeta } from "@/lib/cyrus/projects";
import { Nebula } from "./Nebula";
import { CyIcon } from "./icons";

/** "Explain this mod": everything the build reported, in plain English. */
export function Overview({ b }: { b: ModBuildView }) {
  const r = b.result;
  const s = r?.summary;
  return (
    <div className="cy-ov">
      <div className="cy-ov-main">
        <section className="cy-card cy-explain">
          <Nebula mode="succeeded" seed={hashSeed(b.id) % 997} density={0.45} interactive={false} />
          <span className="cy-k"><CyIcon name="sparkle" size={12} /> In plain English</span>
          <h3>{s?.tagline || `${b.pluginName} is built`}</h3>
          {s?.text && <p className="cy-lead">{s.text}</p>}
          {s?.changes && b.changeRequest && (
            <p className="cy-changed"><b>What changed in this version.</b> {s.changes}</p>
          )}
        </section>

        {!!s?.howToUse?.length && (
          <section className="cy-card">
            <h4>How to use it</h4>
            <ol className="cy-steps">
              {s.howToUse.map((h, i) => <li key={i}><span className="cy-step-n">{i + 1}</span><span>{h}</span></li>)}
            </ol>
          </section>
        )}

        {!!r?.commands?.length && (
          <section className="cy-card">
            <h4>Commands <span className="cy-count">{r.commands.length}</span></h4>
            <div className="cy-rows">
              {r.commands.map((c, i) => (
                <div key={i} className="cy-row">
                  <span className="cy-row-k"><code className="cy-cmd">{c.usage}</code></span>
                  <span className="cy-row-v">{c.description}</span>
                  <span className={`cy-who ${/every/i.test(c.whoCanUse) || (!c.whoCanUse && !c.permission) ? "all" : ""}`}>{c.whoCanUse || (c.permission ? "With permission" : "Everyone")}</span>
                </div>
              ))}
            </div>
          </section>
        )}

        {!!r?.config?.length && (
          <section className="cy-card">
            <h4>Settings you can change</h4>
            <p className="cy-sub">In <code className="cy-cmd">plugins/{b.pluginName}/config.yml</code> on your server.</p>
            <div className="cy-rows">
              {r.config.map((c, i) => (
                <div key={i} className="cy-row">
                  <span className="cy-row-k"><b className="cy-anywhere">{c.key}</b></span>
                  <span className="cy-row-v">{c.description}</span>
                  <span className="cy-row-d cy-anywhere">{c.default ? `Default: ${c.default}` : ""}</span>
                </div>
              ))}
            </div>
          </section>
        )}
        <Request b={b} />
      </div>

      <aside className="cy-ov-side">
        <Safety b={b} />
        {!!r?.permissions?.length && (
          <section className="cy-card">
            <h4>Who can do what</h4>
            <p className="cy-sub">Works with LuckPerms or any permissions plugin.</p>
            {r.permissions.map((p, i) => (
              <div key={i} className="cy-perm">
                <span className="flex items-center justify-between gap-2">
                  <b className="cy-anywhere">{p.node}</b>
                  <span className={`cy-who ${p.default === "true" ? "all" : ""}`}>{p.default === "true" ? "Everyone" : p.default === "false" ? "Nobody by default" : "Operators"}</span>
                </span>
                <span className="cy-sub">{p.description}</span>
              </div>
            ))}
          </section>
        )}
        {(!!s?.limitations?.length || !!r?.warnings?.length) && (
          <section className="cy-card">
            <h4><CyIcon name="warn" size={13} className="cy-amber" /> Good to know</h4>
            <ul className="cy-bullets">
              {(s?.limitations ?? []).map((l, i) => <li key={`l${i}`}>{l}</li>)}
              {(r?.warnings ?? []).slice(0, 6).map((w, i) => <li key={`w${i}`}>{w}</li>)}
            </ul>
          </section>
        )}
        <section className="cy-card cy-soon">
          <span className="cy-badge"><CyIcon name="sparkle" size={10} /> Built with Cyrus</span>
          <h4>Coming to Cyrus mods</h4>
          <ul className="cy-soon-l">
            <li><CyIcon name="server" size={13} /> Your server&apos;s Mods tab, with an on/off switch</li>
            <li><CyIcon name="users" size={13} /> A Cyrus Mods community in NxLabs</li>
            <li><CyIcon name="globe" size={13} /> Open source, so anyone can learn from them</li>
          </ul>
          <button type="button" className="cy-btn ghost" disabled>Publish to NxLabs · soon</button>
        </section>
      </aside>
    </div>
  );
}

function Request({ b }: { b: ModBuildView }) {
  const atts = viewMeta(b).attachments ?? [];
  return (
    <section className="cy-card">
      <h4>{b.changeRequest ? "The change you asked for" : "What you asked for"}</h4>
      <blockquote className="cy-quote">{b.changeRequest || b.prompt}</blockquote>
      {b.changeRequest && <details className="cy-details"><summary>Original description</summary><p>{b.prompt}</p></details>}
      {atts.length > 0 && (
        <div className="cy-refs">
          {atts.map((a) => (
            <a key={a.n} href={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} target="_blank" rel="noreferrer" className="cy-ref" title={a.name}>
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} alt={a.name} loading="lazy" />
            </a>
          ))}
          <span className="cy-sub">Reference images are kept with this version. Cyrus doesn&apos;t read images yet.</span>
        </div>
      )}
    </section>
