import { NextResponse } from "next/server";
import { randomBytes } from "node:crypto";
import { db } from "@/lib/db";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { svcCreate, ModBuilderUnavailable } from "@/lib/modbuilder/client";
import { toView } from "@/lib/modbuilder/store";
import { MB_VERSIONS } from "@/lib/modbuilder/types";
import { checkRateLimit } from "@/lib/rate-limit";
import { NOT_FOUND } from "../_lib";
import { isCyrusModel } from "@/lib/cyrus/models";
import { readCyrusMeta, type CyrusMeta } from "@/lib/cyrus/meta";
import { claimUploads, isUploadId } from "@/lib/cyrus/uploads";

export const dynamic = "force-dynamic";

const MAX_INFLIGHT = 2;

export async function GET() {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  const rows = await db.modBuild.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 50 });
  return NextResponse.json({ builds: rows.map(toView) });
}

export async function POST(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;
  const prompt = String(body.prompt ?? "").trim();
  const mcVersion = String(body.mcVersion ?? MB_VERSIONS[0]);
  const changeRequest = body.changeRequest ? String(body.changeRequest).trim() : "";
  const baseBuildId = body.baseBuildId ? String(body.baseBuildId) : null;
  // Cyrus (optional, additive): the model picked in the composer and pasted images.
  if (body.model !== undefined && !isCyrusModel(body.model)) return NextResponse.json({ error: "Pick Katara, Saka or Yakko." }, { status: 400 });
  const attachmentIds = Array.isArray(body.attachmentIds) ? body.attachmentIds.filter(isUploadId).slice(0, 4) : [];

  if (!(MB_VERSIONS as readonly string[]).includes(mcVersion)) return NextResponse.json({ error: "Pick a Minecraft version from the list." }, { status: 400 });

  let base = null;
  if (baseBuildId) {
    base = await db.modBuild.findUnique({ where: { id: baseBuildId } });
    if (!base || base.userId !== user.id) return NOT_FOUND();
    if (base.status !== "succeeded") return NextResponse.json({ error: "You can only change a build that finished." }, { status: 400 });
    if (changeRequest.length < 4 || changeRequest.length > 2000) return NextResponse.json({ error: "Describe the change in a few words (up to 2,000 characters)." }, { status: 400 });
  } else if (prompt.length < 12 || prompt.length > 4000) {
    return NextResponse.json({ error: prompt.length < 12 ? "Tell us a bit more about what the plugin should do." : "That's a lot! Keep it under 4,000 characters." }, { status: 400 });
  }

  for (const [k, max, windowMs] of [["mb:create:min", 3, 60_000], ["mb:create:hour", 20, 3_600_000]] as const) {
    const rl = checkRateLimit(`${k}:${user.id}`, { max, windowMs });
    if (!rl.ok) return NextResponse.json({ error: `You're building fast! Try again in ${rl.retryAfterSec}s.` }, { status: 429 });
  }
  const inflight = await db.modBuild.count({ where: { userId: user.id, status: { notIn: ["succeeded", "failed"] } } });
  if (inflight >= MAX_INFLIGHT) return NextResponse.json({ error: "You already have builds running. Wait for one to finish first." }, { status: 429 });

  const id = "mb" + randomBytes(10).toString("hex");
  // A change keeps the model its version was built with unless a new one is picked.
  const model = isCyrusModel(body.model) ? body.model : base ? readCyrusMeta(base.cyrus).model : undefined;
  const cyrus: CyrusMeta | null = model || attachmentIds.length ? { ...(model ? { model } : {}) } : null;
  const row = await db.modBuild.create({
    data: {
      id,
      userId: user.id,
      prompt: base ? base.prompt : prompt,
      changeRequest: base ? changeRequest : null,
      baseBuildId: base ? base.id : null,
      rootBuildId: base ? (base.rootBuildId ?? base.id) : id,
      mcVersion: base ? base.mcVersion : mcVersion,
      pluginName: base ? base.pluginName : null,
      ...(cyrus ? { cyrus } : {}),
    },
  });
  if (attachmentIds.length) {
    const attachments = await claimUploads(user.id, id, attachmentIds).catch(() => []);
    if (attachments.length) await db.modBuild.update({ where: { id }, data: { cyrus: { ...(cyrus ?? {}), attachments } } });
  }
  try {
    await svcCreate({
      id,
      prompt: row.prompt,
      mcVersion: row.mcVersion,
      ...(base ? { baseBuildId: base.id, changeRequest } : {}),
      ...(model ? { tier: model } : {}),
    });
  } catch (e) {
    const msg = e instanceof ModBuilderUnavailable ? "The builder is offline right now. Please try again in a few minutes." : "The builder couldn't take this request. Please try again.";
    await db.modBuild.update({ where: { id }, data: { status: "failed", errorCode: "unavailable", error: msg, finishedAt: new Date() } });
    console.error("[modbuilder] create failed", id, (e as Error).message);
  }
  await db.auditLog.create({ data: { userId: user.id, action: base ? "modbuilder.change" : "modbuilder.build", detail: id } }).catch(() => {});
  const fresh = await db.modBuild.findUnique({ where: { id } });
  return NextResponse.json({ build: toView(fresh!) }, { status: 201 });
}
import { NextResponse } from "next/server";
import { svcSource } from "@/lib/modbuilder/client";
import { isTerminal } from "@/lib/modbuilder/types";
import { NOT_FOUND, ownedBuild } from "../../../_lib";

export const dynamic = "force-dynamic";

// One source file as text, proxied from the build service (the source lives there).
export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  const path = new URL(req.url).searchParams.get("path") || "";
  if (!/^[A-Za-z0-9_./-]{1,300}$/.test(path) || path.includes("..")) return NextResponse.json({ error: "Bad path" }, { status: 400 });
  try {
    const r = await svcSource(o.build.id, path);
    if (!r.ok) return NextResponse.json({ error: "File not found" }, { status: 404 });
    // Finished builds never change; an in-flight one may (Cyrus polls it while building).
    const cache = isTerminal(o.build.status) ? "private, max-age=300" : "no-store";
    return new Response(await r.text(), { headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": cache, "X-Content-Type-Options": "nosniff" } });
  } catch {
    return NextResponse.json({ error: "The builder is offline right now." }, { status: 503 });
  }
}
import { NextResponse } from "next/server";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { checkRateLimit } from "@/lib/rate-limit";
import { CYRUS_MAX_IMAGE_BYTES, saveUpload } from "@/lib/cyrus/uploads";
import { NOT_FOUND } from "../_lib";

export const dynamic = "force-dynamic";

// Cyrus: one reference image pasted / dropped into the prompt (multipart field "file").
// Returns an upload id the create call can attach. Images are stored and shown back,
// but the build service does not read them yet.
export async function POST(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  const rl = checkRateLimit(`mb:upload:${user.id}`, { max: 30, windowMs: 10 * 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Too many images. Try again in ${rl.retryAfterSec}s.` }, { status: 429 });
  const len = Number(req.headers.get("content-length") || 0);
  if (len > CYRUS_MAX_IMAGE_BYTES + 64 * 1024) return NextResponse.json({ error: "Images can be up to 5 MB." }, { status: 413 });
  const form = await req.formData().catch(() => null);
  const file = form?.get("file");
  if (!file || typeof file === "string") return NextResponse.json({ error: "No image." }, { status: 400 });
  const bytes = new Uint8Array(await file.arrayBuffer());
  const r = await saveUpload(user.id, file.name, bytes);
  if (!r.ok) return NextResponse.json({ error: r.error }, { status: 400 });
  return NextResponse.json({ upload: { id: r.id, name: r.name, type: r.type, size: r.size } }, { status: 201 });
}

# Nxeon Mod Builder build service.
# Base: claudebox (node 22 + Claude Code CLI + iptables egress allowlist).
FROM claudebox:14f689d

USER root
ARG MC_VERSIONS="1.21.11 1.21.8 1.21.4 1.21.1"

# Pinned toolchain (Temurin 21.0.12.1+1 + Gradle 8.14.3), copied in from the
# Nxeon research toolchain so the image never depends on a moving download.
COPY toolchain.tgz /tmp/toolchain.tgz
RUN mkdir -p /opt/mb && tar xzf /tmp/toolchain.tgz -C /opt/mb && rm /tmp/toolchain.tgz \
 && ln -s /opt/mb/jdk-21.0.12.1+1 /opt/mb/jdk && ln -s /opt/mb/gradle-8.14.3 /opt/mb/gradle
ENV JAVA_HOME=/opt/mb/jdk
ENV PATH=/opt/mb/jdk/bin:/opt/mb/gradle/bin:$PATH

COPY template /opt/mb/template
COPY package.json /opt/mb/app/package.json
RUN cd /opt/mb/app && npm install --omit=dev --no-audit --no-fund && chown -R claude:claude /opt/mb

# Pre-warm the Gradle cache for every supported version and record the exact
# compile classpath. This is the ONLY step that talks to repo.papermc.io /
# repo.maven.apache.org, and it happens at image build time (outside the
# runtime egress firewall). Runtime builds are fully offline.
USER claude
ENV GRADLE_USER_HOME=/opt/mb/gradle-home
RUN set -e; mkdir -p /opt/mb/classpath; for v in $MC_VERSIONS; do \
      gradle --no-daemon -q -p /opt/mb/template writeClasspath -PmcApi=${v}-R0.1-SNAPSHOT -PcpOut=/opt/mb/classpath/${v}.txt; \
      test -s /opt/mb/classpath/${v}.txt; \
    done; rm -rf /opt/mb/template/.gradle /opt/mb/template/build; ls -la /opt/mb/classpath
# Class index per version (every class name on the compile classpath), used by
# precheck.js to turn "cannot find symbol" into "this class lives in package X".
RUN set -e; for v in $MC_VERSIONS; do \
      for j in $(tr ':' ' ' < /opt/mb/classpath/${v}.txt); do jar tf "$j" | grep '\.class$' || true; done | sort -u > /opt/mb/classpath/${v}.classes.txt; \
      test -s /opt/mb/classpath/${v}.classes.txt; \
    done; wc -l /opt/mb/classpath/*.classes.txt

USER root
RUN mkdir -p /work /data && chown claude:claude /work /data
USER claude
COPY --chown=claude:claude server.js scan.js prompts.js route.js precheck.js /opt/mb/app/
COPY --chown=claude:claude sheets /opt/mb/app/sheets
COPY --chown=claude:claude rules /opt/mb/app/rules
ENV MB_VERSIONS="1.21.11 1.21.8 1.21.4 1.21.1"
WORKDIR /data
EXPOSE 3000
ENTRYPOINT ["/bin/bash", "/entrypoint.sh"]
CMD ["node", "/opt/mb/app/server.js"]
#!/bin/bash
# (Re)create the Mod Builder container on the build VM. Idempotent.
#   /root/claudebox.env   CLAUDE_CODE_OAUTH_TOKEN=... (owner subscription)  -- or ANTHROPIC_API_KEY=... for paid API
#   /root/modbuilder.env  MODBUILDER_API_KEY=...      (bearer key the portal uses)
set -euo pipefail
IMAGE="${1:-modbuilder:0.3}"
# Routing / knowledge knobs (see route.js, prompts.js): passed through when set in the caller's env,
# e.g. MB_ROUTING=off /opt/modbuilder/run.sh modbuilder:0.3  (or put them in /root/modbuilder.env).
PASS=()
for k in MB_ROUTING MB_CLASSIFIER MB_MODEL_SIMPLE MB_MODEL_STANDARD MB_MODEL_COMPLEX MB_REPAIR_MODEL MB_REPAIR_CHEAP_MODEL MB_REPAIR_CHEAP_FIRST MB_REPAIR_SMALL_MAX MB_ROUTE_SIMPLE_MAX MB_ROUTE_COMPLEX_MIN MB_SHEETS MB_RULES MB_MAX_REPAIRS; do
  if [[ -n "${!k:-}" ]]; then PASS+=(-e "$k=${!k}"); fi
done
docker rm -f modbuilder >/dev/null 2>&1 || true
docker run -d --name modbuilder --restart unless-stopped \
  --cap-add NET_ADMIN \
  --env-file /root/claudebox.env --env-file /root/modbuilder.env \
  -e MB_CONCURRENCY="${MB_CONCURRENCY:-2}" -e MB_MODEL="${MB_MODEL:-sonnet}" ${PASS[@]+"${PASS[@]}"} \
  -p 127.0.0.1:7340:3000 \
  -v /var/lib/modbuilder/data:/data -v /var/lib/modbuilder/work:/work \
  --memory 5g --pids-limit 512 \
  "$IMAGE"
