  ["p2", "Kodely", "#b14bff", "code", 8, "idle", 0.7],
  ["p3", "Soul Pilates", "#ff8a5c", "sparkles", 30, "idle", 0.5],
  ["p4", "Ads Autopilot", "#3dffb5", "chart", 60, "running", 0.6],
