const sub = (id, parentId, name, color) => ({ id, slug: id, name, color, icon: "layers", status: "idle", activity: 0.3, lastActiveAt: iso(10), kind: "subproject", parentId });
nodes.push(sub("s1", "p1", "Admin", "#ff6fae"), sub("s2", "p1", "Marketing", "#b14bff"), sub("s3", "p2", "Editor", "#3dffb5"));
