const srv = http.createServer((req, res) => {
  const u = new URL(req.url, "http://x");
  const j = (b) => { res.writeHead(200, { "Content-Type": "application/json" }); res.end(JSON.stringify(b)); };
  if (u.pathname === "/api/auth/me") return j({ user });
  if (u.pathname === "/api/projects/graph") return j({ nodes, links });
  if (u.pathname === "/api/projects") return j({ projects: nodes.filter((n) => n.kind === "project").map((n) => ({ ...n, myRole: "owner", previewPort: 0, createdAt: iso(9999) })) });
  if (u.pathname === "/api/usage/me") return j({ today: { tokens: 0 }, limits: {} });
  if (u.pathname.startsWith("/api/")) return j({});
  let f = path.join(DIST, u.pathname);
  if (!f.startsWith(DIST) || !fs.existsSync(f) || fs.statSync(f).isDirectory()) f = path.join(DIST, "index.html");
  res.writeHead(200, { "Content-Type": types[path.extname(f)] || "application/octet-stream" });
  fs.createReadStream(f).pipe(res);
});
const wss = new WebSocketServer({ server: srv, path: "/ws" });
wss.on("connection", (ws) => {
  const t = setInterval(() => {
    const p = P[Math.floor(Math.random() * 5)][0];
    ws.send(JSON.stringify({ t: "graph_pulse", projectId: p, intensity: 0.4 + Math.random() * 0.6 }));
  }, 900);
  ws.on("close", () => clearInterval(t));
});
srv.listen(PORT, "127.0.0.1", () => console.log("ref stub on", PORT));

