// Capture the workspace Nexus reference: stills at 1440x900 + 1920x1080, a hover, a zoom-in, and a frame sequence.
import { createRequire } from "node:module";
import { mkdirSync } from "node:fs";
const require = createRequire("/opt/nxeon/node_modules/");
const { chromium } = require("playwright");
const OUT = "/root/agent-notes/cyrus-v2/reference";
mkdirSync(OUT, { recursive: true });
const b = await chromium.launch({ args: ["--disable-gpu"] });
for (const [w, h] of [[1440, 900], [1920, 1080]]) {
  const ctx = await b.newContext({ viewport: { width: w, height: h } });
  const p = await ctx.newPage();
  const errs = []; p.on("pageerror", (e) => errs.push(String(e)));
  await p.goto("http://127.0.0.1:5199/", { waitUntil: "networkidle" });
  await p.waitForTimeout(3500);
  await p.screenshot({ path: `${OUT}/nexus-${w}.png` });
  if (w === 1440) {
    for (let i = 0; i < 8; i++) { await p.waitForTimeout(250); await p.screenshot({ path: `${OUT}/frame-${String(i).padStart(2, "0")}.png` }); }
    // hover the first ring node near center-ish: sweep a few points
    const box = await p.locator("canvas").boundingBox();
    for (const [dx, dy] of [[170, 0], [0, 170], [-170, 0], [120, 120], [-120, -120], [120, -120]]) {
      await p.mouse.move(box.x + box.width / 2 + dx, box.y + box.height / 2 + dy);
      await p.waitForTimeout(200);
    }
    await p.waitForTimeout(500);
    await p.screenshot({ path: `${OUT}/nexus-hover.png` });
    await p.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
    await p.mouse.wheel(0, -600); await p.waitForTimeout(1500);
    await p.screenshot({ path: `${OUT}/nexus-zoom.png` });
  }
  console.log(w, errs.join(" | ").slice(0, 400));
  await ctx.close();
}
await b.close();

