import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { modBuilderUser } from "@/lib/modbuilder/access";

export const NOT_FOUND = () => NextResponse.json({ error: "Not found" }, { status: 404, headers: { "x-robots-tag": "noindex" } });

/** The preview user + their build, or null (callers answer 404 — the feature doesn't exist for anyone else). */
export async function ownedBuild(id: string) {
  const user = await modBuilderUser();
  if (!user) return null;
  const build = await db.modBuild.findUnique({ where: { id } });
  if (!build || build.userId !== user.id) return null;
  return { user, build };
}
import { NextResponse } from "next/server";
import { readCyrusMeta } from "@/lib/cyrus/meta";
import { readAttachment } from "@/lib/cyrus/uploads";
import { NOT_FOUND, ownedBuild } from "../../../../_lib";

export const dynamic = "force-dynamic";

// Cyrus: a reference image attached to one of the user's builds.
export async function GET(_req: Request, { params }: { params: Promise<{ id: string; n: string }> }) {
  const { id, n } = await params;
  const o = await ownedBuild(id);
  if (!o) return NOT_FOUND();
  const a = readCyrusMeta(o.build.cyrus).attachments?.find((x) => String(x.n) === n);
  if (!a) return NOT_FOUND();
  const buf = await readAttachment(o.build.id, a);
  if (!buf) return NextResponse.json({ error: "Image not found" }, { status: 404 });
  return new Response(new Uint8Array(buf), {
    headers: { "Content-Type": a.type, "Cache-Control": "private, max-age=86400", "X-Content-Type-Options": "nosniff", "Content-Security-Policy": "default-src 'none'" },
  });
}
