// CyrusWeb: the living orb-web behind Cyrus. Framework-free Canvas 2D.
//
// Ported from the owner's workspace "Nexus" engine (orb-web of radial spokes + sagging
// capture rings, catenary strands, travelling light, hex core, semantic-zoom satellites)
// and rebuilt for Cyrus:
//  - two scenes on one canvas: HOME (Cyrus core, your mods, + New mod, template seeds)
//    and PROJECT (the mod as the core, its files, commands, permissions, config keys);
//    scene changes fly the camera into the clicked node and re-grow the web from the core;
//  - every pulse is driven by a real event (the React side calls emit/gather/scan/bloom);
//  - Nxeon brand palette, an aurora layer + three parallax star layers + pointer parallax;
//  - labels are pre-rendered sprites drawn in screen space (crisp, no boxes);
//  - no d3: a tiny deterministic ring layout with collision relaxation;
//  - 60 fps budget (sprite caches, quarter-res background, capped DPR), pauses off-screen
//    and in hidden tabs, and renders single static frames under prefers-reduced-motion.

export type Rgb = [number, number, number];
export type WebKind = "core" | "mod" | "ghost" | "seed" | "file" | "res" | "ver" | "cmd" | "perm" | "cfg";
export type WebStatus = "idle" | "running" | "ok" | "bad";
export type WebTheme = "dark" | "light";

export interface WebNodeSpec {
  id: string;
  kind: WebKind;
  label: string;
  color: string;
  status?: WebStatus;
  /** 0..1, drawn as a ring while running */
  progress?: number;
  /** satellites: owner node id */
  parent?: string;
  /** ring order: higher = closer to the core */
  weight?: number;
  /** short text drawn inside the orb ("{}", "≡", an initial) */
  glyph?: string;
  /** being written right now (live code) */
  live?: boolean;
  /** secondary line in the hover card */
  sub?: string;
}

export interface WebStage {
  /** service status: queued | planning | coding | compiling | repairing | scanning | succeeded | failed */
  status: string;
  repairs: number;
  /** stages reached so far (for failed builds) */
  seen: string[];
}

export interface WebScene {
  key: string;
  mode: "home" | "project";
  core: { label: string; color: string; glyph?: string };
  nodes: WebNodeSpec[];
  stage?: WebStage | null;
  /** the builder is offline: the core dims */
  offline?: boolean;
}

export interface WebCallbacks {
  onHover?: (n: WebNodeSpec | null) => void;
  onOpen?: (n: WebNodeSpec) => void;
}

interface P { x: number; y: number }
interface N extends P {
  spec: WebNodeSpec;
  id: string;
  kind: WebKind;
  rgb: Rgb;
  r: number;
  tx: number; ty: number;
  phase: number;
  flash: number;
  ripples: number[];
  born: number;
  alpha: number;
  dying: boolean;
  owner?: N;
  slot: number; slots: number;
  expand: number; holdUntil: number; vis: number;
  ring: number;
}
interface Strand { a: P & { rgb?: Rgb }; b: P & { rgb?: Rgb }; phase: number; cx: number; cy: number; len: number; kind: "core" | "sat" | "spoke"; node?: N }
interface Pulse { s: Strand; t: number; speed: number; dir: 1 | -1; rgb: Rgb; size: number }
interface Star { x: number; y: number; z: number; tw: number; s: number; c: number }

const TAU = Math.PI * 2;
const CORE_R = 30;
const MAX_PULSES = 360;
const EASE = (u: number) => (u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2);

export const BRAND = {
  violet: [140, 58, 233] as Rgb,
  blue: [47, 126, 239] as Rgb,
  cyan: [20, 197, 228] as Rgb,
  magenta: [214, 35, 225] as Rgb,
  ink: [238, 241, 255] as Rgb,
  ok: [62, 230, 168] as Rgb,
  warn: [255, 180, 79] as Rgb,
  bad: [255, 92, 138] as Rgb,
};
const HOT_V: Rgb = [196, 150, 255];
const HOT_C: Rgb = [140, 236, 252];

const PALETTE = {
  dark: { bg: ["#0b1238", "#060a26", "#03051a"], web: 0.1, webRing: 0.085, strand: 0.2, aurora: 0.2, star: 0.5, labelInk: "#e6eaff", labelDim: "rgba(205,212,245,0.62)", body: "rgba(7,10,32,0.94)" },
  light: { bg: ["#1c2160", "#121747", "#0b0f33"], web: 0.13, webRing: 0.11, strand: 0.25, aurora: 0.3, star: 0.62, labelInk: "#f2f4ff", labelDim: "rgba(222,226,255,0.72)", body: "rgba(14,18,58,0.92)" },
};

export function hexRgb(h: string): Rgb {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec((h || "").trim());
  if (!m) return BRAND.violet;
  let s = m[1];
  if (s.length === 3) s = s.split("").map((c) => c + c).join("");
  const n = parseInt(s, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
const rgba = (c: Rgb, a: number) => `rgba(${c[0]},${c[1]},${c[2]},${a})`;
const mix = (a: Rgb, b: Rgb, t: number): Rgb => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t].map(Math.round) as Rgb;
function mulberry(seed: number) {
  return () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}
export function hashStr(s: string) { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
const isSat = (k: WebKind) => k === "ver" || k === "cmd" || k === "perm" || k === "cfg";
const STAGES = ["planning", "coding", "compiling", "repairing", "scanning"];

export class CyrusWeb {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private cb: WebCallbacks;
  private dpr = 1; private W = 1; private H = 1;
  private raf = 0; private last = 0; private time = 0;
  private running = false; private visible = true; private disposed = false;
  private reduced: boolean;
  private dirty = true;
  private theme: WebTheme = "dark";
  private font = "ui-sans-serif, system-ui, sans-serif";
  private mono = "ui-monospace, monospace";

  private scene: WebScene | null = null;
  private core: N;
  private nodes: N[] = [];
  private sats: N[] = [];
  private byId = new Map<string, N>();
  private strands: Strand[] = [];
  private satStrands: Strand[] = [];
  private spokes: Strand[] = [];
  private pulses: Pulse[] = [];
  private stars: Star[] = [];
  private outerR = 320;
  private webPath: Path2D | null = null;
  private spokePath: Path2D | null = null;
  private bg: HTMLCanvasElement | null = null;
  private bgAt = -1;
  private sprites = new Map<string, HTMLCanvasElement>();
  private labels = new Map<string, HTMLCanvasElement>();
  private labelQ: { x: number; y: number; text: string; alpha: number; color: string; size: number; weight: number; above: boolean }[] = [];

  // camera
  private cam = { x: 0, y: 0, k: 1 };
  private target = { x: 0, y: 0, k: 1 };
  private tween: { from: { x: number; y: number; k: number }; to: { x: number; y: number; k: number }; t0: number; dur: number; done?: () => void } | null = null;
  private region = { x: 0, y: 0, w: 1, h: 1, coreY: 0.5 };
  private fitK = 1;
  private userMoved = false;
  private trans: { t0: number; dur: number; from: N | null; next: WebScene } | null = null;

  // activity
  private energy = 0; private energyS = 0;
  private emitAcc = 0;
  private scanR = -1;
  private bloomT = -1;
  private focusId: string | null = null;
  private showSats = false;

  // interaction
  private hovered: N | null = null;
  private pointer = { x: 0, y: 0, px: 0, py: 0 };
  private pointers = new Map<number, P>();
  private drag: { mode: "pan" | "pinch"; sx: number; sy: number; moved: boolean; camX: number; camY: number; dist?: number; k0?: number; node?: N | null } | null = null;
  private captionEl: HTMLElement | null = null;
  private captionDy = 0;
  private hoverEl: HTMLElement | null = null;
  private ro: ResizeObserver;
  private io: IntersectionObserver | null = null;
  private mo: MutationObserver | null = null;

  constructor(canvas: HTMLCanvasElement, cb: WebCallbacks = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d", { alpha: false })!;
    this.cb = cb;
    this.reduced = typeof matchMedia !== "undefined" && matchMedia("(prefers-reduced-motion: reduce)").matches;
    this.core = this.mkNode({ id: "__core", kind: "core", label: "Cyrus", color: "#8c3ae9" });
    this.core.alpha = 1;
    try {
      const cs = getComputedStyle(document.body);
      if (cs.fontFamily) this.font = cs.fontFamily;
      const m = getComputedStyle(document.documentElement).getPropertyValue("--font-mono").trim();
      if (m) this.mono = m;
    } catch { /* defaults */ }
    this.readTheme();
    this.ro = new ResizeObserver(() => this.resize());
    this.ro.observe(canvas);
    if (typeof IntersectionObserver !== "undefined") {
      this.io = new IntersectionObserver((es) => { this.visible = es.some((e) => e.isIntersecting); if (this.visible) this.start(); else this.stop(); });
      this.io.observe(canvas);
    }
    this.mo = new MutationObserver(() => this.readTheme());
    this.mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme", "class"] });
    this.resize();
    this.makeStars();
    this.buildWeb();
    this.bind();
    document.addEventListener("visibilitychange", this.onVis);
    document.fonts?.ready.then(() => { this.labels.clear(); this.dirty = true; }).catch(() => {});
    this.start();
  }

  // ------------------------------------------------------------------ API --
  /** Replace the scene. Same key = in-place update (nodes animate); new key = fly-through transition. */
  setScene(scene: WebScene, opts: { fromId?: string } = {}) {
    const prev = this.scene;
    if (prev && prev.key !== scene.key && !this.reduced) {
      const from = opts.fromId ? this.byId.get(opts.fromId) ?? null : null;
      this.trans = { t0: performance.now(), dur: 520, from, next: scene };
      for (const n of [...this.nodes, ...this.sats]) n.dying = true;
      this.userMoved = false;
      if (from) this.animateTo({ x: from.x, y: from.y, k: this.cam.k * 2.1 }, 520);
      else this.animateTo({ x: this.cam.x, y: this.cam.y, k: this.cam.k * 0.82 }, 520);
      this.dirty = true;
      return;
    }
    this.apply(scene, !prev || prev.key !== scene.key);
  }

  /** Screen box (canvas px) the web should be fitted into; coreY = where the core sits (0..1 of the box). */
  setRegion(r: { x: number; y: number; w: number; h: number; coreY?: number }) {
    const n = { x: r.x, y: r.y, w: Math.max(80, r.w), h: Math.max(80, r.h), coreY: r.coreY ?? 0.5 };
    const o = this.region;
    if (Math.abs(o.x - n.x) + Math.abs(o.y - n.y) + Math.abs(o.w - n.w) + Math.abs(o.h - n.h) + Math.abs(o.coreY - n.coreY) * 100 < 2) return;
    this.region = n;
    if (!this.userMoved) this.fit(!this.scene || this.reduced);
  }

  /** Composer activity 0..1 (typing bursts, live mic level). */
  setEnergy(e: number) { this.energy = Math.max(0, Math.min(1, e)); }
  setFocus(id: string | null) { if (this.focusId !== id) { this.focusId = id; this.dirty = true; } }
  setSatellites(on: boolean) { this.showSats = on; this.dirty = true; }
  setTheme(t: WebTheme) { if (t !== this.theme) { this.theme = t; this.bg = null; this.dirty = true; } }

  /** Light from the core to a node (or inward from it). Unknown id = along a random spoke. */
  emit(id: string | null, o: { count?: number; rgb?: Rgb; size?: number; inward?: boolean } = {}) {
    const n = id ? this.byId.get(id) : undefined;
    if (n) { n.flash = Math.min(1.4, n.flash + 0.35); }
    if (this.reduced) { this.dirty = true; return; }
    const st = n ? (n.owner ? this.satStrands.find((s) => s.node === n) : this.strands.find((s) => s.node === n)) : this.spokes[Math.floor(Math.random() * this.spokes.length)];
    if (!st) return;
    const c = o.count ?? 1;
    for (let i = 0; i < c; i++) this.spawn(st, o.inward ? -1 : 1, o.rgb ?? (n ? n.rgb : HOT_V), o.size ?? 1, -i * 0.07);
  }
  /** Compiling: light flows inward from every file to the core. */
  gather() {
    if (this.reduced) return;
    for (const s of this.strands) if (s.node && (s.node.kind === "file" || s.node.kind === "res")) this.spawn(s, -1, s.node.rgb, 1, -Math.random() * 0.3);
  }
  /** Safety check: a scan ring sweeps outward over every node. */
  scan() { this.scanR = this.reduced ? -1 : 0; this.dirty = true; }
  /** Success: one bloom from the core. */
  bloom() {
    this.core.flash = 1.4;
    for (const n of this.nodes) n.flash = Math.max(n.flash, 0.7);
    if (this.reduced) { this.dirty = true; return; }
    this.bloomT = 0;
    this.core.ripples.push(0, -0.25);
    for (const s of this.strands) this.spawn(s, 1, s.node?.rgb ?? HOT_V, 1.2, -Math.random() * 0.2);
  }
  ripple(id: string | null) {
    const n = id ? this.byId.get(id) : this.core;
    if (!n) return;
    n.flash = Math.min(1.4, n.flash + 0.6);
    if (!this.reduced) { n.ripples.push(0); if (n.ripples.length > 4) n.ripples.shift(); }
    this.dirty = true;
  }

  zoomBy(f: number) { this.userMoved = true; this.zoomAt(this.W / 2, this.H / 2, f); }
  fit(instant = false) {
    const g = this.region;
    const k = Math.max(0.3, Math.min(1.7, (Math.min(g.w, g.h * 1.08) / 2 / (this.outerR - 40)) * 0.94));
    this.fitK = k;
    // world (0,0) at screen (g.x + g.w/2, g.y + g.h*coreY)
    const sx = g.x + g.w / 2, sy = g.y + g.h * g.coreY;
    const to = { k, x: -(sx - this.W / 2) / k, y: -(sy - this.H / 2) / k };
    this.animateTo(to, instant ? 0 : 750);
  }
  recenter() { this.userMoved = false; this.fit(); }

  /** An element kept centred under the core (stage caption). dy = px below the core's rim. */
  pinCaption(el: HTMLElement | null, dy = 34) { this.captionEl = el; this.captionDy = dy; this.dirty = true; }
  /** The hover card; the engine positions it next to the hovered node every frame. */
  pinHover(el: HTMLElement | null) { this.hoverEl = el; }
  coreScreen() { return this.screenPos(this.core); }

  dispose() {
    this.disposed = true;
    this.stop();
    this.ro.disconnect();
    this.io?.disconnect();
    this.mo?.disconnect();
    document.removeEventListener("visibilitychange", this.onVis);
    this.unbind();
  }

  // ------------------------------------------------------------- scene ----
  private mkNode(spec: WebNodeSpec): N {
    const k = spec.kind;
    const r = k === "core" ? CORE_R : k === "mod" ? 17 : k === "file" ? 15 : k === "res" ? 13 : k === "ghost" ? 14 : k === "seed" ? 9 : k === "ver" ? 5 : 4;
    return {
      spec, id: spec.id, kind: k, rgb: hexRgb(spec.color), r, x: 0, y: 0, tx: 0, ty: 0,
      phase: (hashStr(spec.id) % 1000) / 1000 * TAU, flash: 0, ripples: [], born: this.time, alpha: 0, dying: false,
      slot: 0, slots: 1, expand: 0, holdUntil: 0, vis: 0, ring: 0,
    };
  }

  private apply(scene: WebScene, fresh: boolean) {
    this.scene = scene;
    this.core.spec = { id: "__core", kind: "core", label: scene.core.label, color: scene.core.color, glyph: scene.core.glyph };
    this.core.rgb = hexRgb(scene.core.color);
    const prev = fresh ? new Map<string, N>() : this.byId;
    const ring: N[] = [];
    const sats: N[] = [];
    const t = this.time;
    let stagger = 0;
    for (const spec of scene.nodes) {
      let n = prev.get(spec.id);
      if (!n || n.kind !== spec.kind) {
        n = this.mkNode(spec);
        n.born = t + (fresh ? 0.12 + stagger * 0.045 : 0);
        stagger++;
      }
      n.spec = spec; n.rgb = hexRgb(spec.color); n.dying = false;
      (isSat(spec.kind) ? sats : ring).push(n);
    }
    this.layout(scene, ring, sats, fresh);
    this.nodes = ring;
    this.sats = sats;
    this.byId = new Map([...ring, ...sats].map((n) => [n.id, n]));
    this.byId.set("__core", this.core);
    for (const s of sats) s.owner = s.spec.parent ? this.byId.get(s.spec.parent) : undefined;
    const bySlot = new Map<string, N[]>();
    for (const s of sats) if (s.owner) { const l = bySlot.get(s.owner.id) || []; l.push(s); bySlot.set(s.owner.id, l); }
    for (const l of bySlot.values()) l.forEach((s, i) => { s.slot = i; s.slots = l.length; });
    this.sats = sats.filter((s) => s.owner);

    const old = new Map(this.strands.map((s) => [s.node!.id, s]));
    this.strands = ring.map((n) => old.get(n.id) && old.get(n.id)!.node === n ? old.get(n.id)! : { a: this.core, b: n, phase: n.phase, cx: 0, cy: 0, len: 0, kind: "core" as const, node: n });
    this.satStrands = this.sats.map((n) => ({ a: n.owner!, b: n, phase: n.phase, cx: 0, cy: 0, len: 0, kind: "sat" as const, node: n }));
    const live = new Set<Strand>([...this.strands, ...this.satStrands, ...this.spokes]);
    this.pulses = this.pulses.filter((p) => live.has(p.s));
    this.buildWeb();
    if (fresh) {
      this.userMoved = false;
      this.fit(true);
      if (!this.reduced) { const to = { ...this.target }; this.cam = { x: to.x, y: to.y, k: to.k * 1.55 }; this.animateTo(to, 900); }
    }
    this.dirty = true;
  }

  private layout(scene: WebScene, ring: N[], sats: N[], fresh: boolean) {
    const rings: N[][] = [];
    const add = (list: N[], first: number, step: number, cap0: number, capStep: number) => {
      let r = 0, cap = cap0, i = 0;
      for (const n of list) {
        if (!rings[first + r]) rings[first + r] = [];
        rings[first + r].push(n);
        n.ring = first + r;
        if (++i >= cap) { r++; i = 0; cap += capStep; }
      }
      void step;
      return first + (i === 0 ? r : r + 1);
    };
    let radius = (ri: number) => 175 + ri * 118;
    if (scene.mode === "home") {
      const mods = ring.filter((n) => n.kind === "mod").sort((a, b) => (b.spec.weight ?? 0) - (a.spec.weight ?? 0));
      const ghost = ring.filter((n) => n.kind === "ghost");
      const seeds = ring.filter((n) => n.kind === "seed");
      let next = add([...mods, ...ghost], 0, 0, 6, 5);
      if (!mods.length) next = 1;
      add(seeds, Math.max(next, 1), 0, 12, 12);
    } else {
      radius = (ri: number) => 160 + ri * 110;
      const java = ring.filter((n) => n.kind === "file");
      const res = ring.filter((n) => n.kind === "res");
      if (java.length + res.length <= 7) add([...java, ...res], 0, 0, 7, 6);
      else { const nx = add(java, 0, 0, 7, 6); add(res, nx, 0, 8, 8); }
    }
    let maxR = 0;
    const key = scene.key;
    rings.forEach((list, ri) => {
      if (!list) return;
      const R = radius(ri);
      maxR = Math.max(maxR, R);
      const off = ((hashStr(key + ":" + ri) % 1000) / 1000) * TAU;
      list.forEach((n, i) => {
        // seeds avoid a strict even spread: a little jitter reads as "scattered seeds"
        const jitter = n.kind === "seed" ? ((hashStr(n.id) % 100) / 100 - 0.5) * 0.18 : 0;
        const a = off + (i / list.length) * TAU + jitter;
        const rr = R * (n.kind === "seed" ? 1.0 + ((hashStr(n.id + "r") % 100) / 100) * 0.12 : 1);
        n.tx = Math.cos(a) * rr; n.ty = Math.sin(a) * rr * 0.92;
      });
    });
    // relax overlaps (targets only; deterministic)
    const all = ring;
    for (let it = 0; it < 40; it++) {
      for (let i = 0; i < all.length; i++) for (let j = i + 1; j < all.length; j++) {
        const a = all[i], b = all[j];
        const dx = b.tx - a.tx, dy = b.ty - a.ty, d = Math.hypot(dx, dy) || 0.01;
        const min = a.r + b.r + 62;
        if (d < min) { const f = (min - d) / 2 / d; a.tx -= dx * f; a.ty -= dy * f; b.tx += dx * f; b.ty += dy * f; }
      }
      for (const n of all) { const d = Math.hypot(n.tx, n.ty); if (d < 120) { const f = 120 / (d || 1); n.tx *= f; n.ty *= f; } }
    }
    for (const n of all) if (fresh || (n.x === 0 && n.y === 0)) { n.x = n.tx * 0.08; n.y = n.ty * 0.08; }
    for (const s of sats) if (fresh) { s.x = 0; s.y = 0; }
    this.outerR = Math.max(300, maxR + 120);
  }

  // ---------------------------------------------------------- internals ----
  private readTheme() {
    const t = document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark";
    this.setTheme(t);
  }

  private makeStars() {
    const rnd = mulberry(1337);
    this.stars = Array.from({ length: 300 }, () => {
      const z = rnd() < 0.6 ? 0.03 + rnd() * 0.05 : rnd() < 0.8 ? 0.1 + rnd() * 0.1 : 0.24 + rnd() * 0.16;
      return { x: rnd() * 4000, y: rnd() * 4000, z, tw: rnd() * TAU, s: rnd() < 0.06 ? 1.7 : rnd() < 0.35 ? 1.15 : 0.75, c: Math.floor(rnd() * 4) };
    });
  }

  private buildWeb() {
    const rnd = mulberry(424242);
    const spokesN = 30;
    const R = this.outerR;
    const angles = Array.from({ length: spokesN }, (_, i) => (i / spokesN) * TAU + (rnd() - 0.5) * 0.08);
    const sp = new Path2D();
    for (const a of angles) { sp.moveTo(Math.cos(a) * 48, Math.sin(a) * 48); sp.lineTo(Math.cos(a) * R * 1.5, Math.sin(a) * R * 1.5); }
    this.spokePath = sp;
    const web = new Path2D();
    const gap = 44;
    for (let r = 66; r < R * 1.42; r += gap * (0.86 + rnd() * 0.28)) {
      const pts = angles.map((a) => { const rr = r * (0.97 + rnd() * 0.06); return [Math.cos(a) * rr, Math.sin(a) * rr, rr] as const; });
      web.moveTo(pts[0][0], pts[0][1]);
      for (let i = 0; i < spokesN; i++) {
        const p = pts[i], q = pts[(i + 1) % spokesN];
        const am = (angles[i] + (i === spokesN - 1 ? angles[0] + TAU : angles[(i + 1) % spokesN])) / 2;
        const sag = ((p[2] + q[2]) / 2) * 0.955;
        web.quadraticCurveTo(Math.cos(am) * sag, Math.sin(am) * sag, q[0], q[1]);
      }
    }
    this.webPath = web;
    // spokes as strands (thought light that runs out along the web)
    this.spokes = angles.map((a, i) => ({ a: { x: Math.cos(a) * 46, y: Math.sin(a) * 46 }, b: { x: Math.cos(a) * R * 1.05, y: Math.sin(a) * R * 1.05 }, phase: i, cx: Math.cos(a) * R * 0.55, cy: Math.sin(a) * R * 0.55, len: R, kind: "spoke" as const }));
  }

  private spawn(s: Strand, dir: 1 | -1, rgb: Rgb, size = 1, t0 = 0) {
    if (this.pulses.length >= MAX_PULSES) this.pulses.shift();
    const len = Math.max(60, s.len || Math.hypot(s.b.x - s.a.x, s.b.y - s.a.y));
    this.pulses.push({ s, t: t0, dir, rgb, size, speed: ((170 + Math.random() * 90) / len) * (size > 1 ? 1.25 : 1) });
  }

  private sprite(rgb: Rgb, key = "p") {
    const id = key + rgb.join(",");
    let c = this.sprites.get(id);
    if (!c) {
      c = document.createElement("canvas");
      const S = key === "h" ? 128 : 64;
      c.width = c.height = S;
      const g = c.getContext("2d")!;
      const gr = g.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);
      if (key === "h") { gr.addColorStop(0, rgba(rgb, 0.5)); gr.addColorStop(0.32, rgba(rgb, 0.17)); gr.addColorStop(1, rgba(rgb, 0)); }
      else { gr.addColorStop(0, "rgba(255,255,255,1)"); gr.addColorStop(0.13, rgba(mix(rgb, [255, 255, 255], 0.35), 0.95)); gr.addColorStop(0.42, rgba(rgb, 0.26)); gr.addColorStop(1, rgba(rgb, 0)); }
      g.fillStyle = gr; g.fillRect(0, 0, S, S);
      this.sprites.set(id, c);
    }
    return c;
  }

  private labelSprite(text: string, size: number, color: string, weight: number) {
    const key = `${text}|${size}|${color}|${weight}|${this.dpr}`;
    let c = this.labels.get(key);
    if (c) return c;
    if (this.labels.size > 400) this.labels.clear();
    const d = this.dpr;
    const m = document.createElement("canvas").getContext("2d")!;
    const font = `${weight} ${size}px ${this.font}`;
    m.font = font;
    const w = Math.ceil(m.measureText(text).width) + 16;
    const h = Math.ceil(size * 1.5) + 12;
    c = document.createElement("canvas");
    c.width = w * d; c.height = h * d;
    const g = c.getContext("2d")!;
    g.scale(d, d);
    g.font = font; g.textBaseline = "middle"; g.textAlign = "center";
    g.shadowColor = "rgba(2,4,20,0.95)"; g.shadowBlur = 7;
    g.fillStyle = color;
    g.fillText(text, w / 2, h / 2);
    g.shadowBlur = 0;
    g.fillText(text, w / 2, h / 2);
    this.labels.set(key, c);
    return c;
  }

  private resize() {
    const r = this.canvas.getBoundingClientRect();
    this.W = Math.max(1, r.width); this.H = Math.max(1, r.height);
    let dpr = Math.min(2, window.devicePixelRatio || 1);
    if (this.W * this.H * dpr * dpr > 4.6e6) dpr = Math.max(1, Math.sqrt(4.6e6 / (this.W * this.H)));
    this.dpr = dpr;
    this.canvas.width = Math.round(this.W * dpr);
    this.canvas.height = Math.round(this.H * dpr);
    this.bg = null;
    this.labels.clear();
    this.dirty = true;
    if (!this.userMoved && this.scene) this.fit(true);
    if (this.reduced || !this.running) this.frame(performance.now());
  }

  private onVis = () => { if (document.hidden) this.stop(); else if (this.visible) this.start(); };
  private start() {
    if (this.running || this.disposed) return;
    this.running = true; this.last = performance.now();
    this.raf = requestAnimationFrame(this.loop);
  }
  private stop() { this.running = false; cancelAnimationFrame(this.raf); }
  private loop = (now: number) => {
    if (!this.running) return;
    this.frame(now);
    this.raf = requestAnimationFrame(this.loop);
  };

  private animateTo(to: { x: number; y: number; k: number }, dur: number, done?: () => void) {
    if (dur <= 0 || this.reduced) { this.cam = { ...to }; this.target = { ...to }; this.tween = null; this.dirty = true; done?.(); return; }
    this.tween = { from: { ...this.cam }, to, t0: performance.now(), dur, done };
    this.target = { ...to };
  }
  private zoomAt(sx: number, sy: number, f: number) {
    const k0 = this.target.k;
    const k1 = Math.max(0.25, Math.min(4.5, k0 * f));
    const wx = (sx - this.W / 2) / k0 + this.target.x;
    const wy = (sy - this.H / 2) / k0 + this.target.y;
    this.target = { k: k1, x: wx - (sx - this.W / 2) / k1, y: wy - (sy - this.H / 2) / k1 };
    this.tween = null;
    if (this.reduced) this.cam = { ...this.target };
    this.dirty = true;
  }
  private toWorld(sx: number, sy: number) { return { x: (sx - this.W / 2) / this.cam.k + this.cam.x, y: (sy - this.H / 2) / this.cam.k + this.cam.y }; }
  private screenPos(n: P) { return { x: (n.x - this.cam.x) * this.cam.k + this.W / 2, y: (n.y - this.cam.y) * this.cam.k + this.H / 2 }; }

  private hit(sx: number, sy: number): N | null {
    const w = this.toWorld(sx, sy);
    let best: N | null = null, bd = Infinity;
    for (const n of this.sats) {
      if (n.vis < 0.55) continue;
      const d = Math.hypot(n.x - w.x, n.y - w.y);
      if (d < n.r + 7 / this.cam.k && d < bd) { bd = d; best = n; }
    }
    if (best) return best;
    for (const n of [...this.nodes, this.core]) {
      if (n.alpha < 0.5) continue;
      const d = Math.hypot(n.x - w.x, n.y - w.y);
      if (d < n.r + 9 / this.cam.k && d < bd) { bd = d; best = n; }
    }
    return best;
  }
  private setHover(n: N | null) {
    if (n === this.hovered) return;
    this.hovered = n;
    this.canvas.style.cursor = n && n.kind !== "core" ? "pointer" : this.drag ? "grabbing" : "grab";
    this.cb.onHover?.(n && n.kind !== "core" ? n.spec : null);
    this.dirty = true;
  }

  private bind() {
    const c = this.canvas;
    c.addEventListener("pointerdown", this.onDown);
    window.addEventListener("pointermove", this.onMove);
    window.addEventListener("pointerup", this.onUp);
    window.addEventListener("pointercancel", this.onUp);
    c.addEventListener("wheel", this.onWheel, { passive: false });
    c.addEventListener("dblclick", this.onDbl);
    c.addEventListener("pointerleave", this.onLeave);
    c.style.cursor = "grab";
    c.style.touchAction = "none";
  }
  private unbind() {
    const c = this.canvas;
    c.removeEventListener("pointerdown", this.onDown);
    window.removeEventListener("pointermove", this.onMove);
    window.removeEventListener("pointerup", this.onUp);
    window.removeEventListener("pointercancel", this.onUp);
    c.removeEventListener("wheel", this.onWheel);
    c.removeEventListener("dblclick", this.onDbl);
    c.removeEventListener("pointerleave", this.onLeave);
  }
  private local(e: { clientX: number; clientY: number }) { const r = this.canvas.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; }
  private onDown = (e: PointerEvent) => {
    const p = this.local(e);
    this.pointers.set(e.pointerId, p);
    try { this.canvas.setPointerCapture(e.pointerId); } catch { /* noop */ }
    if (this.pointers.size === 2) {
      const [a, b] = [...this.pointers.values()];
      this.drag = { mode: "pinch", sx: (a.x + b.x) / 2, sy: (a.y + b.y) / 2, moved: true, camX: this.cam.x, camY: this.cam.y, dist: Math.hypot(a.x - b.x, a.y - b.y), k0: this.target.k };
      return;
    }
    this.tween = null;
    this.drag = { mode: "pan", sx: p.x, sy: p.y, moved: false, camX: this.target.x, camY: this.target.y, node: this.hit(p.x, p.y) };
  };
  private onMove = (e: PointerEvent) => {
    const p = this.local(e);
    this.pointer.x = Math.max(-1, Math.min(1, (p.x / this.W) * 2 - 1));
    this.pointer.y = Math.max(-1, Math.min(1, (p.y / this.H) * 2 - 1));
    if (this.pointers.has(e.pointerId)) this.pointers.set(e.pointerId, p);
    const d = this.drag;
    if (!d) { if (e.target === this.canvas) this.setHover(this.hit(p.x, p.y)); return; }
    if (d.mode === "pinch" && this.pointers.size >= 2) {
      const [a, b] = [...this.pointers.values()];
      const dist = Math.hypot(a.x - b.x, a.y - b.y);
      const k1 = Math.max(0.25, Math.min(4.5, (d.k0 || 1) * (dist / (d.dist || dist))));
      this.userMoved = true;
      this.zoomAt((a.x + b.x) / 2, (a.y + b.y) / 2, k1 / this.target.k);
      this.cam = { ...this.target };
      return;
    }
    const dx = p.x - d.sx, dy = p.y - d.sy;
    if (!d.moved && Math.hypot(dx, dy) > 4) { d.moved = true; this.canvas.style.cursor = "grabbing"; }
    if (!d.moved) return;
    this.userMoved = true;
    this.target.x = d.camX - dx / this.cam.k; this.target.y = d.camY - dy / this.cam.k;
    this.cam.x = this.target.x; this.cam.y = this.target.y;
    this.dirty = true;
  };
  private onUp = (e: PointerEvent) => {
    this.pointers.delete(e.pointerId);
    const d = this.drag;
    if (!d) return;
    if (d.mode === "pinch") { if (this.pointers.size === 0) this.drag = null; return; }
    this.drag = null;
    this.canvas.style.cursor = this.hovered ? "pointer" : "grab";
    if (!d.moved && d.node && d.node.kind !== "core") this.cb.onOpen?.(d.node.spec);
  };
  private onLeave = () => { if (!this.drag) this.setHover(null); this.pointer.x = 0; this.pointer.y = 0; };
  private onWheel = (e: WheelEvent) => {
    e.preventDefault();
    const p = this.local(e);
    const delta = e.deltaMode === 1 ? e.deltaY * 16 : e.deltaY;
    this.userMoved = true;
    this.zoomAt(p.x, p.y, Math.exp(-delta * (e.ctrlKey ? 0.01 : 0.0015)));
  };
  private onDbl = (e: MouseEvent) => {
    const p = this.local(e);
    const n = this.hit(p.x, p.y);
    if (n && n.kind !== "core") return;
    this.recenter();
  };

  // ------------------------------------------------------------- frame ----
  private frame(now: number) {
    const dt = Math.min(0.05, (now - this.last) / 1000);
    this.last = now;
    const anim = !this.reduced;
    if (anim) this.time += dt;

    // scene transition
    if (this.trans) {
      const u = Math.min(1, (now - this.trans.t0) / this.trans.dur);
      const from = this.trans.from;
      for (const n of [...this.nodes, ...this.sats]) {
        n.alpha = Math.max(0, n.alpha - dt * 3.2);
        if (n !== from) { n.x += (0 - n.x) * Math.min(1, dt * 3); n.y += (0 - n.y) * Math.min(1, dt * 3); }
      }
      this.core.alpha = from ? Math.max(0, 1 - u * 1.6) : 1 - u * 0.4;
      this.dirty = true;
      if (u >= 1) { const next = this.trans.next; this.trans = null; this.core.alpha = 1; this.apply(next, true); }
    }

    // camera
    if (this.tween) {
      const u = Math.min(1, (now - this.tween.t0) / this.tween.dur);
      const e = EASE(u);
      const { from, to } = this.tween;
      this.cam.k = from.k * Math.pow(to.k / from.k, e);
      this.cam.x = from.x + (to.x - from.x) * e; this.cam.y = from.y + (to.y - from.y) * e;
      this.dirty = true;
      if (u >= 1) { const d = this.tween.done; this.tween = null; d?.(); }
    } else {
      const f = 1 - Math.exp(-dt * 12);
      const dx = this.target.x - this.cam.x, dy = this.target.y - this.cam.y, dk = this.target.k - this.cam.k;
      if (Math.abs(dx) + Math.abs(dy) > 0.01 || Math.abs(dk) > 0.0005) { this.cam.x += dx * f; this.cam.y += dy * f; this.cam.k += dk * f; this.dirty = true; }
    }
    // pointer parallax (smoothed)
    const pf = 1 - Math.exp(-dt * 3);
    this.pointer.px += (this.pointer.x - this.pointer.px) * pf;
    this.pointer.py += (this.pointer.y - this.pointer.py) * pf;
    this.energyS += (this.energy - this.energyS) * (1 - Math.exp(-dt * 6));

    if (!this.trans) {
      // nodes ease to their targets (with a gentle drift), fade in after `born`
      const f = this.reduced ? 1 : 1 - Math.exp(-dt * 3.2);
      for (const n of this.nodes) {
        const drift = anim ? 3.5 : 0;
        const gx = n.tx + Math.sin(this.time * 0.31 + n.phase) * drift, gy = n.ty + Math.cos(this.time * 0.27 + n.phase * 1.3) * drift;
        if (this.time >= n.born) {
          n.x += (gx - n.x) * f; n.y += (gy - n.y) * f;
          n.alpha = Math.min(1, n.alpha + (this.reduced ? 1 : dt * 2.6));
        }
      }
      this.layoutSats(dt);
    }

    if (anim) {
      this.updatePulses(dt);
      for (const n of [this.core, ...this.nodes, ...this.sats]) {
        if (n.flash > 0) n.flash = Math.max(0, n.flash - dt * 0.9);
        if (n.ripples.length) n.ripples = n.ripples.map((r) => r + dt).filter((r) => r < 1.6);
      }
      if (this.scanR >= 0) {
        const prevR = this.scanR;
        this.scanR += dt * 260;
        for (const n of this.nodes) { const d = Math.hypot(n.x, n.y); if (d > prevR && d <= this.scanR) n.flash = Math.max(n.flash, 0.9); }
        if (this.scanR > this.outerR * 1.2) this.scanR = -1;
      }
      if (this.bloomT >= 0) { this.bloomT += dt; if (this.bloomT > 1.8) this.bloomT = -1; }
      this.dirty = true;
    }
    if (!this.dirty) return;
    this.dirty = false;
    this.draw();
  }

  private layoutSats(dt: number) {
    const zoomOpen = this.cam.k > Math.max(1.35, this.fitK * 1.4);
    const hov = this.hovered;
    const clock = performance.now() / 1000;
    const projectMode = this.scene?.mode === "project";
    const f = this.reduced ? 1 : 1 - Math.exp(-dt * 7);
    const owners = new Set(this.sats.map((s) => s.owner!));
    for (const o of owners) {
      const engaged = hov === o || hov?.owner === o || this.focusId === o.id;
      if (engaged) o.holdUntil = clock + 0.9;
      const target = projectMode || this.showSats || zoomOpen || engaged || o.holdUntil > clock ? 1 : 0;
      const v = o.alpha * target;
      if (Math.abs(v - o.expand) > 0.001) { o.expand += (v - o.expand) * f; this.dirty = true; } else o.expand = v;
    }
    const t = this.reduced ? 0 : this.time;
    for (const s of this.sats) {
      const o = s.owner!;
      s.vis = o.expand * (this.time >= s.born ? 1 : 0);
      s.alpha = s.vis;
      const out = Math.hypot(o.x, o.y) > 1 ? Math.atan2(o.y, o.x) : -Math.PI / 2;
      const n = Math.max(1, s.slots), i = s.slot;
      const spread = Math.min(projectMode ? 2.9 : 2.3, 0.42 * (n - 1) + (n > 1 ? 0.3 : 0));
      const a = out + (n > 1 ? -spread / 2 + (i * spread) / (n - 1) : 0) + Math.sin(t * 0.4 + s.phase) * 0.02;
      const tier = projectMode && n > 7 ? (i % 2 ? 26 : 0) : 0;
      const dist = o.r + 6 + s.vis * ((projectMode ? 52 : 34) + tier);
      s.x = o.x + Math.cos(a) * dist;
      s.y = o.y + Math.sin(a) * dist;
    }
  }

  private updatePulses(dt: number) {
    const home = this.scene?.mode === "home";
    // ambient: a slow trickle on the home web; running nodes keep their thread busy
    for (const s of this.strands) {
      const n = s.node!;
      if (n.alpha < 0.5) continue;
      const run = n.spec.status === "running" || n.spec.live;
      const rate = (home ? (n.kind === "seed" ? 0.006 : 0.028) : 0.012) + (run ? (n.spec.live ? 2.4 : 0.9) : 0);
      if (Math.random() < rate * dt) this.spawn(s, run ? 1 : Math.random() < 0.5 ? 1 : -1, n.spec.live ? HOT_C : n.rgb, run ? 1.1 : 0.75);
    }
    // composer energy: light runs out along the web's spokes
    if (this.energyS > 0.02 && this.spokes.length) {
      this.emitAcc += this.energyS * dt * 9;
      while (this.emitAcc >= 1) {
        this.emitAcc -= 1;
        const s = this.spokes[Math.floor(Math.random() * this.spokes.length)];
        this.spawn(s, 1, Math.random() < 0.5 ? HOT_V : HOT_C, 0.7 + this.energyS * 0.6);
      }
    }
    const out: Pulse[] = [];
    for (const p of this.pulses) {
      p.t += p.speed * dt;
      if (p.t < 1.1) out.push(p);
      else if (p.s.kind !== "spoke") { const dest = (p.dir === 1 ? p.s.b : p.s.a) as N; if ("flash" in dest) dest.flash = Math.min(1.2, dest.flash + 0.1 * p.size); }
    }
    this.pulses = out;
  }

  private strandGeom(s: Strand) {
    const ax = s.a.x, ay = s.a.y, bx = s.b.x, by = s.b.y;
    const len = Math.hypot(bx - ax, by - ay);
    const sway = this.reduced ? 0 : Math.sin(this.time * 0.7 + s.phase) * 0.012;
    const sag = len * (0.07 + sway);
    const nx = -(by - ay) / (len || 1), ny = (bx - ax) / (len || 1);
    const sgn = ny >= 0 ? 1 : -1;
    s.cx = (ax + bx) / 2 + nx * sgn * 0.6 * sag;
    s.cy = (ay + by) / 2 + (ny * sgn * 0.6 + 0.4) * sag;
    s.len = len;
  }

  private drawBackground() {
    const { ctx, W, H } = this;
    const pal = PALETTE[this.theme];
    // Quarter-res background (gradient + aurora), refreshed ~7x/s: the aurora moves slowly.
    if (!this.bg || (!this.reduced && this.time - this.bgAt > 0.14)) {
      const c = this.bg ?? document.createElement("canvas");
      c.width = Math.max(2, Math.ceil(W / 4)); c.height = Math.max(2, Math.ceil(H / 4));
      const g = c.getContext("2d")!;
      const cw = c.width, ch = c.height;
      const core = this.screenPos(this.core);
      const gx = core.x / 4, gy = core.y / 4;
      const bg = g.createRadialGradient(gx, gy, 0, gx, gy, Math.max(cw, ch) * 0.9);
      bg.addColorStop(0, pal.bg[0]); bg.addColorStop(0.5, pal.bg[1]); bg.addColorStop(1, pal.bg[2]);
      g.fillStyle = bg; g.fillRect(0, 0, cw, ch);
      const t = this.time;
      const blobs: [Rgb, number, number, number, number][] = this.theme === "light"
        ? [[BRAND.violet, 0.18, 0.12, 0.62, 0.9], [BRAND.magenta, 0.86, 0.1, 0.5, 0.55], [BRAND.cyan, 0.78, 0.96, 0.55, 0.5], [BRAND.blue, 0.1, 0.9, 0.6, 0.7]]
        : [[BRAND.violet, 0.2, 0.15, 0.6, 0.85], [BRAND.blue, 0.85, 0.2, 0.55, 0.65], [BRAND.cyan, 0.75, 0.95, 0.5, 0.4], [BRAND.magenta, 0.08, 0.92, 0.5, 0.42]];
      g.globalCompositeOperation = "lighter";
      blobs.forEach(([rgb, bx, by, rad, a], i) => {
        const px = (bx + Math.sin(t * 0.035 + i * 1.7) * 0.06 - this.pointer.px * 0.015) * cw;
        const py = (by + Math.cos(t * 0.03 + i * 2.3) * 0.05 - this.pointer.py * 0.015) * ch;
        const rr = rad * Math.max(cw, ch);
        const gr = g.createRadialGradient(px, py, 0, px, py, rr);
        gr.addColorStop(0, rgba(rgb, pal.aurora * a)); gr.addColorStop(0.45, rgba(rgb, pal.aurora * a * 0.35)); gr.addColorStop(1, rgba(rgb, 0));
        g.fillStyle = gr; g.fillRect(0, 0, cw, ch);
      });
      g.globalCompositeOperation = "source-over";
      this.bg = c; this.bgAt = this.time;
    }
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage(this.bg, 0, 0, W, H);
    // stars: three depths, camera + pointer parallax, gentle twinkle
    const cols = ["rgba(205,214,255,", "rgba(170,150,255,", "rgba(150,225,255,", "rgba(235,170,255,"];
    const { cam } = this;
    for (const s of this.stars) {
      const px = (((s.x - cam.x * s.z * cam.k - this.pointer.px * 40 * s.z * 3) % W) + W) % W;
      const py = (((s.y - cam.y * s.z * cam.k - this.pointer.py * 40 * s.z * 3) % H) + H) % H;
      const tw = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(this.time * (0.5 + s.z * 3) + s.tw));
      ctx.fillStyle = cols[s.c] + (pal.star * tw * (s.z > 0.2 ? 0.9 : 0.55)).toFixed(3) + ")";
      ctx.fillRect(px, py, s.s, s.s);
    }
  }

  private draw() {
    const { ctx, dpr, W, H, cam } = this;
    const pal = PALETTE[this.theme];
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.globalCompositeOperation = "source-over";
    ctx.globalAlpha = 1;
    this.drawBackground();

    // world transform (+ a few px of pointer parallax on the web layer)
    const k = cam.k;
    const ox = -this.pointer.px * 6, oy = -this.pointer.py * 5;
    ctx.setTransform(dpr * k, 0, 0, dpr * k, dpr * (W / 2 - cam.x * k + ox), dpr * (H / 2 - cam.y * k + oy));
    const hair = 1 / k;
    const coreRgb = this.core.rgb;

    // orb-web, fading out with distance
    if (this.spokePath && this.webPath) {
      const R = this.outerR * 1.35;
      const fade = (a: number, rgb: Rgb) => {
        const g = ctx.createRadialGradient(0, 0, 40, 0, 0, R);
        g.addColorStop(0, rgba(rgb, a * 1.6)); g.addColorStop(0.45, rgba(rgb, a)); g.addColorStop(1, rgba(rgb, 0));
        return g;
      };
      const webRgb = mix(BRAND.blue, BRAND.violet, 0.45);
      const off = this.scene?.offline ? 0.5 : 1;
      ctx.lineWidth = 0.85 * hair;
      ctx.strokeStyle = fade(pal.web * off, webRgb);
      ctx.stroke(this.spokePath);
      ctx.strokeStyle = fade(pal.webRing * off, mix(webRgb, BRAND.cyan, 0.25));
      ctx.stroke(this.webPath);
    }
    // central glow
    {
      const gr = this.outerR * 0.95 * (1 + this.energyS * 0.12);
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = (this.scene?.offline ? 0.12 : 0.26) + this.energyS * 0.2 + this.core.flash * 0.1;
      ctx.drawImage(this.sprite(mix(coreRgb, BRAND.blue, 0.3), "h"), -gr, -gr, gr * 2, gr * 2);
      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = "source-over";
    }

    const hovRaw = this.hovered || (this.focusId ? this.byId.get(this.focusId) || null : null);
    const hov = hovRaw && isSat(hovRaw.kind) ? hovRaw.owner ?? null : hovRaw;
    for (const s of this.strands) this.strandGeom(s);
    for (const s of this.satStrands) if (s.node!.vis > 0.02) this.strandGeom(s);

    // strands: base (batched) + live / hovered (individually)
    ctx.lineCap = "round";
    ctx.beginPath();
    for (const s of this.strands) {
      const n = s.node!;
      if (n === hov || n.spec.status === "running" || n.spec.live || n.alpha < 0.02 || n.kind === "seed" || n.kind === "ghost") continue;
      ctx.moveTo(s.a.x, s.a.y); ctx.quadraticCurveTo(s.cx, s.cy, s.b.x, s.b.y);
    }
    ctx.lineWidth = 1.05 * hair;
    ctx.strokeStyle = rgba(mix(BRAND.violet, BRAND.blue, 0.4), hov ? pal.strand * 0.55 : pal.strand);
    ctx.stroke();
    for (const s of this.strands) {
      const n = s.node!;
      if (n.alpha < 0.02) continue;
      if (n.kind === "seed" || n.kind === "ghost") {
        ctx.save(); ctx.setLineDash([3 * hair, 6 * hair]); ctx.lineDashOffset = -this.time * 4;
        ctx.beginPath(); ctx.moveTo(s.a.x, s.a.y); ctx.quadraticCurveTo(s.cx, s.cy, s.b.x, s.b.y);
        ctx.lineWidth = hair; ctx.strokeStyle = rgba(n.rgb, (n === hov ? 0.55 : n.kind === "ghost" ? 0.2 : 0.11) * n.alpha); ctx.stroke(); ctx.restore();
        continue;
      }
      const run = n.spec.status === "running" || n.spec.live;
      if (!run && n !== hov) continue;
      const g = ctx.createLinearGradient(this.core.x, this.core.y, n.x, n.y);
      const breathe = run ? 0.45 + 0.2 * Math.sin(this.time * 3 + n.phase) : 0.85;
      g.addColorStop(0, rgba(mix(coreRgb, [255, 255, 255], 0.2), breathe * 0.6 * n.alpha));
      g.addColorStop(1, rgba(n.rgb, breathe * n.alpha));
      ctx.beginPath(); ctx.moveTo(s.a.x, s.a.y); ctx.quadraticCurveTo(s.cx, s.cy, s.b.x, s.b.y);
      ctx.lineWidth = (n.spec.live ? 2 : 1.6) * hair; ctx.strokeStyle = g; ctx.stroke();
    }
    // satellite silk
    for (const s of this.satStrands) {
      const n = s.node!;
      if (n.vis < 0.04) continue;
      const on = hovRaw === n || hovRaw === n.owner;
      ctx.beginPath(); ctx.moveTo(s.a.x, s.a.y); ctx.quadraticCurveTo(s.cx, s.cy, s.b.x, s.b.y);
      ctx.lineWidth = (on ? 1.3 : 0.8) * hair; ctx.strokeStyle = rgba(n.rgb, (on ? 0.6 : 0.24) * n.vis); ctx.stroke();
    }

    // pulses (additive light)
    ctx.globalCompositeOperation = "lighter";
    for (const p of this.pulses) {
      const s = p.s;
      if (s.node && s.node.alpha < 0.1) continue;
      const vis = s.kind === "sat" ? s.node!.vis : s.kind === "spoke" ? 0.85 : 1;
      const dim = hov && s.node && s.node !== hov && s.kind !== "spoke" ? 0.45 : 1;
      const spr = this.sprite(p.rgb);
      const trail = k * p.size < 0.55 ? 1 : 4;
      for (let j = 0; j < trail; j++) {
        let t = p.t - j * 0.022;
        if (t < 0 || t > 1) continue;
        if (p.dir === -1) t = 1 - t;
        const u = 1 - t;
        const x = u * u * s.a.x + 2 * u * t * s.cx + t * t * s.b.x;
        const y = u * u * s.a.y + 2 * u * t * s.cy + t * t * s.b.y;
        const fadeEnds = s.kind === "spoke" ? Math.sin(Math.PI * Math.min(1, Math.max(0, t))) : 1;
        const sz = (j === 0 ? 14 : 10 - j * 2) * p.size * hair;
        ctx.globalAlpha = (j === 0 ? 1 : 0.55 - j * 0.12) * dim * vis * fadeEnds;
        ctx.drawImage(spr, x - sz / 2, y - sz / 2, sz, sz);
      }
    }
    ctx.globalAlpha = 1;

    // halos (additive)
    for (const n of this.nodes) {
      if (n.alpha < 0.05 || n.kind === "ghost" || n.kind === "seed") continue;
      const run = n.spec.status === "running" || n.spec.live;
      const breathe = run ? 1 + 0.2 * Math.sin(this.time * 2.6 + n.phase) : 1 + 0.05 * Math.sin(this.time * 0.9 + n.phase);
      let a = 0.26 + (run ? 0.45 : 0) + n.flash * 0.4 + (n === hov ? 0.25 : 0);
      let rgb = n.rgb;
      if (n.spec.status === "bad") { rgb = BRAND.bad; a = 0.22; }
      const size = (5.4 + n.flash * 1.6) * n.r * breathe;
      if (size * k < 10) continue;
      ctx.globalAlpha = Math.min(1, a) * n.alpha * (hov && hov !== n ? 0.55 : 1);
      ctx.drawImage(this.sprite(rgb, "h"), n.x - size / 2, n.y - size / 2, size, size);
    }
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = "source-over";

    // ripples + scan ring + bloom
    for (const n of [this.core, ...this.nodes]) for (const r of n.ripples) {
      if (r < 0) continue;
      const u = r / 1.6;
      ctx.beginPath(); ctx.arc(n.x, n.y, n.r + u * (n === this.core ? 140 : 60), 0, TAU);
      ctx.lineWidth = 1.2 * hair; ctx.strokeStyle = rgba(n === this.core ? HOT_V : n.rgb, 0.5 * (1 - u)); ctx.stroke();
    }
    if (this.scanR >= 0) {
      const u = this.scanR / (this.outerR * 1.2);
      ctx.beginPath(); ctx.arc(0, 0, this.scanR, 0, TAU);
      ctx.lineWidth = 2 * hair; ctx.strokeStyle = rgba(BRAND.cyan, 0.55 * (1 - u)); ctx.stroke();
      ctx.beginPath(); ctx.arc(0, 0, Math.max(0, this.scanR - 14), 0, TAU);
      ctx.lineWidth = 8 * hair; ctx.strokeStyle = rgba(BRAND.cyan, 0.08 * (1 - u)); ctx.stroke();
    }
    if (this.bloomT >= 0) {
      const u = this.bloomT / 1.8;
      const gr = CORE_R * (2 + u * 12);
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = 0.55 * (1 - u);
      ctx.drawImage(this.sprite(HOT_V, "h"), -gr, -gr, gr * 2, gr * 2);
      ctx.globalAlpha = 1; ctx.globalCompositeOperation = "source-over";
    }

    // nodes
    this.labelQ = [];
    for (const n of this.nodes) {
      if (n.alpha < 0.02) continue;
      if (n.kind === "ghost") this.drawGhost(n, hov);
      else if (n.kind === "seed") this.drawSeed(n, hov);
      else this.drawOrb(n, hov);
    }
    this.drawSats(hovRaw);
    this.drawCore();

    // labels in screen space
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    for (const l of this.labelQ) {
      const spr = this.labelSprite(l.text, l.size, l.color, l.weight);
      const w = spr.width / dpr, h = spr.height / dpr;
      ctx.globalAlpha = l.alpha;
      ctx.drawImage(spr, Math.round(l.x - w / 2), Math.round(l.above ? l.y - h + 6 : l.y - 6), w, h);
    }
    ctx.globalAlpha = 1;
    this.positionPins();
  }

  private queueLabel(n: N, text: string, alpha: number, o: { color?: string; size?: number; weight?: number; above?: boolean; r?: number } = {}) {
    if (alpha < 0.03) return;
    const p = this.screenPos(n);
    const ox = -this.pointer.px * 6, oy = -this.pointer.py * 5;
    const rr = (o.r ?? n.r) * this.cam.k;
    const above = !!o.above;
    const t = text.length > 26 ? text.slice(0, 25) + "…" : text;
    this.labelQ.push({ x: p.x + ox, y: above ? p.y + oy - rr - 6 : p.y + oy + rr + 6, text: t, alpha, color: o.color ?? PALETTE[this.theme].labelInk, size: o.size ?? 12, weight: o.weight ?? 500, above });
  }

  private drawOrb(n: N, hov: N | null) {
    const { ctx } = this; const hair = 1 / this.cam.k; const t = this.time; const k = this.cam.k;
    const isHov = hov === n;
    const dim = hov && !isHov ? 0.6 : 1;
    const run = n.spec.status === "running" || n.spec.live;
    const bad = n.spec.status === "bad";
    const rgb = n.rgb;
    const grow = Math.min(1, n.alpha * 1.15);
    const breathe = run ? 1 + 0.05 * Math.sin(t * 2.6 + n.phase) : 1;
    const r = n.r * breathe * (0.6 + 0.4 * grow) + (isHov ? 2 : 0);
    ctx.globalAlpha = n.alpha * dim;
    // body: a dark glass bead with a soft top-left highlight (depth)
    const square = n.kind === "res";
    const shape = () => {
      ctx.beginPath();
      if (square) { const s = r * 0.92; const rad = s * 0.38; ctx.roundRect(n.x - s, n.y - s, s * 2, s * 2, rad); }
      else ctx.arc(n.x, n.y, r, 0, TAU);
    };
    shape();
    ctx.fillStyle = PALETTE[this.theme].body; ctx.fill();
    const hl = ctx.createRadialGradient(n.x - r * 0.35, n.y - r * 0.45, 0, n.x, n.y, r * 1.1);
    hl.addColorStop(0, rgba(mix(rgb, [255, 255, 255], 0.35), 0.34)); hl.addColorStop(0.55, rgba(rgb, 0.1)); hl.addColorStop(1, rgba(rgb, 0.02));
    ctx.fillStyle = hl; ctx.fill();
    ctx.lineWidth = (isHov ? 1.9 : 1.35) * hair;
    ctx.strokeStyle = rgba(bad ? BRAND.bad : rgb, 0.6 + (isHov ? 0.3 : 0) + n.flash * 0.25);
    ctx.stroke();
    if (r * k >= 7) {
      // inner ring
      ctx.beginPath();
      if (square) { const s = r * 0.92 - 3.2; ctx.roundRect(n.x - s, n.y - s, s * 2, s * 2, s * 0.34); } else ctx.arc(n.x, n.y, r - 3.4, 0, TAU);
      ctx.lineWidth = 0.6 * hair; ctx.strokeStyle = rgba(rgb, 0.22); ctx.stroke();
      // glyph
      const gl = n.spec.glyph ?? (n.spec.label[0] || "?").toUpperCase();
      ctx.fillStyle = rgba(mix(rgb, [255, 255, 255], 0.55), 0.92);
      ctx.font = `600 ${Math.max(6, r * (gl.length > 1 ? 0.62 : 0.78))}px ${gl.length > 1 ? this.mono : this.font}`;
      ctx.textAlign = "center"; ctx.textBaseline = "middle";
      ctx.fillText(gl, n.x, n.y + r * 0.04);
    }
    // running: progress ring / sweeping arcs + orbiters
    if (run) {
      const p = n.spec.progress;
      if (p !== undefined && n.kind === "mod") {
        ctx.beginPath(); ctx.arc(n.x, n.y, r + 5, 0, TAU); ctx.lineWidth = 1.2 * hair; ctx.strokeStyle = rgba(rgb, 0.16); ctx.stroke();
