// Cyrus: what the network shows. Pure (no DOM), unit-tested in test/cyrus.test.ts.
//
// HOME    core = Cyrus; ring = your mods (running first, then most recent); satellites = each
//         mod's versions; "+ New mod" ghost; outer ring = template seeds.
// PROJECT core = the mod; ring = its source files (Java orbs, resource squares); satellites
//         = /commands + permission nodes (on plugin.yml) and config keys (on config.yml).
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import { cyrusModel } from "@/lib/cyrus/models";
import { hashSeed, versionNumber, viewMeta, type CyrusProject } from "@/lib/cyrus/projects";
import type { CyrusTemplate } from "@/lib/cyrus/templates";
import type { WebNodeSpec, WebScene, WebStatus } from "./engine";

export const BRAND_HEX = { violet: "#8c3ae9", blue: "#2f7eef", cyan: "#14c5e4", magenta: "#d623e1" } as const;
const MOD_HUES = ["#8c3ae9", "#2f7eef", "#14c5e4", "#d623e1", "#5b6cf5", "#b14fe8"];

/** A mod's own colour (stable per project). */
export const modColor = (rootId: string) => MOD_HUES[hashSeed(rootId) % MOD_HUES.length];

export const PROGRESS: Record<string, number> = { queued: 0.04, planning: 0.14, coding: 0.4, compiling: 0.62, repairing: 0.72, scanning: 0.88, succeeded: 1, failed: 1 };

export const STAGE_HEADLINE: Record<string, string> = {
  queued: "Waiting for a free builder",
  planning: "Mapping out your mod",
  coding: "Weaving the code",
  compiling: "Compiling it into a real plugin",
  repairing: "Found a problem, fixing it",
  scanning: "Running the safety check",
  succeeded: "Your mod is ready",
  failed: "This one didn't build",
};

const projectStatus = (p: CyrusProject): WebStatus => (p.running ? "running" : p.head ? "ok" : "bad");
const buildStatus = (b: ModBuildView): WebStatus => (!isTerminal(b.status) ? "running" : b.status === "succeeded" ? "ok" : "bad");
const CAT_HUE: Record<string, string> = { Gameplay: BRAND_HEX.violet, Economy: BRAND_HEX.cyan, Social: BRAND_HEX.magenta, Admin: BRAND_HEX.blue, World: "#5b6cf5" };

export const modNodeId = (rootId: string) => `m:${rootId}`;
export const seedNodeId = (tplId: string) => `t:${tplId}`;
export const fileNodeId = (path: string) => `f:${path}`;

export function homeScene(projects: CyrusProject[], templates: CyrusTemplate[], opts: { offline?: boolean; maxSeeds?: number } = {}): WebScene {
  const nodes: WebNodeSpec[] = [];
  for (const p of projects.slice(0, 40)) {
    const id = modNodeId(p.rootId);
    nodes.push({
      id, kind: "mod", label: p.title, color: modColor(p.rootId), status: projectStatus(p),
      progress: p.running ? PROGRESS[p.running.status] ?? 0.1 : undefined,
      weight: (p.running ? 1e15 : 0) + (p.meta.favourite ? 1e14 : 0) + (Date.parse(p.updatedAt) || 0),
      glyph: (p.title.trim()[0] || "M").toUpperCase(),
      sub: p.running ? "Building now" : `${p.builds.length} version${p.builds.length === 1 ? "" : "s"}`,
    });
    // versions fan out on hover / zoom (newest 8)
    for (const b of p.builds.slice(-8)) {
      nodes.push({ id: `v:${b.id}`, kind: "ver", parent: id, label: `v${versionNumber(p, b.id)}`, color: modColor(p.rootId), status: buildStatus(b) });
    }
  }
  nodes.push({ id: "ghost", kind: "ghost", label: "New mod", color: BRAND_HEX.violet, weight: -1 });
  for (const t of templates.slice(0, opts.maxSeeds ?? 8)) {
    nodes.push({ id: seedNodeId(t.id), kind: "seed", label: t.title, color: CAT_HUE[t.cat] ?? BRAND_HEX.violet, sub: t.blurb });
  }
  return { key: "home", mode: "home", core: { label: "Cyrus", color: BRAND_HEX.violet }, nodes, offline: opts.offline };
}

export type SceneFile = { path: string; live?: boolean };

/** Files worth showing as nodes: the plugin's own source (no Gradle template, no summary json). */
export const webFiles = (files: { path: string }[]) =>
  files.filter((f) => f.path.startsWith("src/main/java/") || f.path.startsWith("src/main/resources/"));

export function projectScene(project: CyrusProject, b: ModBuildView, files: SceneFile[], opts: { offline?: boolean } = {}): WebScene {
  const nodes: WebNodeSpec[] = [];
  const model = cyrusModel(viewMeta(b).model);
  const color = modColor(project.rootId);
  const seen = new Set<string>();
  let pluginYml: string | null = null, configYml: string | null = null;
  for (const f of files) {
    if (seen.has(f.path)) continue;
    seen.add(f.path);
    const name = f.path.split("/").pop() || f.path;
    const java = name.endsWith(".java");
    const id = fileNodeId(f.path);
    if (name === "plugin.yml") pluginYml = id;
    if (name === "config.yml") configYml = id;
    nodes.push({
      id, kind: java ? "file" : "res", label: name, color: java ? (name.replace(/\.java$/, "") === b.pluginName || /Plugin\.java$/.test(name) ? model.hue : BRAND_HEX.violet) : BRAND_HEX.cyan,
      glyph: java ? "{}" : name.endsWith(".yml") || name.endsWith(".yaml") ? "≡" : "·",
      status: f.live ? "running" : "idle", live: !!f.live,
      weight: java ? 2 : 1,
      sub: f.path.replace(/^src\/main\/(java|resources)\//, ""),
    });
  }
  const r = b.status === "succeeded" ? b.result : null;
  const owner = pluginYml ?? nodes[0]?.id ?? null;
  if (r && owner) {
    for (const c of r.commands.slice(0, 10)) nodes.push({ id: `c:${c.usage}`, kind: "cmd", parent: owner, label: c.usage.split(" ")[0] || c.usage, color: BRAND_HEX.blue, sub: c.description });
    for (const p of r.permissions.slice(0, 8)) nodes.push({ id: `p:${p.node}`, kind: "perm", parent: owner, label: p.node, color: BRAND_HEX.magenta, sub: p.description });
    for (const c of r.config.slice(0, 10)) nodes.push({ id: `k:${c.key}`, kind: "cfg", parent: configYml ?? owner, label: c.key, color: BRAND_HEX.cyan, sub: c.description });
  }
  const seenStages = Array.from(new Set((b.result?.events ?? []).map((e) => e.stage)));
  return {
    key: `p:${project.rootId}`, mode: "project",
    core: { label: project.title, color },
    nodes,
    stage: { status: b.status, repairs: b.result?.repairs ?? 0, seen: seenStages },
    offline: opts.offline,
  };
}

/** Map one build event to what the web should do (null = nothing). Pure, tested. */
export type WebAction = { kind: "emit" | "inward" | "ripple" | "gather" | "scan" | "bloom" | "warn"; file?: string };
export function eventAction(message: string, stage: string): WebAction | null {
  let m = message.match(/^Reading (.+)$/);
  if (m) return { kind: "inward", file: m[1] };
  m = message.match(/^(Wrote|Edited) (.+)$/);
  if (m) return { kind: "ripple", file: m[2] };
  if (/^Compiling against/.test(message)) return { kind: "gather" };
  if (/^Compiled successfully/.test(message)) return { kind: "ripple" };
  if (stage === "repairing" && /found|flagged|problem/i.test(message)) return { kind: "warn" };
  if (/^Running the safety check/.test(message)) return { kind: "scan" };
  if (stage === "succeeded") return { kind: "bloom" };
  return null;
}

