"use client";

// The code view. While a build runs it shows the REAL workspace filling in (useLive):
// the file being written types itself out at the speed the AI writes it, files that land
// get a check, edited lines glow once. When the build is done it shows the final source.
import { memo, useEffect, useMemo, useRef, useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import { diffLines } from "@/lib/cyrus/diff";
import { CyIcon } from "./icons";
import { highlight, langOf } from "./highlight";
import { useSource } from "./source";
import { useTypewriter, type LiveState } from "./useLive";

const EV = /^(Wrote|Edited|Reading) (.+)$/;

/** File names the AI touched, from the real build events ("Wrote Main.java"). Fallback when live code is unavailable. */
export function touchedFiles(b: ModBuildView): { name: string; verb: "Wrote" | "Edited" | "Reading"; at: string }[] {
  const out = new Map<string, { name: string; verb: "Wrote" | "Edited" | "Reading"; at: string }>();
  for (const e of b.result?.events ?? []) {
    const m = e.message.match(EV);
    if (!m) continue;
    const verb = m[1] as "Wrote" | "Edited" | "Reading";
    const prev = out.get(m[2]);
    if (verb === "Reading" && prev) continue;
    out.set(m[2], { name: m[2], verb: prev && prev.verb !== "Reading" && verb === "Reading" ? prev.verb : verb, at: e.at });
  }
  return Array.from(out.values());
}

export const visibleSrc = (files: { path: string; size: number }[]) => files.filter((f) => f.path.startsWith("src/") || f.path === "modbuilder.json" || f.path.endsWith(".kts"));

type Row = { path: string; name: string; state: "writing" | "editing" | "written" | "edited" | "base" | "ready" | "named"; src: "live" | "final" | "base" | "none" };

export function LiveCode({ build, base, live, focusPath, onPick }: {
  build: ModBuildView;
  base?: ModBuildView | null;
  live: LiveState;
  /** a file picked on the web */
  focusPath?: string | null;
  onPick?: (path: string) => void;
}) {
  const running = !isTerminal(build.status);
  const finalFiles = visibleSrc(build.result?.files ?? []).filter((f) => !f.path.endsWith(".kts"));

  const rows: Row[] = useMemo(() => {
    if (!running && finalFiles.length) return finalFiles.map((f) => ({ path: f.path, name: f.path.split("/").pop()!, state: "ready" as const, src: "final" as const }));
    const out = new Map<string, Row>();
    for (const f of visibleSrc(base?.result?.files ?? []).filter((x) => x.path.startsWith("src/main/"))) out.set(f.path, { path: f.path, name: f.path.split("/").pop()!, state: "base", src: "base" });
    for (const f of live.files.values()) out.set(f.path, { path: f.path, name: f.path.split("/").pop()!, state: f.state, src: "live" });
    if (live.supported === false) {
      for (const t of touchedFiles(build).filter((x) => x.verb !== "Reading")) {
        if (![...out.values()].some((r) => r.name === t.name)) out.set(t.name, { path: t.name, name: t.name, state: "named", src: "none" });
      }
    }
    return [...out.values()];
  }, [running, finalFiles, base, live, build]);

  const [sel, setSel] = useState<string | null>(null);
  const [follow, setFollow] = useState(true);
  useEffect(() => { if (focusPath) { setSel(focusPath); setFollow(false); } }, [focusPath]);
  useEffect(() => { setFollow(true); setSel(null); }, [build.id]);
  const writing = live.draft && !live.draft.done ? live.draft.path : null;
  const newest = running ? writing ?? [...live.files.values()].sort((a, b) => b.changedAt - a.changedAt)[0]?.path ?? null : null;
  const pickDefault = () => {
    const java = rows.filter((r) => r.name.endsWith(".java"));
    const pn = build.pluginName;
    return (pn && java.find((r) => r.name === `${pn}.java` || r.name === `${pn}Plugin.java`)) || java.find((r) => /Plugin\.java$|Main\.java$/.test(r.name)) || java[0] || rows[0] || null;
  };
  const current = (running && follow && newest ? rows.find((r) => r.path === newest) : null) ?? rows.find((r) => r.path === sel) ?? pickDefault();

  const groups = useMemo(() => {
    const g: Record<string, Row[]> = { Code: [], "Plugin files": [] };
    for (const r of rows) (r.name.endsWith(".java") ? g.Code : g["Plugin files"]).push(r);
    return Object.entries(g).filter(([, v]) => v.length);
  }, [rows]);

  const touched = rows.filter((r) => r.state === "writing" || r.state === "editing" || r.state === "written" || r.state === "edited").length;

  return (
    <div className="cy-code">
      <nav className="cy-tree" aria-label="Files">
        <div className="cy-tree-head">
          {running ? <span className="cy-live"><i />{live.supported === false ? "Building" : "Live"}</span> : <span className="cy-tree-count">{rows.length} files</span>}
          {running && touched > 0 && <span className="cy-tree-count">{touched} written</span>}
        </div>
        {rows.length === 0 && (
          <div className="cy-tree-empty">
            <span className="cy-skel" style={{ width: "72%" }} /><span className="cy-skel" style={{ width: "54%" }} /><span className="cy-skel" style={{ width: "63%" }} />
            <p>{running ? "Files appear the moment Cyrus starts writing them." : "No source for this version."}</p>
          </div>
        )}
        {groups.map(([dir, list]) => (
          <div key={dir} className="cy-tree-g">
            <div className="cy-tree-dir">{dir}</div>
            {list.map((r) => (
              <button key={r.path} type="button" title={r.path} className={`cy-tree-f ${current?.path === r.path ? "on" : ""} st-${r.state}`}
                      onClick={() => { setSel(r.path); setFollow(false); onPick?.(r.path); }}>
                <span className={`cy-fdot ${r.name.endsWith(".java") ? "j" : "y"}`} />
                <span className="cy-tree-n">{r.name}</span>
                {(r.state === "writing" || r.state === "editing") && <span className="cy-fstate run">{r.state === "writing" ? "writing" : "editing"}</span>}
                {(r.state === "written" || r.state === "edited") && <span className="cy-fstate ok"><CyIcon name="check" size={10} strokeWidth={2.6} /></span>}
              </button>
            ))}
          </div>
        ))}
        {running && !follow && rows.length > 0 && (
          <button type="button" className="cy-follow" onClick={() => setFollow(true)}><CyIcon name="eye" size={12} /> Follow Cyrus</button>
        )}
      </nav>
      <div className="cy-view">
        {current ? <Viewer key={`${build.id}:${current.path}`} build={build} base={base ?? null} row={current} live={live} running={running} /> : (
          <div className="cy-view-empty"><Skeleton label={running ? "Cyrus is planning the files" : "No source files"} /></div>
        )}
      </div>
    </div>
  );
}

function Viewer({ build, base, row, live, running }: { build: ModBuildView; base: ModBuildView | null; row: Row; live: LiveState; running: boolean }) {
  const lf = live.files.get(row.path);
  const draft = live.draft && live.draft.path === row.path && !live.draft.done ? live.draft : null;
  const fetched = useSource(row.src === "final" ? build.id : row.src === "base" ? base?.id ?? null : null, row.src === "final" || row.src === "base" ? row.path : null);
  const streaming = !!draft && draft.op === "write";
  const target = streaming ? draft!.text : row.src === "live" ? lf?.text ?? "" : fetched.text ?? "";
  const shown = useTypewriter(target, `${row.path}:${draft?.seq ?? "f"}`, streaming);
  const text = streaming ? target.slice(0, shown) : target;
  const lang = langOf(row.path);
  const lines = text ? text.replace(/\n$/, "").split("\n") : [];
  const scroller = useRef<HTMLDivElement>(null);

  // Lines changed by an edit glow once.
  const changed = useMemo(() => {
    if (!lf || lf.state !== "edited" || !lf.prev || !lf.text) return null;
    const s = new Set<number>();
    for (const op of diffLines(lf.prev, lf.text)) if (op.t === "add" && op.b !== null) s.add(op.b);
    return s;
  }, [lf]);

  useEffect(() => {
    if (!streaming) return;
    const el = scroller.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [streaming, lines.length]);

  const status = draft ? (draft.op === "write" ? "Cyrus is writing this file" : "Cyrus is editing this file")
    : row.state === "edited" ? "Just edited" : row.state === "written" ? "Written" : row.state === "base" && running ? "Previous version" : null;

  return (
    <>
      <div className="cy-view-path">
        <span className="cy-view-file">{row.path.replace(/^src\/main\/(java\/)?/, "")}</span>
        {status && <span className={`cy-view-tag ${draft ? "run" : ""}`}>{draft && <i className="cy-dotpulse" />}{status}</span>}
        {!running && text && (
          <button type="button" className="cy-view-btn" onClick={() => navigator.clipboard?.writeText(text)} aria-label="Copy file"><CyIcon name="copy" size={13} /></button>
        )}
      </div>
      <div className="cy-view-scroll" ref={scroller}>
        {row.state === "named" ? (
          <Skeleton label={`${row.name} is written`} note="This builder shares file names while it works; the code opens when the build finishes." />
        ) : !text && (fetched.error) ? (
          <p className="cy-view-err">Couldn&apos;t load this file right now.</p>
        ) : !text && !draft ? (
          <Skeleton label={running ? "Loading" : "Loading"} compact />
        ) : (
          <div className={`cy-lines ${streaming ? "streaming" : ""}`} role="region" aria-label={`Source of ${row.name}`} aria-live={streaming ? "off" : undefined}>
            {lines.map((l, i) => <Line key={i} n={i + 1} text={l} lang={lang} glow={!!changed?.has(i + 1)} caret={streaming && i === lines.length - 1} />)}
            {draft && draft.op === "edit" && (
              <div className="cy-editing">
                <span className="cy-editing-k"><i className="cy-dotpulse" /> New code going in</span>
                <pre>{draft.text.slice(-600)}</pre>
              </div>
            )}
          </div>
        )}
      </div>
    </>
  );
}

const Line = memo(function Line({ n, text, lang, glow, caret }: { n: number; text: string; lang: string; glow: boolean; caret: boolean }) {
  return (
    <div className={`cy-ln ${glow ? "glow" : ""}`}>
      <span className="n">{n}</span>
      <span className="c">{highlight(text, lang)}{caret && <i className="cy-caret" />}</span>
    </div>
  );
});

function Skeleton({ label, note, compact }: { label: string; note?: string; compact?: boolean }) {
  const widths = [62, 44, 78, 30, 66, 52, 84, 38, 58, 70];
  return (
    <div className={`cy-weave ${compact ? "compact" : ""}`}>
      <div className="cy-weave-lines" aria-hidden="true">
        {widths.slice(0, compact ? 4 : 10).map((w, i) => <span key={i} className="cy-skel" style={{ width: `${w}%`, marginLeft: `${(i % 4) * 14}px`, animationDelay: `${i * 90}ms` }} />)}
      </div>
      <div className="cy-weave-l"><i className="cy-spin" /> {label}</div>
      {note && <p className="cy-weave-n">{note}</p>}
    </div>
  );
}

