"use client";

// The glyph dock: a slim glass column, one orb per mod (running ones ringed with their
// progress). Hover, focus or L opens the library drawer: search + Building / Favourites / All.
import { useEffect, useRef, useState } from "react";
import { CYRUS_STATUS_LABEL } from "@/lib/cyrus/models";
import { versionNumber, type CyrusProject } from "@/lib/cyrus/projects";
import { CyIcon, CyrusMark } from "./icons";
import { Glyph } from "./Glyph";
import { PROGRESS } from "./web/scenes";
import { ago } from "./util";

export function Dock({ projects, current, open, onOpenChange, onPick, onNew, onHome, onFocus }: {
  projects: CyrusProject[];
  current: string | null;
  open: boolean;
  onOpenChange: (o: boolean) => void;
  onPick: (p: CyrusProject) => void;
  onNew: () => void;
  onHome: () => void;
  onFocus: (rootId: string | null) => void;
}) {
  const [q, setQ] = useState("");
  const leave = useRef<number | undefined>(undefined);
  const inp = useRef<HTMLInputElement>(null);
  useEffect(() => { if (open) setTimeout(() => inp.current?.focus({ preventScroll: true }), 60); else setQ(""); }, [open]);
  const list = q.trim() ? projects.filter((p) => p.title.toLowerCase().includes(q.trim().toLowerCase()) || p.latest.prompt.toLowerCase().includes(q.trim().toLowerCase())) : projects;
  const groups: [string, CyrusProject[]][] = [
    ["Building", list.filter((p) => p.running)],
    ["Favourites", list.filter((p) => !p.running && p.meta.favourite)],
    ["All mods", list.filter((p) => !p.running && !p.meta.favourite)],
  ];
  const dockList = projects.slice(0, 9);
  return (
    <div className={`cy-dockwrap ${open ? "open" : ""}`}
         onMouseLeave={() => { window.clearTimeout(leave.current); leave.current = window.setTimeout(() => onOpenChange(false), 260); }}
         onMouseEnter={() => window.clearTimeout(leave.current)}>
      <nav className="cy-dock" aria-label="Your mods">
        <button type="button" className="cy-dock-mark" onClick={onHome} aria-label="Cyrus home" title="Cyrus home"><CyrusMark size={26} /></button>
        <button type="button" className="cy-dock-new" onClick={onNew} aria-label="New mod (N)" title="New mod  N"><CyIcon name="plus" size={17} strokeWidth={2} /></button>
        <span className="cy-dock-sep" aria-hidden="true" />
        <div className="cy-dock-list">
          {dockList.map((p) => {
            const r = p.running;
            return (
              <button key={p.rootId} type="button" className={`cy-dock-i ${current === p.rootId ? "on" : ""}`} onClick={() => onPick(p)}
                      onMouseEnter={() => onFocus(p.rootId)} onMouseLeave={() => onFocus(null)} onFocus={() => onFocus(p.rootId)} onBlur={() => onFocus(null)}
                      aria-label={`${p.title}${r ? `, ${CYRUS_STATUS_LABEL[r.status]}` : ""}`}>
                <Glyph id={p.rootId} size={34} state={r ? "running" : p.head ? "ok" : "bad"} progress={r ? PROGRESS[r.status] : undefined} />
                {p.meta.favourite && <i className="cy-dock-fav" aria-hidden="true" />}
