                <button type="button" role="menuitem" onClick={() => { setMenu(false); setRename(true); }}><CyIcon name="pencil" size={14} /> Rename</button>
                {ok && <a role="menuitem" href={`/api/mod-builder/builds/${b.id}/source-zip`}><CyIcon name="download" size={14} /> Download source (.zip)</a>}
                <button type="button" role="menuitem" onClick={() => { setMenu(false); navigator.clipboard?.writeText(b.changeRequest || b.prompt); }}><CyIcon name="note" size={14} /> Copy the request</button>
                <button type="button" role="menuitem" onClick={() => { setMenu(false); onNewMod(); }}><CyIcon name="plus" size={14} /> New mod</button>
              </span>
            )}
          </span>
        </div>
      </header>

      {!isHead && ok && project.head && (
        <div className="cy-older">
          <CyIcon name="layers" size={13} />
          <span>Viewing <b>v{n}</b>. Current is <b>v{versionNumber(project, project.head.id)}</b>.</span>
          <button type="button" className="cy-link" onClick={() => onPatch(project.rootId, { headBuildId: b.id })}>Make v{n} current</button>
          <button type="button" className="cy-link dim" onClick={() => onOpen(project.head!.id)}>Go to current</button>
        </div>
      )}

      <section className="cy-inspector" aria-label="Mod details">
        <div className="cy-tabs" role="tablist">
          {tabs.map((t, i) => (
            <button key={t.id} type="button" role="tab" aria-selected={tab === t.id} className={`cy-tab ${tab === t.id ? "on" : ""}`} onClick={() => setTab(t.id)} title={`${t.label}  ${i + 1}`}>
              {t.id === "code" && running && <i className="cy-dotpulse" />}
              {t.label}{t.n !== undefined && <span className="cy-tab-n">{t.n}</span>}
            </button>
          ))}
        </div>
        <div className="cy-panel-body" role="tabpanel">
          {tab === "code" && (
            <>
              <LiveCode build={b} base={parent} live={live} focusPath={focusPath} onPick={onPickFile} />
              {ok && <p className="cy-codefoot">Source is yours to keep. The .zip includes a Gradle project so a developer can rebuild it.{b.jarName && <> {b.jarName} · {bytes(b.jarSize)}</>}</p>}
            </>
          )}
          {tab === "explain" && <Explain b={b} />}
          {tab === "versions" && (
            <Versions project={project} viewing={b.id} onOpen={onOpen}
                      onRestore={async (id) => { await onPatch(project.rootId, { headBuildId: id }); }}
                      onBranch={(id) => { setBranchFrom(id); composerRef.current?.focus(); }} />
          )}
          {tab === "notes" && <Notes key={project.rootId} project={project} onPatch={onPatch} />}
        </div>
      </section>

      {(base || project.running) && (
        <div className="cy-change" ref={dockRef}>
          {branchFrom && base && (
            <div className="cy-change-note"><CyIcon name="branch" size={13} /> Branching from <b>v{baseN}</b> <button type="button" onClick={() => setBranchFrom(null)}>Use {ok ? `v${n}` : "current"} instead</button></div>
          )}
          <Composer ref={composerRef} kind="change" compact onActivity={onActivity}
                    placeholder={base ? `Ask for a change to v${baseN}… “add /shop reload and make the title purple”` : "Ask for a change once this mod builds"}
                    defaultModel={bm.model ?? viewMeta(project.head ?? b).model ?? CYRUS_DEFAULT_MODEL}
                    lockVersion={b.mcVersion} disabledReason={disabledReason} submitLabel={base ? `Build v${project.builds.length + 1}` : "Build"} onSubmit={submitChange} />
        </div>
      )}

      {modal === "install" && <InstallModal build={b} servers={servers} onClose={() => setModal(null)} onDone={onRefresh} />}
    </>
  );
}

/** Pinned under the core: what Cyrus is doing right now, or the outcome. */
export function ProjectCaption({ b, onRetry, onEdit }: { b: ModBuildView; onRetry: () => Promise<string | null>; onEdit: () => void }) {
  const events = b.result?.events ?? [];
  const running = !isTerminal(b.status);
  const startedAt = events.find((e) => e.stage !== "queued")?.at ?? null;
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => { if (!running) return; const t = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(t); }, [running]);
  const elapsed = running && startedAt ? now - new Date(startedAt).getTime() : b.durationMs ?? 0;
  const stream = events.filter((e) => e.stage !== "queued" && e.message && e.message !== "Error details" && e.message !== "API lookup").slice(-4);
  const head = b.status === "queued" && b.result?.queuePosition ? `In line · position ${b.result.queuePosition}` : STAGE_HEADLINE[b.status] ?? "Working";
  const lastRepairs = b.result?.repairs ?? 0;
  const prevLen = useRef(0);
  useEffect(() => { prevLen.current = events.length; }, [events.length]);

  if (b.status === "failed") return <Failure b={b} onRetry={onRetry} onEdit={onEdit} />;
  if (b.status === "succeeded") {
    const s = b.result?.summary;
    return (
      <div className="cy-cap done">
        <span className="cy-cap-k ok"><CyIcon name="check" size={12} strokeWidth={2.4} /> Ready</span>
        <h2 className="cy-cap-h">{s?.tagline || `${b.pluginName} is built`}</h2>
        <p className="cy-cap-m">Built in {dur(b.durationMs)}{b.attempts > 1 ? ` · fixed itself ${b.attempts - 1}×` : " · first try"}{b.version ? ` · plugin ${b.version}` : ""}</p>
      </div>
    );
  }
  return (
    <div className="cy-cap">
      <span className="cy-cap-k"><i className="cy-dotpulse" /> Cyrus is thinking <span className="cy-cap-t" suppressHydrationWarning>{startedAt ? dur(elapsed) : "—"}</span></span>
      <h2 className="cy-cap-h">{head}{b.status === "repairing" && lastRepairs ? <span className="cy-cap-fix"> · fix {lastRepairs} of 3</span> : null}</h2>
      {stream.length > 0 && (
        <ol className="cy-thoughts">
          {stream.map((e, i) => (
            <li key={`${e.at}-${i}`} style={{ opacity: 0.32 + (0.68 * (i + 1)) / stream.length }}>
              <span className="t" suppressHydrationWarning>+{Math.max(0, Math.round((new Date(e.at).getTime() - new Date(startedAt || e.at).getTime()) / 1000))}s</span>
              <span className="m">{e.message}</span>
            </li>
          ))}
        </ol>
      )}
    </div>
  );
}

function Notes({ project, onPatch }: { project: CyrusProject; onPatch: (rootId: string, p: { notes: string }) => Promise<string | null> }) {
  const [v, setV] = useState(project.meta.notes ?? "");
  const [state, setState] = useState<"saved" | "dirty" | "saving" | "error">("saved");
  const t = useRef<number | undefined>(undefined);
  const save = async (text: string) => { setState("saving"); const e = await onPatch(project.rootId, { notes: text }); setState(e ? "error" : "saved"); };
  return (
    <section className="cy-doc cy-notes">
      <div className="cy-notes-h">
        <h4>Notes</h4>
        <span className={`cy-save ${state}`}>{state === "saving" ? "Saving…" : state === "dirty" ? "Unsaved" : state === "error" ? "Couldn't save" : "Saved"}</span>
      </div>
      <p className="cy-sub">Only you see these: ideas for the next version, what players said, server setup reminders.</p>
      <textarea value={v} maxLength={CYRUS_NOTES_MAX} placeholder="Players want the shop to sell elytra. Try a 7-day streak reward next."
                onChange={(e) => { setV(e.target.value); setState("dirty"); window.clearTimeout(t.current); const text = e.target.value; t.current = window.setTimeout(() => save(text), 800); }}
                onBlur={() => { if (state === "dirty") { window.clearTimeout(t.current); save(v); } }} />
      <span className="cy-fine">{v.length.toLocaleString("en-US")} / {CYRUS_NOTES_MAX.toLocaleString("en-US")} · <span suppressHydrationWarning>{ago(project.updatedAt)}</span></span>
    </section>
  );
}

