"use client";

// Cyrus: the AI mod studio. A full-bleed application inside the portal's content area:
// one living web (components/cyrus/web) as the stage, the UI floating on it.
//   Home     the loom: Cyrus core, your mods, + New mod, template seeds; headline + prompt.
//   Project  the weave: the mod's files / commands / settings; live build on the web,
//            caption under the core, inspector (Code / Explain / Versions / Notes), change prompt.
import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { usePathname } from "next/navigation";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import type { MbServer } from "@/lib/modbuilder/install";
import { CYRUS_DEFAULT_MODEL, CYRUS_STATUS_LABEL, type CyrusModelId } from "@/lib/cyrus/models";
import { groupProjects, projectOf, viewMeta, versionNumber, type CyrusProject } from "@/lib/cyrus/projects";
import { CYRUS_TEMPLATES } from "@/lib/cyrus/templates";
import type { CyrusMeta } from "@/lib/cyrus/meta";
import type { ComposerHandle } from "./Composer";
import { Home, HOME_CHIPS } from "./Home";
import { Project, ProjectCaption, type Tab } from "./Project";
import { Dock } from "./Dock";
import { ProjectPalette, ShortcutsModal } from "./Modals";
import { CyIcon } from "./icons";
import { useLive } from "./useLive";
import { CyrusCanvas, type Region } from "./web/CyrusCanvas";
import type { CyrusWeb, WebNodeSpec } from "./web/engine";
import { BRAND, hexRgb } from "./web/engine";
import { eventAction, fileNodeId, homeScene, modNodeId, projectScene, seedNodeId, webFiles, type SceneFile } from "./web/scenes";
import { isTypingTarget } from "./util";

const BASE = "/dashboard/cyrus";
type Toast = { id: string; text: string; buildId: string; ok: boolean };
const HOME_TEMPLATES = [...HOME_CHIPS.map((id) => CYRUS_TEMPLATES.find((t) => t.id === id)!).filter(Boolean), ...CYRUS_TEMPLATES.filter((t) => !HOME_CHIPS.includes(t.id))];

export function CyrusApp({ initialBuilds, servers, online, firstName }: { initialBuilds: ModBuildView[]; servers: MbServer[]; online: boolean; firstName: string }) {
  const [builds, setBuilds] = useState<ModBuildView[]>(initialBuilds);
  const [netErr, setNetErr] = useState(false);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [modal, setModal] = useState<null | "palette" | "keys">(null);
  const [dockOpen, setDockOpen] = useState(false);
  const [focusRoot, setFocusRoot] = useState<string | null>(null);
  const [focusSeed, setFocusSeed] = useState<string | null>(null);
  const [tab, setTab] = useState<Tab>("code");
  const [focusPath, setFocusPath] = useState<string | null>(null);
  const [branchFrom, setBranchFrom] = useState<string | null>(null);
  const pathname = usePathname();
  const selectedId = pathname.startsWith(BASE + "/") ? decodeURIComponent(pathname.slice(BASE.length + 1).split("/")[0]) : null;
  const homeComposer = useRef<ComposerHandle>(null);
  const changeComposer = useRef<ComposerHandle>(null);
  const engine = useRef<CyrusWeb | null>(null);
  const root = useRef<HTMLDivElement>(null);
  const headRef = useRef<HTMLDivElement>(null);
  const composeRef = useRef<HTMLDivElement>(null);
  const changeRef = useRef<HTMLDivElement>(null);

  const projects = useMemo(() => groupProjects(builds), [builds]);
  const project = projectOf(projects, selectedId);
  const viewing = project?.builds.find((b) => b.id === selectedId) ?? null;
  const inflight = builds.filter((b) => !isTerminal(b.status)).length;
  const fromRef = useRef<string | null>(null);

  const go = useCallback((id: string | null, from?: string | null) => {
    fromRef.current = from ?? null;
    const url = id ? `${BASE}/${id}` : BASE;
    if (url !== window.location.pathname) window.history.pushState(null, "", url);
  }, []);
  const openProject = useCallback((p: CyrusProject) => { setDockOpen(false); go((p.running ?? p.head ?? p.latest).id, modNodeId(p.rootId)); }, [go]);

  // A build opened while running starts on the live code; a finished one on Explain.
  const lastRoot = useRef<string | null>(null);
  useEffect(() => {
    if (!viewing || !project) { lastRoot.current = null; return; }
    if (lastRoot.current !== project.rootId) { setTab(isTerminal(viewing.status) ? (viewing.status === "succeeded" ? "explain" : "explain") : "code"); setBranchFrom(null); }
    lastRoot.current = project.rootId;
  }, [project, viewing]);

  const viewingRef = useRef<string | null>(null);
  viewingRef.current = selectedId;
  const upsert = useCallback((list: ModBuildView[]) => {
    setBuilds((cur) => {
      const m = new Map(cur.map((b) => [b.id, b]));
      for (const b of list) {
        const prev = m.get(b.id);
        if (prev && !isTerminal(prev.status) && isTerminal(b.status) && viewingRef.current !== b.id) {
          setToasts((t) => [...t.filter((x) => x.buildId !== b.id), { id: b.id + b.status, buildId: b.id, ok: b.status === "succeeded", text: b.status === "succeeded" ? `${b.pluginName || "Your mod"} is ready` : `${b.pluginName || "A build"} didn't build` }]);
        }
        m.set(b.id, { ...prev, ...b });
      }
      return Array.from(m.values());
    });
  }, []);

  // Poll every in-flight build (each GET also syncs it from the build service).
  useEffect(() => {
    const ids = builds.filter((b) => !isTerminal(b.status)).map((b) => b.id);
    if (!ids.length) return;
    let stop = false;
    const t = setTimeout(async () => {
      const res = await Promise.all(ids.map((id) => fetch(`/api/mod-builder/builds/${id}`, { cache: "no-store" }).then((r) => (r.ok ? r.json() : null)).catch(() => null)));
      if (stop) return;
      upsert(res.filter(Boolean).map((j) => j.build as ModBuildView));
      setNetErr(res.some((r) => !r));
    }, document.visibilityState === "hidden" ? 9000 : 2000);
    return () => { stop = true; clearTimeout(t); };
  }, [builds, upsert]);

  const refreshAll = useCallback(async () => {
    const r = await fetch("/api/mod-builder/builds", { cache: "no-store" }).catch(() => null);
    if (r?.ok) { const j = await r.json(); upsert(j.builds as ModBuildView[]); }
  }, [upsert]);
  useEffect(() => { const t = setInterval(refreshAll, 30_000); return () => clearInterval(t); }, [refreshAll]);
  useEffect(() => {
    if (!toasts.length) return;
    const t = setTimeout(() => setToasts((x) => x.slice(1)), 7000);
    return () => clearTimeout(t);
  }, [toasts]);
  useEffect(() => { if (selectedId) setToasts((t) => t.filter((x) => x.buildId !== selectedId)); }, [selectedId]);

  const create = useCallback(async (body: Record<string, unknown>): Promise<string | null> => {
    try {
      const r = await fetch("/api/mod-builder/builds", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) return j.error || "Cyrus couldn't start this build.";
      upsert([j.build]);
      const rootId = (j.build as ModBuildView).rootBuildId || j.build.id;
      go(j.build.id, body.baseBuildId ? null : null);
      void rootId;
      return null;
    } catch { return "We couldn't reach Nxeon. Check your connection and try again."; }
  }, [go, upsert]);

  const patch = useCallback(async (rootId: string, p: Record<string, unknown>): Promise<string | null> => {
    setBuilds((cur) => cur.map((b) => (b.id === rootId ? { ...b, cyrus: { ...viewMeta(b), ...cleanPatch(p) } } : b)));
    try {
      const r = await fetch(`/api/mod-builder/projects/${rootId}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(p) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { refreshAll(); return j.error || "Couldn't save."; }
      setBuilds((cur) => cur.map((b) => (b.id === rootId ? { ...b, cyrus: j.meta } : b)));
      return null;
    } catch { return "Couldn't save."; }
  }, [refreshAll]);

  const duplicate = useCallback(async (p: CyrusProject) => {
    const src = p.head ?? p.latest;
    return create({ prompt: (p.builds[0] ?? src).prompt, mcVersion: src.mcVersion, model: viewMeta(src).model ?? CYRUS_DEFAULT_MODEL });
  }, [create]);

  const newMod = useCallback((prefill?: { text: string; model?: CyrusModelId }) => {
    setDockOpen(false);
    go(null);
    setTimeout(() => { if (prefill) homeComposer.current?.setText(prefill.text, prefill.model); else homeComposer.current?.focus(); }, 120);
  }, [go]);

  // ----- the web -------------------------------------------------------------
  const live = useLive(viewing && !isTerminal(viewing.status) ? viewing : null, (path, n) => {
    engine.current?.emit(fileNodeId(path), { count: Math.min(3, Math.ceil(n / 220)), rgb: [140, 236, 252], size: 0.95 });
  });

  const sceneFiles: SceneFile[] = useMemo(() => {
    if (!viewing || !project) return [];
    if (isTerminal(viewing.status)) return webFiles(viewing.result?.files ?? []);
    const parent = viewing.baseBuildId ? project.builds.find((x) => x.id === viewing.baseBuildId) : null;
    const out = new Map<string, SceneFile>();
    for (const f of webFiles(parent?.result?.files ?? [])) out.set(f.path, { path: f.path });
    for (const f of live.files.values()) if (f.path.startsWith("src/main/")) out.set(f.path, { path: f.path, live: f.state === "writing" || f.state === "editing" });
    if (live.draft && !live.draft.done) out.set(live.draft.path, { path: live.draft.path, live: true });
    if (live.supported === false) {
      for (const e of viewing.result?.events ?? []) {
        const m = e.message.match(/^(Wrote|Edited) (.+)$/);
        if (m && !/\.json$/.test(m[2]) && ![...out.keys()].some((p) => p.endsWith("/" + m[2]))) out.set(`src/main/${m[2].endsWith(".java") ? "java" : "resources"}/${m[2]}`, { path: `src/main/${m[2].endsWith(".java") ? "java" : "resources"}/${m[2]}` });
      }
    }
    return [...out.values()];
  }, [viewing, project, live]);

  const scene = useMemo(() => {
    if (project && viewing) return projectScene(project, viewing, sceneFiles, { offline: !online });
    return homeScene(projects, HOME_TEMPLATES, { offline: !online });
  }, [project, viewing, sceneFiles, projects, online]);

  // Real build events -> light on the web.
  const seenEv = useRef<{ id: string; n: number } | null>(null);
  useEffect(() => {
    if (!viewing) { seenEv.current = null; return; }
    const ev = viewing.result?.events ?? [];
    const prev = seenEv.current;
    seenEv.current = { id: viewing.id, n: ev.length };
    if (!prev || prev.id !== viewing.id) return;
    const e = engine.current;
    if (!e) return;
    const byName = (name?: string) => {
      if (!name) return null;
      const f = sceneFiles.find((x) => x.path.endsWith("/" + name));
      return f ? fileNodeId(f.path) : null;
    };
    for (const x of ev.slice(prev.n)) {
      const a = eventAction(x.message, x.stage);
      if (!a) continue;
      if (a.kind === "inward") e.emit(byName(a.file), { inward: true, rgb: hexRgb("#c496ff") });
      else if (a.kind === "ripple") e.ripple(byName(a.file));
      else if (a.kind === "gather") e.gather();
      else if (a.kind === "scan") e.scan();
      else if (a.kind === "bloom") e.bloom();
      else if (a.kind === "warn") for (const f of sceneFiles.slice(0, 4)) e.emit(fileNodeId(f.path), { rgb: BRAND.warn, count: 2 });
    }
  }, [viewing, sceneFiles]);

  // Composer activity drives the core (no React state: straight to the engine).
  const onActivity = useCallback((a: { typing: boolean; listening: boolean; level: number }) => {
    engine.current?.setEnergy(a.listening ? 0.25 + a.level * 0.75 : a.typing ? 0.55 : 0);
  }, []);

  // Where the web sits: measured from the floating UI around it.
  const [region, setRegion] = useState<Region>({ x: 0, y: 0, w: 1200, h: 800, coreY: 0.5 });
  const [stacked, setStacked] = useState(false);
  const measure = useCallback(() => {
    const r = root.current?.getBoundingClientRect();
    if (!r) return;
    const W = r.width, H = r.height;
    const narrow = W < 1180;
    setStacked(narrow);
    const dockR = W >= 760 ? 92 : 0;
    let next: Region;
    if (!selectedId) {
      const hb = headRef.current?.getBoundingClientRect();
      const cb = composeRef.current?.getBoundingClientRect();
      const top = hb ? hb.bottom - r.top : 160;
      const bottom = cb ? cb.top - r.top : H * 0.62;
      next = { x: dockR, y: top, w: W - dockR, h: Math.max(140, bottom - top), coreY: 0.5, fit: "inner" };
    } else if (!narrow) {
      const ib = root.current?.querySelector(".cy-inspector")?.getBoundingClientRect();
      const ch = changeRef.current?.getBoundingClientRect();
      const left = ib ? ib.left - r.left : W * 0.6;
      const bottom = ch ? ch.top - r.top : H;
      next = { x: dockR, y: 64, w: Math.max(240, left - dockR - 12), h: Math.max(200, bottom - 64 - 120), coreY: 0.42, fit: "all" };
    } else {
      const heroH = Math.round(Math.min(H * 0.46, 420));
      next = { x: 0, y: 60, w: W, h: heroH - 60, coreY: 0.5, fit: "all" };
    }
    setRegion((o) => (Math.abs(o.x - next.x) + Math.abs(o.y - next.y) + Math.abs(o.w - next.w) + Math.abs(o.h - next.h) + Math.abs((o.coreY ?? 0.5) - (next.coreY ?? 0.5)) < 2 && o.fit === next.fit ? o : next));
  }, [selectedId]);
  useLayoutEffect(() => {
    measure();
    const ro = new ResizeObserver(() => measure());
    if (root.current) ro.observe(root.current);
    for (const el of [headRef.current, composeRef.current, changeRef.current]) if (el) ro.observe(el);
    const t = setTimeout(measure, 300);
    return () => { ro.disconnect(); clearTimeout(t); };
  }, [measure, viewing?.status, tab]);

  const onNode = useCallback((n: WebNodeSpec) => {
    if (n.kind === "mod") { const p = projects.find((x) => modNodeId(x.rootId) === n.id); if (p) openProject(p); }
    else if (n.kind === "ghost") newMod();
    else if (n.kind === "seed") { const t = CYRUS_TEMPLATES.find((x) => seedNodeId(x.id) === n.id); if (t) homeComposer.current?.setText(t.prompt, t.model); }
    else if (n.kind === "ver") go(n.id.slice(2));
    else if (n.kind === "file" || n.kind === "res") { setTab("code"); setFocusPath(n.id.slice(2)); }
    else setTab("explain");
  }, [projects, openProject, newMod, go]);

  const focusId = !selectedId ? (focusSeed ? seedNodeId(focusSeed) : focusRoot ? modNodeId(focusRoot) : null) : focusPath ? fileNodeId(focusPath) : null;

  // Global shortcuts.
  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if (e.key === "Escape" && modal) { setModal(null); return; }
      if (e.key === "Escape" && dockOpen) { setDockOpen(false); return; }
      if (isTypingTarget(e.target) || e.metaKey || e.ctrlKey || e.altKey || modal) return;
      const comp = selectedId ? changeComposer.current : homeComposer.current;
      const idx = project ? projects.findIndex((p) => p.rootId === project.rootId) : -1;
      switch (e.key) {
        case "n": case "N": e.preventDefault(); newMod(); break;
        case "p": case "P": e.preventDefault(); setModal("palette"); break;
        case "l": case "L": e.preventDefault(); setDockOpen((o) => !o); break;
        case "?": e.preventDefault(); setModal("keys"); break;
        case "/": e.preventDefault(); comp?.focus(); break;
        case "v": case "V": e.preventDefault(); comp?.toggleVoice(); break;
        case "0": e.preventDefault(); engine.current?.recenter(); break;
        case "+": case "=": e.preventDefault(); engine.current?.zoomBy(1.2); break;
        case "-": e.preventDefault(); engine.current?.zoomBy(0.83); break;
        case "[": if (projects.length) { e.preventDefault(); openProject(projects[(idx - 1 + projects.length) % projects.length]); } break;
        case "]": if (projects.length) { e.preventDefault(); openProject(projects[(idx + 1) % projects.length]); } break;
      }
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [modal, dockOpen, selectedId, project, projects, newMod, openProject]);

  const running = projects.filter((p) => p.running);
  const retry = async () => viewing ? create(viewing.baseBuildId
    ? { baseBuildId: viewing.baseBuildId, changeRequest: viewing.changeRequest, model: viewMeta(viewing).model }
    : { prompt: viewing.prompt, mcVersion: viewing.mcVersion, model: viewMeta(viewing).model }) : null;
  const editRetry = () => {
    if (!viewing) return;
    const m = viewMeta(viewing).model;
    if (viewing.baseBuildId) { setBranchFrom(viewing.baseBuildId); changeComposer.current?.setText(viewing.changeRequest || "", m); }
    else newMod({ text: viewing.prompt, model: m });
  };

  return (
    <div ref={root} className={`cy-app ${selectedId ? "is-project" : "is-home"} ${stacked ? "stacked" : ""} ${dockOpen ? "dock-open" : ""}`} data-status={viewing?.status ?? "home"}>
      <CyrusCanvas engineRef={engine} scene={scene} fromId={fromRef.current} region={region} energy={0} focusId={focusId} onOpen={onNode}
                   caption={viewing ? <ProjectCaption b={viewing} onRetry={retry} onEdit={editRetry} /> : null} captionDy={18}
                   hoverCard={(n) => <HoverCard n={n} projects={projects} />} />
      <div className="cy-vignette" aria-hidden="true" />

      <div className="cy-layer">
        {!selectedId && (
          <header className="cy-strip home">
            <span className="cy-word">Cyrus <span>Studio</span></span>
            <span className="cy-preview">Preview</span>
            <span className="cy-strip-r">
              {netErr ? <span className="cy-online down"><i />Reconnecting…</span>
                : <span className={`cy-online ${online ? "up" : "down"}`} title={online ? "The builder is online" : "The builder is offline"}><i />{online ? "Builder online" : "Builder offline"}</span>}
              {running.length > 0 && (
                <button type="button" className="cy-running" onClick={() => openProject(running[0])} title="Building now"><i className="cy-dotpulse" />{running.length} building</button>
              )}
              <button type="button" className="cy-topbtn" onClick={() => setModal("palette")} title="Find a mod  P"><CyIcon name="search" size={14} /><span>Find a mod</span><kbd>P</kbd></button>
              <button type="button" className="cy-topbtn icon" onClick={() => setModal("keys")} title="Keyboard shortcuts  ?" aria-label="Keyboard shortcuts"><CyIcon name="keyboard" size={16} /></button>
            </span>
          </header>
        )}

        <Dock projects={projects} current={project?.rootId ?? null} open={dockOpen} onOpenChange={setDockOpen} onPick={openProject} onNew={() => newMod()} onHome={() => go(null)} onFocus={setFocusRoot} />

        {selectedId && project && viewing ? (
          <div className="cy-project">
            <Project project={project} viewing={viewing} servers={servers} inflight={inflight} live={live} tab={tab} setTab={setTab}
                     focusPath={focusPath} onPickFile={(p) => setFocusPath(p)} onOpen={(id) => go(id)} onCreate={create} onPatch={patch}
                     onDuplicate={duplicate} onRefresh={refreshAll} onBack={() => go(null)} composerRef={changeComposer} onNewMod={newMod}
                     onActivity={onActivity} dockRef={changeRef} branchFrom={branchFrom} setBranchFrom={setBranchFrom} />
          </div>
        ) : selectedId ? (
          <div className="cy-missing"><p>That build isn&apos;t here.</p><button type="button" className="cy-btn" onClick={() => newMod()}>Back to Cyrus</button></div>
        ) : (
          <div className="cy-home">
            <Home firstName={firstName} inflight={inflight} online={online} onCreate={create} composerRef={homeComposer} onActivity={onActivity}
                  onSeedFocus={setFocusSeed} headRef={headRef} composerBoxRef={composeRef} />
            <p className="cy-legal">Cyrus builds Paper server plugins (Java). Not an official Minecraft product. Not approved by or associated with Mojang or Microsoft.</p>
          </div>
        )}

        <div className="cy-webctl" aria-label="Network view">
          <button type="button" onClick={() => engine.current?.zoomBy(1.2)} aria-label="Zoom in" title="Zoom in  +"><CyIcon name="plus" size={14} /></button>
          <button type="button" onClick={() => engine.current?.zoomBy(0.83)} aria-label="Zoom out" title="Zoom out  −"><span className="cy-minus" /></button>
          <button type="button" onClick={() => engine.current?.recenter()} aria-label="Recenter" title="Recenter  0"><CyIcon name="eye" size={14} /></button>
        </div>
      </div>

      <div className="cy-toasts" aria-live="polite">
        {toasts.map((t) => (
          <button key={t.id} type="button" className={`cy-toast ${t.ok ? "ok" : "bad"}`} onClick={() => { go(t.buildId); setToasts((x) => x.filter((y) => y.id !== t.id)); }}>
            <span className="cy-toast-orb"><CyIcon name={t.ok ? "check" : "warn"} size={13} strokeWidth={2.2} /></span>
            <span>{t.text}</span><span className="cy-toast-go">Open <CyIcon name="chevr" size={12} /></span>
          </button>
        ))}
      </div>

      {modal === "palette" && <ProjectPalette projects={projects} onClose={() => setModal(null)} onPick={(p) => { setModal(null); openProject(p); }} onNew={() => { setModal(null); newMod(); }} />}
      {modal === "keys" && <ShortcutsModal onClose={() => setModal(null)} />}
    </div>
  );
}

function cleanPatch(p: Record<string, unknown>): Partial<CyrusMeta> {
  const o: Record<string, unknown> = { ...p };
  for (const k of Object.keys(o)) if (o[k] === null) delete o[k];
  return o as Partial<CyrusMeta>;
}

function HoverCard({ n, projects }: { n: WebNodeSpec; projects: CyrusProject[] }) {
  if (n.kind === "mod") {
    const p = projects.find((x) => modNodeId(x.rootId) === n.id);
    const r = p?.running;
    return (
      <div className="cy-hc">
        <span className="cy-hc-k" style={{ color: n.color }}>{r ? "Building" : p?.head ? "Mod" : "Didn't build"}</span>
        <b className="cy-hc-t">{n.label}</b>
        <span className="cy-hc-d">{p?.head?.result?.summary?.tagline || p?.latest.prompt.slice(0, 110)}</span>
        <span className="cy-hc-f">{r ? CYRUS_STATUS_LABEL[r.status] : n.sub} · open</span>
      </div>
    );
  }
  if (n.kind === "seed") return <div className="cy-hc"><span className="cy-hc-k">Template</span><b className="cy-hc-t">{n.label}</b><span className="cy-hc-d">{n.sub}</span><span className="cy-hc-f">Click to start from it</span></div>;
  if (n.kind === "ghost") return <div className="cy-hc"><b className="cy-hc-t">New mod</b><span className="cy-hc-d">Start from a blank prompt.</span></div>;
  if (n.kind === "ver") {
    const p = projects.find((x) => x.builds.some((b) => `v:${b.id}` === n.id));
    const b = p?.builds.find((x) => `v:${x.id}` === n.id);
    return <div className="cy-hc"><span className="cy-hc-k">{p?.title}</span><b className="cy-hc-t">{n.label}{b && p ? ` of ${p.builds.length}` : ""}</b><span className="cy-hc-d">{b?.changeRequest || (b && p && versionNumber(p, b.id) === 1 ? "First build" : "")}</span><span className="cy-hc-f">{b ? CYRUS_STATUS_LABEL[b.status] : ""}</span></div>;
  }
  if (n.kind === "file" || n.kind === "res") return <div className="cy-hc"><span className="cy-hc-k">{n.live ? "Writing now" : n.kind === "file" ? "Java source" : "Plugin file"}</span><b className="cy-hc-t mono">{n.label}</b><span className="cy-hc-d mono">{n.sub}</span><span className="cy-hc-f">Click to read it</span></div>;
  return <div className="cy-hc"><span className="cy-hc-k">{n.kind === "cmd" ? "Command" : n.kind === "perm" ? "Permission" : "Setting"}</span><b className="cy-hc-t mono">{n.label}</b>{n.sub && <span className="cy-hc-d">{n.sub}</span>}</div>;
}

