.cy-composer.compact textarea { min-height: 48px; padding: 14px 16px 4px; font-size: 14.5px; }
.cy-composer textarea::placeholder { color: var(--cy-ink4); }
.cy-bar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; padding: 8px 10px 10px 12px; }
.cy-bar-l, .cy-bar-r { display: flex; align-items: center; gap: 6px; min-width: 0; }
.cy-bar-r { margin-left: auto; }
.cy-bar-sep { width: 1px; height: 20px; background: var(--cy-rim2); margin: 0 4px; }
.cy-tool { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 11px; color: var(--cy-ink3); transition: color .15s, background .15s; }
.cy-tool:hover { color: var(--cy-ink); background: var(--cy-raise-2); }
.cy-mic.on { color: #04131a; background: linear-gradient(135deg, var(--cy-n1), var(--cy-n2)); box-shadow: 0 0 0 4px color-mix(in srgb, var(--cy-n1) 22%, transparent), 0 0 24px color-mix(in srgb, var(--cy-n1) 60%, transparent); animation: cy-mic 1.6s ease-in-out infinite; }
.cy-mic.unsupported { opacity: .55; }
.cy-pick { display: inline-flex; align-items: center; gap: 7px; height: 34px; padding: 0 10px; border-radius: 10px; font-size: 12.5px; font-weight: 650; color: var(--cy-ink2); border: 1px solid var(--cy-rim); background: var(--cy-raise); white-space: nowrap; }
.cy-pick:hover, .cy-pick[aria-expanded="true"] { color: var(--cy-ink); border-color: var(--cy-rim2); background: var(--cy-raise-2); }
.cy-pick-k { color: var(--cy-ink); }
.cy-pick-v { color: var(--cy-ink3); font-weight: 600; }
.cy-spend { display: inline-flex; gap: 2px; align-items: flex-end; }
.cy-spend i { width: 3px; border-radius: 2px; background: var(--cy-rim2); }
.cy-spend i:nth-child(1) { height: 6px; } .cy-spend i:nth-child(2) { height: 9px; } .cy-spend i:nth-child(3) { height: 12px; }
.cy-spend i.on { background: linear-gradient(var(--cy-n5), var(--cy-n3)); }
.cy-est { display: inline-flex; align-items: center; gap: 5px; font-size: 11.5px; font-weight: 600; color: var(--cy-ink3); white-space: nowrap; }
.cy-est-sep { opacity: .5; }
.cy-kbd-hint { font: 600 11px/1 var(--font-mono); color: var(--cy-ink4); padding: 0 2px; }
.cy-go {
  position: relative; display: inline-flex; align-items: center; gap: 8px; height: 38px; padding: 0 16px; border-radius: 12px;
  font-size: 13.5px; font-weight: 700; color: #fff; white-space: nowrap;
  background: linear-gradient(110deg, #13b8d6, #5a5cf0 50%, #b13fd6); background-size: 160% 100%;
  box-shadow: 0 10px 30px -12px rgba(110, 90, 255, .9), inset 0 1px 0 rgba(255,255,255,.25);
  transition: background-position .4s, transform .15s, opacity .2s;
}
.cy-go:hover:not(:disabled) { background-position: 100% 0; transform: translateY(-1px); }
.cy-go:disabled { opacity: .45; box-shadow: none; }
.cy-composer-msg { padding: 9px 6px 0; font-size: 12.5px; line-height: 1.5; }
