.cy-composer-msg .hint { color: var(--cy-ink3); }
.cy-composer-msg button { color: var(--cy-n2); font-weight: 700; text-decoration: underline; text-underline-offset: 3px; }

/* attachments */
.cy-atts { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 14px 16px 0; }
.cy-att { position: relative; width: 64px; height: 64px; border-radius: 12px; overflow: hidden; border: 1px solid var(--cy-rim2); background: var(--cy-raise); animation: cy-pop .35s cubic-bezier(.2,.9,.3,1.3) both; }
.cy-att img { width: 100%; height: 100%; object-fit: cover; }
.cy-att button { position: absolute; top: 4px; right: 4px; width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; color: #fff; background: rgba(4, 8, 24, .72); opacity: 0; transition: opacity .15s; }
.cy-att:hover button, .cy-att:focus-within button { opacity: 1; }
.cy-att-veil { position: absolute; inset: 0; display: grid; place-items: center; background: rgba(4, 8, 24, .5); color: #fff; }
.cy-att-veil.err { background: rgba(120, 10, 40, .55); }
.cy-att.err { border-color: var(--cy-bad); }
.cy-att-note { flex: 1 1 180px; font-size: 11.5px; line-height: 1.45; color: var(--cy-ink4); }

/* listening */
.cy-listen { display: flex; align-items: center; gap: 14px; padding: 2px 20px 8px; min-height: 44px; }
.cy-wave { display: inline-flex; align-items: center; gap: 3px; height: 40px; flex: none; }
.cy-wave i { width: 3px; height: 40px; border-radius: 3px; transform: scaleY(.15); background: linear-gradient(var(--cy-n1), var(--cy-n2) 45%, var(--cy-n3) 80%, var(--cy-n5)); box-shadow: 0 0 8px color-mix(in srgb, var(--cy-n1) 50%, transparent); }
.cy-listen-t { font-size: 13.5px; font-weight: 600; color: var(--cy-n1); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cy-listen-t em { font-style: normal; color: var(--cy-ink2); }
.cy-ellipsis::after { content: "…"; animation: cy-blink 1.2s steps(2) infinite; }

/* popovers (bottom sheet on phones) */
.cy-pop { position: relative; display: inline-flex; }
.cy-pop-back { display: none; }
.cy-pop-panel { position: absolute; top: calc(100% + 8px); left: 0; z-index: 60; width: 340px; }
.cy-composer.compact .cy-pop-panel { top: auto; bottom: calc(100% + 8px); }
.cy-panel { display: flex; flex-direction: column; gap: 4px; padding: 8px; border-radius: 16px; border: 1px solid var(--cy-rim2); background: var(--cy-surface-2); box-shadow: 0 30px 70px -30px rgba(0,0,0,.7), 0 0 0 1px rgba(0,0,0,.2); animation: cy-in .18s ease-out both; }
