.cy-panel-h { display: flex; align-items: center; gap: 8px; font: 700 9.5px/1 var(--font-mono); letter-spacing: .16em; text-transform: uppercase; color: var(--cy-ink4); padding: 8px 8px 4px; }
.cy-panel-hn { letter-spacing: .04em; text-transform: none; font-family: inherit; font-weight: 600; }
.cy-panel-foot { font-size: 11px; color: var(--cy-ink4); padding: 6px 8px 2px; line-height: 1.45; }
.cy-opt { display: flex; align-items: flex-start; gap: 11px; padding: 10px; border-radius: 12px; text-align: left; border: 1px solid transparent; }
.cy-opt:hover { background: var(--cy-raise-2); }
