.cy-tag.cur { color: var(--cy-n3); background: color-mix(in srgb, var(--cy-n3) 14%, transparent); }
.cy-games { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; padding: 0 2px 4px; }
.cy-game { display: flex; flex-direction: column; gap: 2px; padding: 9px 10px; border-radius: 11px; border: 1px solid var(--cy-rim); }
.cy-game.on { border-color: color-mix(in srgb, var(--cy-n1) 55%, transparent); background: color-mix(in srgb, var(--cy-n1) 9%, transparent); }
