/* ── composer + rotating rim ────────────────────────────────────────── */
.cy-composer { position: relative; width: 100%; max-width: 780px; text-align: left; }
.cy-composer-box { position: relative; isolation: isolate; border-radius: 22px; }
.cy-composer-box::before {
  content: ""; position: absolute; inset: -3px; z-index: -1; border-radius: inherit; filter: blur(16px); opacity: .45;
  background: conic-gradient(from var(--cy-ang), transparent 0deg 200deg, var(--cy-n1) 260deg, var(--cy-n3) 300deg, var(--cy-n5) 335deg, transparent 360deg);
  animation: cy-rim 8s linear infinite; transition: opacity .3s;
}
.cy-rim {
  position: absolute; inset: 0; z-index: 2; border-radius: inherit; padding: 1.2px; pointer-events: none;
  background: conic-gradient(from var(--cy-ang), transparent 0deg 200deg, var(--cy-n1) 260deg, var(--cy-n3) 300deg, var(--cy-n5) 335deg, transparent 360deg);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor;
