  animation: cy-rim 8s linear infinite;
}
.cy-composer:focus-within .cy-composer-box::before { opacity: .7; }
.cy-composer:focus-within .cy-rim, .cy-composer:focus-within .cy-composer-box::before { animation-duration: 4.5s; }
.cy-composer.listening .cy-composer-box::before, .cy-composer.listening .cy-rim { background: conic-gradient(from var(--cy-ang), transparent 0deg 120deg, var(--cy-n1) 200deg, var(--cy-n2) 260deg, var(--cy-n1) 320deg, transparent 360deg); animation-duration: 2.6s; }
.cy-composer.listening .cy-composer-box::before { opacity: .9; }
.cy-composer.drag .cy-composer-in { border-color: var(--cy-n2); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--cy-n2) 40%, transparent); }
.cy-composer-in { position: relative; z-index: 1; border-radius: inherit; border: 1px solid var(--cy-rim2); background: var(--cy-surface-2); display: flex; flex-direction: column; }
:root.nx-portal[data-theme="light"] .cy-composer-in { background: #fff; }
.cy-composer textarea {
  width: 100%; min-height: 96px; resize: none; background: transparent; border: 0; outline: 0;
  color: var(--cy-ink); font-size: 15.5px; line-height: 1.6; font-weight: 450; padding: 18px 20px 6px; display: block;
}
