/* ═══ CYRUS · AI mod studio (v2, 2026-10-07) ═══════════════════════════════
   A full-bleed application: one living web (components/cyrus/web/engine.ts) is the
   stage and the UI floats on it as a few deliberate glass surfaces. Everything hangs
   off .cy-app so nothing leaks into portal classes.
   The canvas is a dark island in both portal themes (the portal's rail and top bar are
   dark islands too, so the whole viewport reads as one app); light theme switches to
   the "Dawn" palette: lifted indigo ground, warmer aurora, pearl-tinted glass.
   Spec: /root/agent-notes/cyrus-v2/SPEC.md */

@property --cy-ang { syntax: "<angle>"; inherits: false; initial-value: 0deg; }

.cy-app {
  --cy-n1: #14c5e4; --cy-n2: #2f7eef; --cy-n3: #8c3ae9; --cy-n4: #a55cf0; --cy-n5: #d623e1;
  --cy-bg0: #03051a; --cy-bg1: #070b26; --cy-bg2: #0c1236; --cy-sky: #060a26;
  --cy-ink: #eef1ff; --cy-ink2: #b4bce0; --cy-ink3: #7d87b2; --cy-ink4: #545e8a;
  --cy-line: rgba(150, 165, 255, .13); --cy-line2: rgba(150, 165, 255, .22);
  --cy-rim: var(--cy-line); --cy-rim2: var(--cy-line2); --cy-thread: rgba(150, 165, 255, .34);
  --cy-glass: rgba(9, 13, 40, .58); --cy-glass2: rgba(13, 18, 52, .78); --cy-glass-solid: #0b1033;
  --cy-glass-hi: rgba(255, 255, 255, .055); --cy-raise: rgba(255, 255, 255, .035); --cy-raise-2: rgba(255, 255, 255, .065);
  --cy-surface: var(--cy-glass); --cy-surface-2: var(--cy-glass2);
  --cy-ok: #3ee6a8; --cy-warn: #ffb44f; --cy-bad: #ff5c8a;
  --cy-code-bg: rgba(3, 6, 22, .72); --cy-code-ink: #d9e0ff; --cy-code-n: #424d7a;
  --cy-blur: blur(22px) saturate(1.5);
  --cy-shadow: 0 30px 80px -36px rgba(0, 0, 0, .85), 0 0 0 1px rgba(0, 0, 0, .25);
  --cy-ease: cubic-bezier(.2, .8, .2, 1);
  --cy-dock-w: 60px;
  position: relative; height: 100%; min-height: 520px; overflow: hidden; isolation: isolate;
  color: var(--cy-ink); background: var(--cy-bg0);
  font-feature-settings: "ss01", "cv11"; -webkit-font-smoothing: antialiased;
}
/* Dawn: the same island, lifted (light portal theme) */
:root.nx-portal[data-theme="light"] .cy-app {
  --cy-bg0: #0b0f33; --cy-sky: #121747;
  --cy-ink2: #c4cbef; --cy-ink3: #959fcc; --cy-ink4: #6a74a3;
  --cy-line: rgba(190, 200, 255, .2); --cy-line2: rgba(200, 210, 255, .32);
  --cy-glass: rgba(40, 46, 110, .46); --cy-glass2: rgba(48, 54, 124, .72); --cy-glass-solid: #262c74;
  --cy-glass-hi: rgba(255, 255, 255, .1); --cy-raise: rgba(255, 255, 255, .055); --cy-raise-2: rgba(255, 255, 255, .095);
  --cy-code-bg: rgba(8, 11, 40, .74);
  --cy-shadow: 0 30px 80px -36px rgba(6, 8, 40, .7), 0 0 0 1px rgba(255, 255, 255, .04);
}
.cy-app button { cursor: pointer; font: inherit; color: inherit; background: none; border: 0; padding: 0; }
.cy-app button:disabled { cursor: not-allowed; }
.cy-app :focus-visible { outline: 2px solid var(--cy-n1); outline-offset: 2px; border-radius: 8px; }
.cy-app kbd, .cy-keycap { font: 600 10.5px/1 var(--font-mono); padding: 3px 5px; border-radius: 5px; color: var(--cy-ink3); border: 1px solid var(--cy-line2); background: var(--cy-raise); }
