    await row("cy-dr-v3", d2.prompt, d2.mcVersion, min(150), {
      baseBuildId: "mb16f8378db9c3e2b68cbe", rootBuildId: "mb67f7a97b866da50800f4", status: "failed", errorCode: "compile", attempts: 4, durationMs: 412000, finishedAt: min(143),
