    await mock({ id: "cy-dr-v4", status: "succeeded", fx: "mb16f8378db9c3e2b68cbe", prompt: d1.prompt, mcVersion: d1.mcVersion, baseBuildId: "mb67f7a97b866da50800f4", changeRequest: "Make the day 7 reward a diamond AND an enchanted golden apple, and the title gold." });
    await row("cy-dr-v4", d1.prompt, d1.mcVersion, min(120), { baseBuildId: "mb67f7a97b866da50800f4", rootBuildId: "mb67f7a97b866da50800f4", changeRequest: "Make the day 7 reward a diamond AND an enchanted golden apple, and the title gold.", cyrus: { model: "saka" } });

