// LOCAL MOCK of the Mod Builder build service, for Cyrus UI screenshots only.
// Serves REAL build records + sources fetched read-only from the service (fx/), and
// simulates new builds by replaying a real fixture's files: v2 adds the 0.4 live view
// (/live with a streaming draft, /source of the in-progress workspace).
// Control: POST /_set {id, status, fx?, ago?, livePct?} freezes a build at a stage.
"use strict";
const http = require("http");
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const FX = path.join(__dirname, "fx");
const PORT = 7399;
const now = () => new Date().toISOString();
const iso = (ms) => new Date(ms).toISOString();

const fixtures = {};
for (const f of fs.readdirSync(FX)) if (f.endsWith(".json")) { const d = JSON.parse(fs.readFileSync(path.join(FX, f))); fixtures[d.id] = d; }
const recs = new Map();

function fixtureFor(prompt, changeRequest) {
  const p = (prompt + " " + (changeRequest || "")).toLowerCase();
  if (changeRequest && /heal|feed/.test(p)) return "p0-heal01c1";
  if (changeRequest && /streak|daily/.test(p)) return "mb16f8378db9c3e2b68cbe";
  if (/econom|coin|shop/.test(p)) return "p0-econ01";
  if (/scoreboard|sidebar|stats/.test(p)) return "p0-score01";
  if (/spleef/.test(p)) return "p0-spleef01";
  if (/zone|grief/.test(p)) return "p0-zones01";
  if (/boss/.test(p)) return "mb900780697eb88bcaaede";
  if (/streak|daily/.test(p)) return "mb67f7a97b866da50800f4";
  if (/join|welcome/.test(p)) return "p0-joinmsg01";
  return "p0-heal01";
}
const srcFiles = (fxId) => fixtures[fxId].files.filter((f) => /^src\/main\/(java|resources)\//.test(f.path))
  .sort((a, b) => (a.path.endsWith(".yml") ? 0 : 1) - (b.path.endsWith(".yml") ? 0 : 1))
  .map((f) => ({ path: f.path, text: fs.readFileSync(path.join(FX, "src", fxId, f.path), "utf8") }));

// Timeline of a simulated build (seconds from start).
function timeline(fxId) {
  const files = srcFiles(fxId);
  let t = 4;
  const writes = files.map((f) => { const d = Math.max(1.6, f.text.length / 420); const w = { ...f, t0: t, t1: t + d }; t += d + 0.35; return w; });
  return { writes, codingEnd: t, compileEnd: t + 3, scanEnd: t + 6 };
}
function stageAt(tl, s) {
  if (s < 1.5) return "queued";
  if (s < 4) return "planning";
  if (s < tl.codingEnd) return "coding";
  if (s < tl.compileEnd) return "compiling";
  if (s < tl.scanEnd) return "scanning";
  return "succeeded";
}

function record(e, s) {
  const { body, fxId } = e;
  const tl = e.tl;
  const st = stageAt(tl, s);
  const t0 = e.t0;
  if (st === "succeeded") return { ...fixtures[fxId], id: e.id, prompt: body.prompt, changeRequest: body.changeRequest || null, baseBuildId: body.baseBuildId || null, mcVersion: body.mcVersion, durationMs: Math.round(tl.scanEnd * 1000), finishedAt: iso(t0 + tl.scanEnd * 1000), queuePosition: 0, references: e.references || [] };
  const ev = [{ at: iso(t0), stage: "queued", message: "Waiting for a free builder" }];
  if (s >= 1.5) ev.push({ at: iso(t0 + 1500), stage: "planning", message: body.baseBuildId ? "Reading your existing plugin and planning the change" : "Planning the plugin from your description" });
  if (s >= 2 && e.references?.length) ev.push({ at: iso(t0 + 2000), stage: "planning", message: "Reading 1.png" });
  if (s >= 4) ev.push({ at: iso(t0 + 4000), stage: "coding", message: "Writing the plugin code" });
  for (const w of tl.writes) if (s >= w.t1) ev.push({ at: iso(t0 + w.t1 * 1000), stage: "coding", message: `${body.baseBuildId ? "Edited" : "Wrote"} ${w.path.split("/").pop()}` });
  if (s >= tl.codingEnd) { ev.push({ at: iso(t0 + tl.codingEnd * 1000), stage: "compiling", message: `Compiling against Paper ${body.mcVersion}` }); }
  if (s >= tl.compileEnd) { ev.push({ at: iso(t0 + tl.compileEnd * 1000 - 200), stage: "compiling", message: "Compiled successfully" }); ev.push({ at: iso(t0 + tl.compileEnd * 1000), stage: "scanning", message: "Running the safety check" }); }
  return {
    id: e.id, status: st, prompt: body.prompt, changeRequest: body.changeRequest || null, baseBuildId: body.baseBuildId || null, mcVersion: body.mcVersion,
    error: null, errorCode: null, attempts: 1, repairs: 0, costUsd: 0.1, durationMs: 0, pluginName: null, references: e.references || [],
    jar: null, summary: null, commands: [], permissions: [], config: [], warnings: [], files: [], safety: null, events: ev, queuePosition: st === "queued" ? 1 : 0, finishedAt: null,
  };
}
const elapsed = (e) => (e.frozen !== undefined ? e.frozen : (Date.now() - e.t0) / 1000);
function liveView(e, q) {
  const s = elapsed(e);
  const st = stageAt(e.tl, s);
  if (st === "succeeded") return { live: false, status: st, files: [], draft: null };
  const done = e.tl.writes.filter((w) => s >= w.t1);
  const cur = e.tl.writes.find((w) => s >= w.t0 && s < w.t1);
  const files = done.map((w) => ({ path: w.path, size: Buffer.byteLength(w.text), hash: crypto.createHash("sha1").update(w.text).digest("hex").slice(0, 12) }));
  let draft = null;
  if (cur) {
    const n = Math.floor(cur.text.length * Math.min(1, (s - cur.t0) / (cur.t1 - cur.t0)));
    const seq = e.tl.writes.indexOf(cur) + 1;
    const from = q.get("draft") === cur.path && Number(q.get("seq")) === seq ? Math.min(n, Number(q.get("from") || 0)) : 0;
    draft = { path: cur.path, op: e.body.baseBuildId ? "edit" : "write", seq, from, text: cur.text.slice(from, n), total: n, done: false, inputBytes: n };
    if (e.body.baseBuildId) { draft.op = "write"; }
  }
  return { live: true, status: st, files, draft };
}

const send = (res, code, body) => { res.writeHead(code, { "Content-Type": "application/json" }); res.end(JSON.stringify(body)); };
const readBody = (req) => new Promise((r) => { let b = ""; req.on("data", (d) => (b += d)); req.on("end", () => { try { r(JSON.parse(b || "{}")); } catch { r({}); } }); });

function get(id) {
  if (recs.has(id)) return recs.get(id);
  if (fixtures[id]) { const e = { id, static: fixtures[id], fx: id }; recs.set(id, e); return e; }
  return null;
}
const recOf = (e) => (e.static ? e.static : record(e, elapsed(e)));

http.createServer(async (req, res) => {
  const url = new URL(req.url, "http://x");
  const parts = url.pathname.split("/").filter(Boolean);
  if (url.pathname === "/health") return send(res, 200, { ok: true, service: "mock", image: "0.4-mock", features: { images: true, live: true } });
  if (req.method === "POST" && url.pathname === "/_set") {
    const b = await readBody(req);
    const fxId = b.fx || fixtureFor(b.prompt || "", b.changeRequest);
    if (b.status === "succeeded") { recs.set(b.id, { id: b.id, fx: fxId, static: { ...fixtures[fxId], id: b.id, prompt: b.prompt, changeRequest: b.changeRequest || null, baseBuildId: b.baseBuildId || null, mcVersion: b.mcVersion, durationMs: 90000, finishedAt: now() } }); return send(res, 200, { ok: true }); }
    if (b.status === "failed") { recs.set(b.id, { id: b.id, fx: fxId, static: { ...fixtures[b.fx], id: b.id } }); return send(res, 200, { ok: true }); }
    const tl = timeline(fxId);
    const e = { id: b.id, body: b, fxId, fx: fxId, tl, t0: Date.now() - (b.ago || 30) * 1000, references: b.references || [] };
    // Freeze at a point inside the requested stage (coding: livePct through the writes).
    const at = { queued: 0.5, planning: 2.5, coding: 4 + (tl.codingEnd - 4) * (b.livePct ?? 0.55), compiling: tl.codingEnd + 1, repairing: tl.codingEnd + 1, scanning: tl.compileEnd + 1 }[b.status];
    if (at !== undefined && !b.run) e.frozen = at;
    else if (at !== undefined) e.t0 = Date.now() - at * 1000;
    recs.set(b.id, e);
    return send(res, 200, { ok: true, status: stageAt(tl, at ?? 0), fx: fxId });
  }
  if (req.method === "POST" && url.pathname === "/builds") {
    const b = await readBody(req);
    if (b.tier !== undefined && !["katara", "saka", "yakko"].includes(b.tier)) return send(res, 400, { error: "bad tier" });
    const fxId = fixtureFor(b.prompt, b.changeRequest);
    const references = (b.images || []).map((im, i) => ({ n: i + 1, name: im.name, type: im.type, size: Buffer.from(im.data || "", "base64").length }));
    const e = { id: b.id, body: b, fxId, fx: fxId, tl: timeline(fxId), t0: Date.now(), references };
    recs.set(b.id, e);
    console.log("create", b.id, fxId, JSON.stringify({ tier: b.tier, images: references.length, keys: Object.keys(b) }));
    return send(res, 202, recOf(e));
  }
  if (parts[0] === "builds" && parts[1]) {
    const e = get(parts[1]);
    if (!e) return send(res, 404, { error: "not found" });
    const rec = recOf(e);
    if (req.method === "GET" && parts.length === 2) return send(res, 200, rec);
    if (req.method === "POST" && parts[2] === "cancel") { e.static = { ...rec, status: "failed", errorCode: "cancelled", error: "Build cancelled.", finishedAt: now() }; return send(res, 200, { ok: true }); }
    if (parts[2] === "live") return send(res, 200, e.static ? { live: false, status: rec.status, files: [], draft: null } : liveView(e, url.searchParams));
    if (parts[2] === "artifact") {
      const f = path.join(FX, `${e.fx}.jar.bin`);
      if (!fs.existsSync(f)) return send(res, 404, {});
      return res.end(fs.readFileSync(f));
    }
    if (parts[2] === "source") {
      const p = String(url.searchParams.get("path") || "");
      if (rec.status !== "succeeded" && rec.status !== "failed") {
        const lv = liveView(e, new URLSearchParams());
        if (!lv.files.some((f) => f.path === p)) return send(res, 404, { error: "no such file" });
      }
      const f = path.join(FX, "src", e.fx, p);
      if (!f.startsWith(path.join(FX, "src", e.fx)) || !fs.existsSync(f)) return send(res, 404, { error: "no such file" });
      res.writeHead(200, { "Content-Type": "text/plain; charset=utf-8" });
      return res.end(fs.readFileSync(f));
    }
  }
  send(res, 404, { error: "nope" });
}).listen(PORT, "127.0.0.1", () => console.log("mock modbuilder (0.4 live) on", PORT, Object.keys(fixtures).length, "fixtures"));

