// End-to-end Cyrus v2 flow against the local mock service: compose (image + model + voice), build,
// the fly-through into the project, the live build (frames), success bloom. ROUND=r2 VIEW=desktop|mobile THEME=dark|light
import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
const require = createRequire("/opt/nxeon/node_modules/");
const { chromium } = require("playwright");
const tok = JSON.parse(readFileSync("/tank/nxeon-wt-cyrus/.cyrus-local/tokens.json", "utf8"));
const BASE = "http://localhost:3149";
const OUT = `/root/agent-notes/cyrus-v2/${process.env.ROUND ?? "r2"}/flow`; mkdirSync(OUT, { recursive: true });
const view = process.env.VIEW ?? "desktop";
const theme = process.env.THEME ?? "dark";
const vp = { desktop: { width: 1440, height: 900 }, wide: { width: 1920, height: 1080 }, mobile: { width: 390, height: 844 } }[view];
const sfx = `${view}${theme === "light" ? "-light" : ""}`;
const b = await chromium.launch({ args: ["--use-fake-ui-for-media-stream", "--use-fake-device-for-media-stream"] });
const ctx = await b.newContext({ viewport: vp, isMobile: view === "mobile", hasTouch: view === "mobile", colorScheme: theme, permissions: ["microphone"] });
await ctx.addCookies([{ name: tok.cookie, value: tok.ownerTok, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
const p = await ctx.newPage();
await p.addInitScript((t) => { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); localStorage.setItem("cyDebug", "1"); }, theme);
const errs = []; p.on("pageerror", (e) => errs.push(String(e))); p.on("console", (m) => { if (m.type() === "error") errs.push(m.text().slice(0, 300)); });
const shot = async (n) => { await p.screenshot({ path: `${OUT}/${n}-${sfx}.png` }); console.log(n); };
const frames = async (n, count, gap) => { for (let i = 0; i < count; i++) { await p.screenshot({ path: `${OUT}/${n}-${sfx}-f${String(i).padStart(2, "0")}.png` }); await p.waitForTimeout(gap); } console.log(n, "frames", count); };
await p.goto(BASE + "/dashboard/cyrus", { waitUntil: "networkidle" });
await p.waitForTimeout(1500);
const ta = p.getByLabel("Describe your mod");
await ta.click();
await ta.pressSequentially("A /shop command that opens a chest menu exactly like the picture: same title, items, prices and slots. Players start with 100 coins.", { delay: 6 });
await shot("01-typing");
await p.locator("input[type=file]").first().setInputFiles(["/root/agent-notes/cyrus-v2/proof/shop-mock.png"]);
await p.waitForTimeout(1500);
await shot("02-image");
await p.getByRole("button", { name: /Voice typing/ }).click(); await p.waitForTimeout(1300); await shot("03-listening");
await p.getByRole("button", { name: /Stop voice typing|Voice typing/ }).first().click().catch(() => {});
await p.waitForTimeout(400);
await p.locator(".cy-pick").filter({ hasText: /Saka|Katara|Yakko/ }).first().click(); await p.waitForTimeout(500); await shot("04-model");
await p.getByRole("option", { name: /Katara/ }).click();
await p.locator(".cy-pick").filter({ hasText: "Minecraft" }).first().click(); await p.waitForTimeout(500); await shot("05-game");
await p.keyboard.press("Escape");
const go = p.getByRole("button", { name: /^Build$/ });
if (await go.isDisabled()) { console.log("build disabled (two running)"); }
await go.click();
await frames("06-fly", 8, 110);
await p.waitForURL(/\/dashboard\/cyrus\/mb/, { timeout: 20000 }).catch(() => errs.push("no nav"));
await p.waitForTimeout(2500); await shot("07-planning");
await p.waitForTimeout(4000); await frames("08-coding", 6, 400);
await p.waitForTimeout(6000); await shot("09-coding-late");
await p.waitForSelector(".cy-pill.st-succeeded", { timeout: 120000 }).catch(() => errs.push("no success"));
await frames("10-bloom", 5, 200);
await p.waitForTimeout(1500); await shot("11-done");
console.log(p.url(), errs.join(" | ").slice(0, 800));
await b.close();

