// REAL build through the local Cyrus UI against the real build service (0.4 on VM 88001):
// prompt that depends on the attached image + live code frames. Throwaway DB.
import { createRequire } from "node:module";
import { readFileSync, mkdirSync, writeFileSync } from "node:fs";
const require = createRequire("/opt/nxeon/node_modules/");
const { chromium } = require("playwright");
const tok = JSON.parse(readFileSync("/tank/nxeon-wt-cyrus/.cyrus-local/tokens.json", "utf8"));
const BASE = "http://localhost:3149";
const OUT = "/root/agent-notes/cyrus-v2/proof/ui"; mkdirSync(OUT, { recursive: true });
const b = await chromium.launch();
const ctx = await b.newContext({ viewport: { width: 1440, height: 900 }, colorScheme: "dark" });
await ctx.addCookies([{ name: tok.cookie, value: tok.ownerTok, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
const p = await ctx.newPage();
await p.addInitScript(() => { localStorage.setItem("nx-theme", "dark"); localStorage.setItem("nx-tour-dismissed", "1"); });
const errs = []; p.on("pageerror", (e) => errs.push(String(e)));
const liveLog = [];
p.on("response", async (r) => { if (r.url().includes("/live")) { try { const j = await r.json(); liveLog.push({ t: Date.now(), status: j.status, files: (j.files || []).length, draft: j.draft ? { path: j.draft.path, from: j.draft.from, got: j.draft.text.length, total: j.draft.total, done: j.draft.done } : null }); } catch {} } });
await p.goto(BASE + "/dashboard/cyrus", { waitUntil: "networkidle" });
await p.waitForTimeout(2000);
const ta = p.getByLabel("Describe your mod");
await ta.click();
await ta.fill("A /shop command that opens a chest menu built exactly like the attached picture: use the same menu title, the same items with the same amounts, the same prices and the same slots, and the same filler and close button. Every player starts with 100 coins (saved to disk), /coins shows the balance, and clicking an item buys it if they can afford it.");
await p.locator("input[type=file]").first().setInputFiles(["/root/agent-notes/cyrus-v2/proof/shop-mock.png"]);
await p.waitForTimeout(2500);
await p.screenshot({ path: `${OUT}/00-compose.png` });
await p.getByRole("button", { name: /^Build$/ }).click();
await p.waitForURL(/\/dashboard\/cyrus\/mb/, { timeout: 60000 });
const id = p.url().split("/").pop();
console.log("build", id);
let i = 0;
const t0 = Date.now();
while (Date.now() - t0 < 420000) {
  await p.waitForTimeout(2500);
  const st = await p.locator(".cy-pill").first().textContent().catch(() => "");
  if (i % 2 === 0 || /Writing/.test(st || "")) await p.screenshot({ path: `${OUT}/live-${String(i).padStart(3, "0")}.png` });
  i++;
  if (/Ready|Didn't build/.test(st || "")) break;
}
await p.waitForTimeout(2000);
await p.screenshot({ path: `${OUT}/zz-done.png` });
await p.getByRole("tab", { name: /^Code/ }).click().catch(() => {});
await p.waitForTimeout(1200);
await p.locator(".cy-tree-f", { hasText: "config.yml" }).first().click().catch(() => {});
await p.waitForTimeout(1500);
await p.screenshot({ path: `${OUT}/zz-config.png` });
await p.getByRole("tab", { name: /Explain|Request/ }).click().catch(() => {});
await p.waitForTimeout(1200);
await p.screenshot({ path: `${OUT}/zz-explain.png` });
writeFileSync(`${OUT}/live-responses.json`, JSON.stringify({ id, liveLog }, null, 1));
console.log("done", id, "live responses", liveLog.length, "with draft text", liveLog.filter((x) => x.draft && x.draft.got > 0).length, errs.join(" | ").slice(0, 400));
await b.close();

